INSERT INTO REGRAS_SISTEMA (CATEGORIA, CHAVE, DADOS) VALUES
('CLASSE', 'Bardo', '{"dominios":["Códice","Graça"],"subclasses":["Beletrista","Trovador"],"evasao":10,"pv":6,"esperanca":2,"habilidadeNome":"Inspiração de Bardo","habilidade":"Inspiração: Uma vez por sessão, descreva como você inspira o grupo e forneça a você e seus aliados um Dado de Inspiração (d6 no Nv 1, d8 no Nv 5, d10 no Nv 8). Um personagem pode rolar o Dado de Inspiração e somar o resultado a um teste, reação, rolagem de dano ou para recuperar um número de PF igual ao resultado."}'),
('CLASSE', 'Druida', '{"dominios":["Arcano","Sabedoria"],"subclasses":["Protetor dos elementos","Protetor da renovação"],"evasao":10,"pv":6,"esperanca":2,"habilidadeNome":"Forma de Fera","habilidade":"Forma de Fera: Marque 1 Ponto de Fadiga para se transformar magicamente em uma criatura da lista de Formas de Fera (até seu patamar). Você pode sair dessa forma a qualquer momento. Seus ataques usam as armas naturais da fera e concedem habilidades exclusivas de locomoção e percepção."}'),
('CLASSE', 'Feiticeiro', '{"dominios":["Arcano","Meia-noite"],"subclasses":["Elementalista","Primordialista"],"evasao":10,"pv":6,"esperanca":2,"habilidadeNome":"Sentido Arcano & Ilusão Menor","habilidade":"Sentido Arcano & Ilusão Menor: Você pode sentir a presença de magia próxima. Além disso, faça um teste de conjuração (10) para manifestar uma ilusão visual sensorial em alcance próximo sem gastar recursos."}'),
('CLASSE', 'Guardião', '{"dominios":["Valor","Lâmina"],"subclasses":["Baluarte","Vingador"],"evasao":9,"pv":7,"esperanca":2,"habilidadeNome":"Determinação Inabalável","habilidade":"Determinação: Uma vez por descanso longo, receba um Dado de Determinação (d4 no Nv 1). Após causar dano a um alvo tirando PV, aumente o valor do dado. Você pode gastar o dado para reduzir dano sofrido ou somar a um ataque devastador."}'),
('CLASSE', 'Guerreiro', '{"dominios":["Falange","Lâmina"],"subclasses":["Escolhido da bravura","Escolhido da matança"],"evasao":11,"pv":6,"esperanca":2,"habilidadeNome":"Ataque de Oportunidade","habilidade":"Ataque de Oportunidade: Se um adversário corpo a corpo tentar sair do seu alcance, faça um teste de reação contra a Dificuldade dele. Em um sucesso, impeça o movimento ou cause dano igual ao dano da sua arma principal."}'),
('CLASSE', 'Ladino', '{"dominios":["Graça","Meia-noite"],"subclasses":["Gatuno","Mafioso"],"evasao":12,"pv":6,"esperanca":2,"habilidadeNome":"Oculto & Ataque Furtivo","habilidade":"Oculto & Ataque Furtivo: Sempre que estiver Escondido, você fica Oculto (permanece invisível mesmo que o adversário se mova para onde normalmente o veria). Cause dados de dano adicionais ao desferir ataques contra alvos desatentos ou vulneráveis."}'),
('CLASSE', 'Mago', '{"dominios":["Códice","Esplendor"],"subclasses":["Discípulo do conhecimento","Discípulo da guerra"],"evasao":11,"pv":5,"esperanca":2,"habilidadeNome":"Padrões Estranhos & Prestidigitação","habilidade":"Padrões Estranhos & Prestidigitação: Escolha um número de 1 a 12. Ao rolar esse número em um Dado de Esperança, ganhe 1 Esperança ou recupere 1 PF imediatamente. Você também pode conjurar efeitos mágicos sensoriais menores e truques inofensivos à vontade."}'),
('CLASSE', 'Patrulheiro', '{"dominios":["Falange","Sabedoria"],"subclasses":["Rastreador","Treinador"],"evasao":10,"pv":6,"esperanca":2,"habilidadeNome":"Marca da Presa","habilidade":"Marca da Presa: Gaste 1 Ponto de Esperança e ataque um alvo para Marcá-lo. Você sabe precisamente a direção e distância da criatura marcada e causa dados adicionais de dano contra ela em todos os ataques."}'),
('CLASSE', 'Serafim', '{"dominios":["Valor","Esplendor"],"subclasses":["Portador divino","Sentinela alada"],"evasao":9,"pv":6,"esperanca":2,"habilidadeNome":"Dados de Oração","habilidade":"Dados de Oração: No início de cada sessão, role uma quantidade de d4s igual ao seu atributo de conjuração. Você pode gastar qualquer número de Dados de Oração para somar a testes, dano ou curar ferimentos de você ou aliados até alcance distante."}'),
('SUBCLASSE', 'Trovador', '{"classe":"Bardo","conjuracao":"Presença","nome":"Trovador","habilidadeNome":"Artista Talentoso","habilidade":"Artista Talentoso (Presença): Descreva como se apresenta. Cante, toque ou recite para inspirar. Você pode se apresentar durante um descanso para recuperar Esperança adicional para o grupo ou usar sua melodia para acalmar ânimos hostis."}'),
('SUBCLASSE', 'Beletrista', '{"classe":"Bardo","conjuracao":"Presença","nome":"Beletrista","habilidadeNome":"Discurso Inspirador","habilidade":"Discurso Inspirador (Presença): Uma vez por descanso longo, faça um discurso emocionante. Aliados que o ouvirem ganham um bônus especial no próximo teste e recuperam 1 Ponto de Fadiga."}'),
('SUBCLASSE', 'Protetor dos elementos', '{"classe":"Druida","conjuracao":"Instinto","nome":"Protetor dos elementos","habilidadeNome":"Encarnação Elemental","habilidade":"Encarnação Elemental (Instinto): Marque 1 PF para canalizar um elemento (Água, Fogo, Terra ou Vento) até sofrer dano grave. Enquanto canalizado, seus ataques corpo a corpo causam dano do elemento escolhido e você ganha resistência associada."}'),
('SUBCLASSE', 'Protetor da renovação', '{"classe":"Druida","conjuracao":"Instinto","nome":"Protetor da renovação","habilidadeNome":"Serenidade da Natureza","habilidade":"Serenidade da Natureza (Instinto): Uma vez por descanso longo, crie um santuário de serenidade natural. Aliados que descansarem nele recuperam 1 PV e 1 PF adicionais e limpam condições negativas."}'),
('SUBCLASSE', 'Elementalista', '{"classe":"Feiticeiro","conjuracao":"Instinto","nome":"Elementalista","habilidadeNome":"Poder Primordial dos Elementos","habilidade":"Poder Primordial Elemental (Instinto): Escolha um elemento de afinidade (Água, Ar, Fogo, Relâmpago ou Terra). Seus feitiços desse elemento causam dano ampliado e você pode gastar 1 Esperança para dobrar o alcance ou área de impacto."}'),
('SUBCLASSE', 'Primordialista', '{"classe":"Feiticeiro","conjuracao":"Instinto","nome":"Primordialista","habilidadeNome":"Manipular Magia","habilidade":"Manipular Magia (Instinto): Sua herança primordial permite alterar a essência da magia. Ao conjurar feitiços, você pode marcar 1 PF para converter tipos de dano mágico ou transmutar seus efeitos."}'),
('SUBCLASSE', 'Baluarte', '{"classe":"Guardião","conjuracao":"Nenhum","nome":"Baluarte","habilidadeNome":"Resoluto & Vontade de Ferro","habilidade":"Resoluto & Vontade de Ferro: Você recebe um bônus permanente de +1 em seus limiares de dano. Ao sofrer dano físico, você pode marcar 1 PF para reduzir a severidade do dano em sua armadura ativa."}'),
('SUBCLASSE', 'Vingador', '{"classe":"Guardião","conjuracao":"Nenhum","nome":"Vingador","habilidadeNome":"Vem Tranquilo & Revanche","habilidade":"Vem Tranquilo & Revanche: Receba +1 Ponto de Fadiga máximo adicional. Quando um adversário corpo a corpo acertar um ataque contra você, marque 1 PF para desferir um contra-ataque de retaliação imediato."}'),
('SUBCLASSE', 'Escolhido da bravura', '{"classe":"Guerreiro","conjuracao":"Nenhum","nome":"Escolhido da bravura","habilidadeNome":"Coragem & Ritual de Batalha","habilidade":"Coragem & Ritual de Batalha: Ao falhar com Medo, receba 1 Ponto de Esperança. Uma vez por descanso longo, execute um ritual marcial para receber bônus de combate e liderança na próxima batalha."}'),
('SUBCLASSE', 'Escolhido da matança', '{"classe":"Guerreiro","conjuracao":"Nenhum","nome":"Escolhido da matança","habilidadeNome":"Frenesi da Matança","habilidade":"Frenesi da Matança: Ao rolar com Esperança durante ataques, você pode acumular um d6 de Frenesi nesta carta em vez de pegar Esperança. Gaste esses dados para adicionar dano maciço aos seus golpes."}'),
('SUBCLASSE', 'Gatuno', '{"classe":"Ladino","conjuracao":"Acuidade","nome":"Gatuno","habilidadeNome":"Passo Sombrio","habilidade":"Passo Sombrio (Acuidade): Salte de uma sombra para outra instantaneamente. Ao entrar em área de escuridão ou penumbra, você pode se teletransportar para outra sombra no alcance próximo sem provocar ataques."}'),
('SUBCLASSE', 'Mafioso', '{"classe":"Ladino","conjuracao":"Acuidade","nome":"Mafioso","habilidadeNome":"Conexões Criminosas","habilidade":"Conexões Criminosas (Acuidade): Em qualquer cidade ou povoado, você conhece contatos influentes do submundo. Gaste 1 Esperança para obter abrigo seguro, rotas de fuga ou segredos dos poderosos."}'),
('SUBCLASSE', 'Discípulo do conhecimento', '{"classe":"Mago","conjuracao":"Conhecimento","nome":"Discípulo do conhecimento","habilidadeNome":"Estudo Promissor","habilidade":"Estudo Promissor (Conhecimento): Você desvenda fórmulas arcanas raras. Pegue 1 carta de domínio adicional de nível igual ou inferior ao seu de qualquer um dos seus domínios."}'),
('SUBCLASSE', 'Discípulo da guerra', '{"classe":"Mago","conjuracao":"Conhecimento","nome":"Discípulo da guerra","habilidadeNome":"Mago de Batalha","habilidade":"Mago de Batalha (Conhecimento): Concentre seus estudos nas artes bélicas. Ao atacar com armas corpo a corpo, você pode canalizar Conhecimento e infundir seus golpes com dano arcano puro."}'),
('SUBCLASSE', 'Rastreador', '{"classe":"Patrulheiro","conjuracao":"Agilidade","nome":"Rastreador","habilidadeNome":"Predador Implacável","habilidade":"Predador Implacável (Agilidade): Ao fazer rolagem de dano contra um alvo que você esteja rastreando ou Marcado, marque 1 PF para rerrolar qualquer quantidade de dados de dano."}'),
('SUBCLASSE', 'Treinador', '{"classe":"Patrulheiro","conjuracao":"Agilidade","nome":"Treinador","habilidadeNome":"Companheiro Animal","habilidade":"Companheiro Animal (Agilidade): Você tem um parceiro animal leal (lobo, falcão, felino, urso, etc.). Ele se desloca com você, ataca alvos coordenados e pode interceptar perigos para o grupo."}'),
('SUBCLASSE', 'Portador divino', '{"classe":"Serafim","conjuracao":"Força","nome":"Portador divino","habilidadeNome":"Arma Espiritual & Toque Piedoso","habilidade":"Arma Espiritual (Força): Sua arma corpo a corpo voa até o alcance próximo para golpear adversários e retorna à sua mão. Marque 1 PF para atingir um alvo adicional. Uma vez por descanso longo, use Toque Piedoso para curar ferimentos graves."}'),
('SUBCLASSE', 'Sentinela alada', '{"classe":"Serafim","conjuracao":"Força","nome":"Sentinela alada","habilidadeNome":"Asas de Luz","habilidade":"Asas de Luz (Força): Manifeste asas radiantes. Enquanto voa, você pode marcar 1 PF para erguer e carregar um aliado voluntário ou gastar 1 Ponto de Esperança para causar +1d8 de dano sagrado em ataques aéreos."}'),
('ANCESTRALIDADE', 'Anão', '{"nome":"Anão","descricao":"Anões são conhecidos como humanoides baixos com tipo corporal quadrado, musculatura densa e cabelo espesso.","poderes":[{"id":"anao_1","nome":"Pele Espessa","desc":"Quando sofre dano menor, você pode marcar 2 Pontos de Fadiga em vez de marcar 1 Ponto de Vida."},{"id":"anao_2","nome":"Vigoroso","desc":"Gaste 3 Pontos de Esperança para reduzir à metade o dano físico sofrido."}]}'),
('ANCESTRALIDADE', 'Clank', '{"nome":"Clank","descricao":"Clanks são seres mecânicos sencientes, construídos de uma variedade de materiais, como madeira, metal e pedra.","poderes":[{"id":"clank_1","nome":"Projeto Intencional","desc":"Escolha uma de suas Experiências alinhada ao propósito de sua criação e receba um bônus permanente de +1 nela."},{"id":"clank_2","nome":"Eficiente","desc":"Ao fazer um descanso curto, você pode escolher um movimento de descanso longo em vez de um de descanso curto."}]}'),
('ANCESTRALIDADE', 'Drakona', '{"nome":"Drakona","descricao":"Drakonas lembram dragões humanoides sem asas, com escamas rígidas e um poderoso sopro elemental.","poderes":[{"id":"drakona_1","nome":"Escamas","desc":"Quando sofrer dano grave, você pode marcar 1 Ponto de Fadiga para marcar 1 PV a menos."},{"id":"drakona_2","nome":"Sopro Elemental","desc":"Use seu sopro contra alvo ou grupo muito próximo como arma de Instinto causando d8 de dano mágico com sua Proficiência."}]}'),
('ANCESTRALIDADE', 'Elfo', '{"nome":"Elfo","descricao":"Elfos são humanoides altos, com orelhas pontudas, sentidos hiperapurados e conexão celestial.","poderes":[{"id":"elfo_1","nome":"Reação Rápida","desc":"Marque 1 Ponto de Fadiga para receber vantagem em um teste de reação."},{"id":"elfo_2","nome":"Transe Celestial","desc":"Durante um descanso, você pode entrar em transe celestial para escolher um movimento de repouso adicional."}]}'),
('ANCESTRALIDADE', 'Fada', '{"nome":"Fada","descricao":"Fadas são humanoides alados com traços insetoides, asas translúcidas e magia cintilante.","poderes":[{"id":"fada_1","nome":"Testar a Sorte","desc":"Uma vez por sessão, após você ou um aliado voluntário próximo fazer um teste, gaste 3 Pontos de Esperança para rolar novamente os Dados de Dualidade."},{"id":"fada_2","nome":"Asas","desc":"Você pode voar. Enquanto voa e após um adversário atacar você, marque 1 PF para receber +2 na Evasão contra o ataque."}]}'),
('ANCESTRALIDADE', 'Fauno', '{"nome":"Fauno","descricao":"Faunos lembram cabras humanoides, com cascos fendidos, chifres curvados e agilidade acrobática.","poderes":[{"id":"fauno_1","nome":"Salto Caprino","desc":"Você pode saltar para qualquer ponto no alcance próximo como movimento normal, transpondo obstáculos e fendas facilmente."},{"id":"fauno_2","nome":"Coice","desc":"Ao acertar ataque corpo a corpo, marque 1 PF para dar um coice causando +2d6 de dano e empurrando o adversário ou a si mesmo."}]}'),
('ANCESTRALIDADE', 'Firbolg', '{"nome":"Firbolg","descricao":"Firbolgs são humanoides imponentes com características bovinas, focinho largo e ligação serena com a terra.","poderes":[{"id":"firbolg_1","nome":"Investida","desc":"Ao obter sucesso em teste de Agilidade para se mover de longe para corpo a corpo, marque 1 PF para causar 1d12 de dano físico a todos os alvos corpo a corpo."},{"id":"firbolg_2","nome":"Inabalável","desc":"Quando for marcar 1 Ponto de Fadiga, role 1d6. Se tirar 6, não o marque."}]}'),
('ANCESTRALIDADE', 'Fungril', '{"nome":"Fungril","descricao":"Fungris parecem cogumelos humanoides conectados à rede micelial e aos ciclos da vida e morte.","poderes":[{"id":"fungril_1","nome":"Conexão Fungril","desc":"Faça teste de Instinto (12) para conversar com outros membros de sua ancestralidade por meio da rede micelial a qualquer distância."},{"id":"fungril_2","nome":"Vínculo Mortal","desc":"Enquanto toca um cadáver recente, marque 1 PF para extrair dele uma memória relacionada a uma emoção ou sensação escolhida."}]}'),
('ANCESTRALIDADE', 'Galapa', '{"nome":"Galapa","descricao":"Galapas lembram tartarugas antropomórficas, com carapaças largas e arredondadas e grande sabedoria.","poderes":[{"id":"galapa_1","nome":"Carapaça","desc":"Você recebe um bônus permanente nos seus limiares de dano igual à sua Proficiência."},{"id":"galapa_2","nome":"Retração","desc":"Marque 1 PF para entrar na carapaça: recebe resistência a dano físico, desvantagem em testes e não pode se mover."}]}'),
('ANCESTRALIDADE', 'Gigante', '{"nome":"Gigante","descricao":"Gigantes são humanoides descomunais, com ombros largos, enorme musculatura e até três olhos.","poderes":[{"id":"gigante_1","nome":"Resistência Colossal","desc":"Receba +1 Ponto de Vida máximo adicional permanentemente na criação."},{"id":"gigante_2","nome":"Alcance Alongado","desc":"Trate qualquer arma, talento, magia ou habilidade com alcance corpo a corpo como se tivesse alcance muito próximo."}]}'),
('ANCESTRALIDADE', 'Goblin', '{"nome":"Goblin","descricao":"Goblins são humanoides pequenos e astutos com orelhas membranosas e reflexos rápidos.","poderes":[{"id":"goblin_1","nome":"Passo Firme","desc":"Você ignora desvantagem em testes de Agilidade."},{"id":"goblin_2","nome":"Cheiro de Perigo","desc":"Uma vez por descanso, marque 1 PF para forçar um adversário a rerrolar um teste de ataque contra você ou aliado muito próximo."}]}'),
('ANCESTRALIDADE', 'Humano', '{"nome":"Humano","descricao":"Humanos são adaptáveis, resilientes e habilidosos, com tenacidade inabalável em situações extremas.","poderes":[{"id":"humano_1","nome":"Resiliência","desc":"Receba 1 Ponto de Fadiga máximo adicional permanentemente na criação de personagem."},{"id":"humano_2","nome":"Adaptabilidade","desc":"Ao falhar em teste que usou uma de suas Experiências, marque 1 PF para rolar novamente o teste."}]}'),
('ANCESTRALIDADE', 'Infernis', '{"nome":"Infernis","descricao":"Infernis descendem de linhagens demoníacas, portando chifres, caninos afiados e presença imponente.","poderes":[{"id":"infernis_1","nome":"Destemido","desc":"Quando rolar com Medo, você pode marcar 2 Pontos de Fadiga para rolar com Esperança em vez disso."},{"id":"infernis_2","nome":"Aspecto Apavorante","desc":"Você tem vantagem em testes para intimidar criaturas hostis."}]}'),
('ANCESTRALIDADE', 'Katari', '{"nome":"Katari","descricao":"Kataris são humanoides felinos com garras retráteis, pupilas verticais e sentidos caçadores.","poderes":[{"id":"katari_1","nome":"Instinto Felino","desc":"Em testes de Agilidade, você pode gastar 2 Pontos de Esperança para rolar seu Dado de Esperança novamente."},{"id":"katari_2","nome":"Garras Retráteis","desc":"Ataque corpo a corpo com Agilidade; em um sucesso, o alvo fica temporariamente Vulnerável."}]}'),
('ANCESTRALIDADE', 'Orc', '{"nome":"Orc","descricao":"Orcs são guerreiros honoráveis e imponentes com presas mandibulares e robustez indomável.","poderes":[{"id":"orc_1","nome":"Robusto","desc":"Quando tiver apenas 1 Ponto de Vida restante, todos os testes de ataque contra você sofrem desvantagem."},{"id":"orc_2","nome":"Presas","desc":"Ao acertar um ataque corpo a corpo, gaste 1 Ponto de Esperança para perfurar com as presas causando +1d6 de dano adicional."}]}'),
('ANCESTRALIDADE', 'Pequenino', '{"nome":"Pequenino","descricao":"Pequeninos são pequenos humanoides com pés aveludados, coração acolhedor e sorte lendária.","poderes":[{"id":"pequenino_1","nome":"Talismã da Sorte","desc":"No início de cada sessão, todos os membros do seu grupo recebem 1 Ponto de Esperança extra."},{"id":"pequenino_2","nome":"Senso de Direção","desc":"Ao tirar 1 no seu Dado de Esperança, você pode rolá-lo novamente imediatamente."}]}'),
('ANCESTRALIDADE', 'Quacho', '{"nome":"Quacho","descricao":"Quachos lembram anfíbios sapóides com olhos protuberantes, pés palmados e língua extensível.","poderes":[{"id":"quacho_1","nome":"Anfíbio","desc":"Você pode respirar debaixo dágua e nadar naturalmente com sua velocidade normal."},{"id":"quacho_2","nome":"Linguarudo","desc":"Pode agarrar objetos distantes. Marque 1 PF para atacar com a língua como arma de Acuidade (alcance próximo) causando d12 físico com Proficiência."}]}'),
('ANCESTRALIDADE', 'Símio', '{"nome":"Símio","descricao":"Símios são primatas antropomórficos de membros longos, pés preênseis e agilidade ímpar.","poderes":[{"id":"simio_1","nome":"Escalador Natural","desc":"Você tem vantagem em testes de Agilidade envolvendo equilíbrio, acrobacia e escalada."},{"id":"simio_2","nome":"Ágil","desc":"Você recebe um bônus permanente de +1 na Evasão durante a criação de personagem."}]}'),
('COMUNIDADE', 'Aristocrática', '{"nome":"Aristocrática","descricao":"Integrar uma comunidade aristocrática significa que você está acostumado a uma vida de elegância, opulência e prestígio na alta sociedade.","habilidadeNome":"Privilégio","habilidade":"Privilégio: Você tem vantagem em testes para se relacionar com nobres, negociar preços ou se aproveitar de sua reputação para conseguir o que quer."}'),
('COMUNIDADE', 'Erudita', '{"nome":"Erudita","descricao":"Integrar uma comunidade erudita significa que você vem de uma sociedade que favorece grandes feitos acadêmicos, arcanos ou políticos.","habilidadeNome":"Culto","habilidade":"Culto: Você tem vantagem em testes que envolvem cultura, história, mistérios arcanos ou política de um lugar ou pessoa importante."}'),
('COMUNIDADE', 'Disciplinada', '{"nome":"Disciplinada","descricao":"Integrar uma comunidade disciplinada significa que você vem de um povo focado em virtude, ordem marcial ou fé inabalável.","habilidadeNome":"Princípios","habilidade":"Princípios: Anote três ditados ou valores com os quais cresceu. Uma vez por descanso, ao incorporar um destes princípios no seu movimento, jogue 1d20 como seu Dado de Esperança."}'),
('COMUNIDADE', 'Montanhesa', '{"nome":"Montanhesa","descricao":"Integrar uma comunidade montanhesa significa que você chama os picos escarpados e penhascos de lar.","habilidadeNome":"Firme","habilidade":"Firme: Você tem vantagem em testes para cruzar abismos e saliências, orientar-se em altitudes e ambientes inóspitos e usar técnicas de sobrevivência."}'),
('COMUNIDADE', 'Marítima', '{"nome":"Marítima","descricao":"Integrar uma comunidade marítima significa que você já viveu próximo ou navegando em um grande corpo dágua.","habilidadeNome":"Conhecer a Maré","habilidade":"Conhecer a Maré: Ao rolar com Medo, coloque 1 marcador de maré nesta carta (máx. igual ao seu nível). Antes de qualquer teste, gaste marcadores para receber +1 de bônus por marcador gasto."}'),
('COMUNIDADE', 'Fora da Lei', '{"nome":"Fora da Lei","descricao":"Integrar estas comunidades significa que você vem de um meio que age às margens da lei, cercado por foras da lei, contrabandistas e rebeldes.","habilidadeNome":"Malandro","habilidade":"Malandro: Você tem vantagem em testes para negociar com criminosos, farejar traições, perceber mentiras ou encontrar um esconderijo seguro."}'),
('COMUNIDADE', 'Subterrânea', '{"nome":"Subterrânea","descricao":"Integrar uma comunidade subterrânea significa que você cresceu abaixo da superfície, em galerias e cidades de pedra.","habilidadeNome":"Habituado à Penumbra","habilidade":"Habituado à Penumbra: Você tem vantagem em testes para se esconder, investigar, farejar ou perceber detalhes em áreas de penumbra ou sombra forte."}'),
('COMUNIDADE', 'Nômade', '{"nome":"Nômade","descricao":"Integrar uma comunidade nômade significa que você vive viajando, renunciando a um lar fixo e conhecendo diversas terras.","habilidadeNome":"Mochila de Nômade","habilidade":"Mochila de Nômade: Adicione uma mochila de nômade ao seu inventário. Uma vez por sessão, gaste 1 Ponto de Esperança para tirar dela um item mundano providencial para a situação atual."}'),
('COMUNIDADE', 'Silvestre', '{"nome":"Silvestre","descricao":"Integrar uma comunidade silvestre significa que você viveu no coração das matas e florestas ancestrais.","habilidadeNome":"Pés Leves","habilidade":"Pés Leves: Seu movimento é naturalmente silencioso. Você tem vantagem em testes para se mover furtivamente sem ser ouvido."}');
INSERT INTO CARTAS_DOMINIO (ID, NOME, DOMINIO, NIVEL, CUSTO_RETORNO, TIPO, DESCRICAO) VALUES
(82, 'Proteção Rúnica', 'Arcano', 1, 0, 'Feitiço', 'Você tem um talismã pessoal que pode ser infundido com magia protetora e usado por você ou por um aliado. Descreva o que esse item é e por que ele é importante para você. O portador da proteção pode gastar 1 Ponto de Esperança para reduzir o dano sofrido em 1d8. Se tirar 8 nesse dado, o poder da Proteção Rúnica se encerra após reduzir dano neste turno. Ela pode ser recarregada sem custo no seu próximo descanso.'),
(83, 'Caos Liberto', 'Arcano', 1, 1, 'Feitiço', 'No início da sessão, coloque um número de marcadores igual ao seu atributo de conjuração nesta carta. Faça um teste de conjuração contra um alvo distante e gaste qualquer número de marcadores para canalizar energia bruta de seu interior e liberá-la contra ele. Em um sucesso, role uma quantidade de d10 igual ao número de marcadores que gastou e cause o resultado deles como dano mágico ao alvo. Marque 1 Ponto de Fadiga para recarregar esta carta com marcadores (até uma quantidade igual ao seu atributo de conjuração). No fim de cada sessão, marcadores não utilizados são perdidos.'),
(84, 'Caminhar na Parede', 'Arcano', 1, 1, 'Feitiço', 'Gaste 1 Ponto de Esperança: uma criatura tocada por você pode escalar paredes e tetos como se estivesse caminhando em terra firme. Esse efeito dura até o fim da cena ou até você conjurar Caminhar na Parede novamente.'),
(85, 'Incendiar', 'Arcano', 2, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo corpo a corpo. Em um sucesso, o alvo instantaneamente irrompe em chamas, sofre 1d20+3 de dano mágico e fica temporariamente Em Chamas. Quando uma criatura Em Chamas age, ela sofre 2d6 de dano mágico adicional se ainda estiver Em Chamas no fim da ação dela.'),
(86, 'Olho Flutuante', 'Arcano', 2, 0, 'Feitiço', 'Gaste 1 Ponto de Esperança para criar um pequeno orbe flutuante que você pode mover para um ponto qualquer em alcance muito distante. Enquanto este feitiço estiver ativo, você pode ver pelo orbe como se estivesse onde ele está. Você pode escolher entre usar seus próprios sentidos ou os do orbe como quiser. Se o orbe sofrer dano ou sair do alcance, o feitiço termina.'),
(87, 'Contramágica', 'Arcano', 3, 2, 'Feitiço', 'Você pode interromper um efeito mágico em andamento fazendo um teste de reação com seu atributo de conjuração. Em um sucesso, o efeito termina, quaisquer consequências são evitadas e esta carta vai para sua reserva.'),
(88, 'Voo', 'Arcano', 3, 1, 'Feitiço', 'Faça um teste de conjuração (15). Em um sucesso, coloque um número de marcadores igual à sua Agilidade nesta carta (mínimo de 1). Ao fazer um teste enquanto estiver voando, gaste um marcador desta carta. Após terminar a ação que consumiu o último marcador, você desce para o solo diretamente abaixo de você.'),
(89, 'Translocação', 'Arcano', 4, 1, 'Feitiço', 'Faça um teste de conjuração (12). Em um sucesso, gaste 1 Ponto de Esperança para se teleportar a um ponto que você possa ver em alcance distante. Se houver criaturas voluntárias Muito Próximas, gaste 1 Ponto de Esperança adicional para cada criatura que quiser levar consigo.'),
(90, 'Impacto Defensivo', 'Arcano', 4, 2, 'Feitiço', 'Faça um teste de conjuração contra todos os alvos corpo a corpo. Alvos atingidos são empurrados para um ponto qualquer em alcance distante e sofrem d8+3 de dano mágico usando seu atributo de conjuração.'),
(91, 'Corrente de Relâmpagos', 'Arcano', 5, 1, 'Feitiço', 'Marque 2 Pontos de Fadiga para fazer um teste de conjuração e liberar relâmpagos em cadeia contra todos os alvos próximos. Alvos atingidos devem fazer um teste de reação com Dificuldade igual ao resultado de seu teste de conjuração. Se falharem, sofrem 2d8+4 de dano mágico. Adversários adicionais que não tenham sido alvo da Corrente de Relâmpagos e estejam próximos dos alvos que sofreram dano também devem fazer um teste de reação. Se falharem, sofrem 2d8+4 de dano mágico. A corrente continua até não haver mais adversários no alcance.'),
(92, 'Premonição', 'Arcano', 5, 2, 'Feitiço', 'Você pode canalizar energia arcana para ter visões do futuro. Uma vez por descanso longo, imediatamente após o mestre apresentar as consequências de um teste que você fez, você pode ignorar esse movimento e suas consequências como se elas não tivessem acontecido e fazer outro movimento no lugar.'),
(93, 'Fenda Espacial', 'Arcano', 6, 2, 'Feitiço', 'Faça um teste de conjuração (15). Em um sucesso, você faz uma marca arcana no solo onde está no momento. Na próxima vez que você conjurar Fenda Espacial, abre-se um portal que fornece passagem segura para o ponto exato onde a marca foi colocada. A fenda permanece aberta até você fechá-la ou até conjurar outro feitiço. Você pode cancelar o feitiço a qualquer momento para conjurar Fenda Espacial novamente e marcar outro lugar.'),
(94, 'Telecinese', 'Arcano', 6, 0, 'Feitiço', 'Faça um teste de conjuração contra um alvo distante. Em um sucesso, você pode usar sua mente para movê-lo para um ponto qualquer em alcance distante relativo à posição inicial dele. Você também pode arremessá-lo como um ataque, fazendo um teste de conjuração adicional contra o alvo desse ataque. Em um sucesso, você causa d12+4 de dano físico ao segundo alvo com sua Proficiência. Depois disso, o feitiço acaba.'),
(95, 'Dom Arcano', 'Arcano', 7, 2, 'Feitiço', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio Arcano, receba os seguintes benefícios: • Bônus de +1 em testes de conjuração; • Uma vez por descanso, você pode trocar os resultados dos Dados de Esperança e Medo um pelo outro.'),
(96, 'Ocultação', 'Arcano', 7, 2, 'Feitiço', 'Ao ter sucesso em um teste de conjuração para conjurar um feitiço diferente, você pode gastar 1 Ponto de Esperança para ficar Oculto. Enquanto estiver Oculto, quando um adversário se movimentar para um lugar de onde normalmente veria você, ele não pode vê-lo se você estiver parado. Ao entrar ou se movimentar dentro da linha de visão de um adversário, ou ao atacar, você deixa de estar Oculto.'),
(97, 'Reflexo Arcano', 'Arcano', 8, 1, 'Feitiço', 'Quando for sofrer dano mágico, você pode gastar qualquer quantidade de Pontos de Esperança e rolar um número equivalente de d6. Se tirar 6 em qualquer um desses dados, o ataque é refletido e, em vez de causar dano a você, causa dano ao atacante.'),
(98, 'Aura de Confusão', 'Arcano', 8, 2, 'Feitiço', 'Faça um teste de conjuração (14). Uma vez por descanso longo, em um sucesso, você cria uma camada ilusória sobre seu corpo, que torna difícil distinguir exatamente onde você está. Marque um número qualquer de Pontos de Fadiga e crie uma quantidade de camadas igual aos PF marcados. Quando um adversário ataca você, role um número de d6 igual à quantidade de camadas que tem no momento. Se tirar 5 ou mais em qualquer dado, uma camada da aura é destruída e o ataque falha. Se todos os resultados forem 4 ou menos, você sofre o dano e o feitiço termina.'),
(99, 'Terremoto', 'Arcano', 9, 2, 'Feitiço', 'Faça um teste de conjuração (16). Uma vez por descanso, em um sucesso, todos os alvos Muito distantes que não estiverem voando devem fazer um teste de reação (18). Quem falhar sofre 3d10+8 de dano físico e fica temporariamente Vulnerável. Quem passar sofre metade do dano. Além disso, quando você tem sucesso no teste de conjuração, o terreno dentro do alcance muito distante torna-se difícil e as estruturas dentro desse alcance podem ser danificadas ou desmoronar completamente.'),
(100, 'Projeção Sensorial', 'Arcano', 9, 0, 'Feitiço', 'Uma vez por descanso, faça um teste de conjuração (15). Em um sucesso, você entra numa visão que lhe permite ver e ouvir claramente qualquer lugar onde já esteve anteriormente, como se estivesse lá no momento. Você pode se mover livremente dentro da visão, sem sofrer as restrições físicas de ter um corpo material. Este feitiço não pode ser detectado por meios mágicos ou mundanos. Você sai da visão ao sofrer dano ou ao conjurar outra magia.'),
(101, 'Ajustar Realidade', 'Arcano', 10, 1, 'Feitiço', 'Quando você ou um aliado voluntário faz uma rolagem, você pode gastar 5 Pontos de Esperança para mudar o resultado para um à sua escolha — ele deve ser plausível dentro das possibilidades fornecidas pelos dados.'),
(102, 'Chuva Arcana', 'Arcano', 10, 1, 'Feitiço', 'Faça um teste de conjuração contra todos os adversários distantes. Marque uma quantidade qualquer de Pontos de Fadiga para fazer chover fragmentos arcanos. Alvos atingidos sofrem 1d20+2 de dano mágico para cada PF marcado.'),
(103, 'Levante-Se', 'Lâmina', 1, 1, 'Talento', 'Ao sofrer dano grave, você pode marcar 1 Ponto de Fadiga para reduzir a gravidade em um limiar.'),
(104, 'Não o Suficiente', 'Lâmina', 1, 1, 'Talento', 'Ao rolar dados de dano, você pode rolar novamente quaisquer resultados 1 ou 2.'),
(105, 'Turbilhão', 'Lâmina', 1, 0, 'Talento', 'Quando acerta um ataque contra um alvo muito próximo, você pode gastar 1 Ponto de Esperança para usar este ataque contra todos os outros alvos muito próximos. Todos os adversários adicionais que você acertar ao usar este talento sofrem metade do dano.'),
(106, 'Fraternidade Marcial', 'Lâmina', 2, 1, 'Talento', 'Uma vez por descanso longo, ao elogiar ou perguntar algo que alguém faz bem, vocês recebem 3 Pontos de Esperança.'),
(107, 'Ataque Imprudente', 'Lâmina', 2, 1, 'Talento', 'Marque 1 Ponto de Fadiga para receber vantagem em um teste de ataque.'),
(108, 'Mexa-Se', 'Lâmina', 3, 1, 'Talento', 'Uma vez por descanso, quando uma criatura corpo a corpo for causar dano a você, você pode evitar o ataque e sair com segurança do alcance do inimigo.'),
(109, 'Versatilidade', 'Lâmina', 3, 1, 'Talento', 'Em vez de usar o atributo requerido por uma arma equipada, você pode usar um atributo diferente. Ao causar dano, você pode marcar 1 Ponto de Fadiga para usar o valor máximo de um de seus dados de dano.'),
(110, 'Concentração Mortal', 'Lâmina', 4, 2, 'Talento', 'Uma vez por descanso, você pode se concentrar totalmente em um alvo à sua escolha, recebendo um bônus de +1 em sua Proficiência. Esse bônus dura até você derrotar o alvo, atacar outra criatura ou a batalha terminar.'),
(111, 'Armadura Fortificada', 'Lâmina', 4, 0, 'Talento', 'Você recebe um bônus de +2 nos seus limiares de dano enquanto estiver usando armadura.'),
(112, 'Vantagem do Campeão', 'Lâmina', 5, 1, 'Talento', 'Ao ter sucesso crítico em um ataque, você pode gastar até 3 Pontos de Esperança e escolher uma das opções a seguir para cada Ponto de Esperança gasto dessa forma: • Você recupera 1 Ponto de Vida; • Você recupera 1 Ponto de Armadura; • O alvo deve marcar 1 PV adicional. Você não pode escolher a mesma opção mais de uma vez.'),
(113, 'Vitalidade', 'Lâmina', 5, 0, 'Talento', 'Ao escolher esta carta, receba dois destes benefícios permanentemente: • 1 PF adicional; • 1 PV adicional; • Bônus de +2 em seus limiares de dano. Em seguida, coloque esta carta na sua reserva permanentemente.'),
(114, 'Calejado Pela Batalha', 'Lâmina', 6, 2, 'Talento', 'Uma vez por descanso longo, quando for fazer um movimento de morte, você pode gastar 1 Ponto de Esperança para, em vez disso, recuperar 1 PV.'),
(115, 'Fúria', 'Lâmina', 6, 1, 'Talento', 'Antes de fazer um ataque, você pode marcar 1 Ponto de Fadiga para receber um bônus igual ao dobro de sua Força na rolagem de dano. Você pode ativar este talento duas vezes por ataque.'),
(116, 'Dom da Lâmina', 'Lâmina', 7, 1, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio da Lâmina, receba os seguintes benefícios: • Bônus de +2 em testes de ataque; • Bônus de +4 no seu limiar de dano grave.'),
(117, 'Golpe de Raspão', 'Lâmina', 7, 1, 'Talento', 'Quando erra um ataque, você pode marcar 1 Ponto de Fadiga para causar o dano da arma usando metade de sua Proficiência.'),
(118, 'Grito de Guerra', 'Lâmina', 8, 2, 'Talento', 'Uma vez por descanso longo, enquanto se lança rumo ao perigo, você pode emitir um grito de guerra que inspira seus aliados. Cada aliado capaz de ouvi-lo recupera 1 Ponto de Fadiga e ganha 1 Ponto de Esperança. Além disso, seus aliados fazem testes de ataque com vantagem até que você ou algum aliado role uma falha com Medo.'),
(119, 'Frenesi', 'Lâmina', 8, 3, 'Talento', 'Uma vez por descanso longo, você pode entrar Em Frenesi até que não haja mais adversários na sua linha de visão. Enquanto estiver Em Frenesi, você não pode usar PA, ganha um bônus de +10 em rolagens de dano e um bônus de +8 no seu limiar de dano grave.'),
(120, 'Guerra e Glória', 'Lâmina', 9, 2, 'Talento', 'Em um sucesso crítico ao atacar com uma arma, receba 1 Ponto de Esperança adicional ou recupere 1 Ponto de Fadiga adicional. Além disso, ao causar dano suficiente para derrotar um inimigo, receba 1 Ponto de Esperança ou recupere 1 PF.'),
(121, 'Golpe da Morte', 'Lâmina', 9, 3, 'Talento', 'Uma vez por descanso longo, gaste 1 Ponto de Esperança para fazer um teste de ataque. O mestre informa contra quais alvos no alcance da arma o teste teria sucesso. Escolha um desses alvos e force-o a marcar 5 PV.'),
(122, 'Monstro de Batalha', 'Lâmina', 10, 0, 'Talento', 'Ao acertar um ataque contra um adversário, em vez de rolar o dano, você pode marcar 4 Pontos de Fadiga para forçar o alvo a marcar um número de PV igual ao número de PV que você tem marcados no momento.'),
(123, 'Massacrar', 'Lâmina', 10, 3, 'Talento', 'Ao acertar um ataque com sua arma, você nunca causa dano abaixo do limiar de dano maior do alvo (ele sempre marca no mínimo 2 Pontos de Vida). Além disso, quando uma criatura no alcance da sua arma causa dano a um aliado com um ataque que não tem você como alvo, você pode marcar 1 PF para forçá-la a fazer um teste de reação (15). Se falhar, o alvo deve marcar 1 Ponto de Vida.'),
(124, 'Movimento Ligeiro', 'Falange', 1, 0, 'Talento', 'Uma vez por descanso, marque 1 PF para se deslocar para qualquer lugar em alcance distante sem precisar de um teste de Agilidade. Se terminar esse movimento em alcance corpo a corpo de um adversário e imediatamente atacá-lo, você ganha um bônus de +1 no teste de ataque.'),
(125, 'Um Passo à Frente', 'Falange', 1, 1, 'Talento', 'Quando você é alvo de um ataque originado de um ponto fora de alcance corpo a corpo, você pode marcar 1 Ponto de Fadiga para rolar 1d4 e receber um bônus igual ao resultado na sua Evasão contra este ataque.'),
(126, 'Intocável', 'Falange', 1, 1, 'Talento', 'Receba um bônus na Evasão igual à metade da sua Agilidade.'),
(127, 'Ferocidade', 'Falange', 2, 2, 'Talento', 'Ao fazer com que um adversário marque 1 ou mais Pontos de Vida, você pode gastar 2 Pontos de Esperança para aumentar sua Evasão em um número igual à quantidade de PV que ele marcou. Esse bônus dura até o término do próximo ataque feito contra você.'),
(128, 'Aproximação Estratégica', 'Falange', 2, 1, 'Talento', 'Após um descanso longo, coloque um número de marcadores igual ao seu Conhecimento nesta carta (mínimo de 1). Na primeira vez que você se mover para ficar próximo de um adversário e atacá-lo, você pode gastar um marcador para escolher uma das opções abaixo: • Você faz o ataque com vantagem; • Você recupera 1 Ponto de Fadiga de um aliado cac ao adversário; • Você soma 1d8 à rolagem de dano. Após um descanso longo, marcadores não utilizados são perdidos.'),
(129, 'Resistir', 'Falange', 3, 1, 'Talento', 'Ao marcar 1 Ponto de Armadura para reduzir o dano sofrido, você pode marcar 1 Ponto de Fadiga para marcar 1 Ponto de Armadura adicional.'),
(130, 'Táticas', 'Falange', 3, 1, 'Talento', 'Ao prestar ajuda a um aliado, você pode gastar 1 Ponto de Esperança para somar uma de suas Experiências à rolagem, junto ao seu dado de vantagem. Ao fazer um teste em dupla, você pode usar 1d20 como seu Dado de Esperança.'),
(131, 'Impulso', 'Falange', 4, 1, 'Talento', 'Marque 1 Ponto de Fadiga para usar um aliado próximo voluntário como impulso para se lançar no ar e fazer um ataque aéreo contra um alvo distante. Você tem vantagem no ataque, soma 1d10 à rolagem de dano e termina seu movimento corpo a corpo ao alvo.'),
(132, 'Redirecionar', 'Falange', 4, 1, 'Talento', 'Quando um ataque originado de um ponto além do alcance corpo a corpo falha contra você, role um número de d6 igual à sua Proficiência. Se tirar 6 em qualquer dado, você pode marcar 1 Ponto de Fadiga para redirecionar o ataque, fazendo-o causar dano a um adversário muito próximo.'),
(133, 'Conhece Teu Inimigo', 'Falange', 5, 1, 'Talento', 'Enquanto estiver observando uma criatura, você pode fazer um teste de Instinto contra ela. Em um sucesso, gaste 1 Ponto de Esperança e pergunte ao mestre uma das seguintes informações a respeito dela: • PV e PF restantes; • Dificuldade e limiares de dano; • Táticas e dados de dano padrão; • Habilidades e Experiências. Além disso, em um sucesso, você pode marcar 1 PF para fazer o mestre perder 1 Ponto de Medo.'),
(134, 'Golpe Pessoal', 'Falange', 5, 1, 'Talento', 'Você tem um golpe icônico de combate. Descreva-o e dê um nome a ele. Uma vez por descanso, ao utilizá-lo como parte de uma ação, você pode rolar 1d20 como seu Dado de Esperança. Em um sucesso, recupere 1 Ponto de Fadiga.'),
(135, 'Contra-Ataque Rápido', 'Falange', 6, 0, 'Talento', 'Quando um ataque originado de um ponto em alcance corpo a corpo falha contra você, você pode marcar 1 Ponto de Fadiga e aproveitar a oportunidade para causar o dano de uma de suas armas ativas ao atacante.'),
(136, 'Recuperação', 'Falange', 6, 1, 'Talento', 'Durante um descanso curto, você pode escolher um movimento de repouso de descanso longo. Você pode gastar 1 Ponto de Esperança para permitir que um aliado também faça isso.'),
(137, 'Dom da Falange', 'Falange', 7, 2, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio da Falange, receba os seguintes benefícios: • Bônus de +1 na Agilidade; • Uma vez por descanso, você pode gastar 3 Pontos de Esperança para fazer com que um ataque bem-sucedido contra você falhe.'),
(138, 'Acuidade Cruel', 'Falange', 7, 1, 'Talento', 'Ao acertar um ataque com uma arma, receba um bônus igual à sua Acuidade ou Agilidade na rolagem de dano.'),
(139, 'Golpe Debilitante', 'Falange', 8, 3, 'Talento', 'Ao acertar um ataque, você pode marcar 1 PF para fazer com que o próximo ataque bem-sucedido contra o mesmo alvo cause 2d12 de dano adicional.'),
(140, 'Amontoar', 'Falange', 8, 1, 'Talento', 'Faça um teste de Agilidade contra todos os alvos próximos. Gaste 1 Ponto de Esperança para mover os alvos que você acerta, bem como quaisquer aliados próximos voluntários, para outro ponto em alcance próximo.'),
(141, 'Quase Lá', 'Falange', 9, 1, 'Talento', 'Se tiver 2 PV ou menos desmarcados, você não sofre dano menor.'),
(142, 'Ataque Fragmentado', 'Falange', 9, 3, 'Talento', 'Gaste 1 Ponto de Esperança e faça um ataque contra todos os adversários no alcance de sua arma. Uma vez por descanso longo, em um sucesso contra qualquer um dos alvos, some todo o dano causado e em seguida o redistribua como quiser entre os alvos atingidos. Antes de causar dano a um alvo, role um dado de dano adicional e some o resultado dele ao dano que causar ao alvo.'),
(143, 'Trajeto Mortal', 'Falange', 10, 1, 'Talento', 'Gaste 3 Pontos de Esperança para percorrer o campo de batalha em linha reta até um ponto em alcance distante, fazendo um ataque contra todos os adversários no alcance da sua arma ao longo do caminho percorrido. Escolha a ordem na qual o dano é causado aos alvos atingidos. Para o primeiro alvo, role o dano de sua arma com +1 de bônus na Proficiência. Depois disso, remova um dado do teste de dano e cause o dano restante ao próximo alvo. Continue removendo um dado para cada alvo subsequente até que não tenha mais dados de dano ou adversários. Você não pode escolher o mesmo alvo mais de uma vez por ataque.'),
(144, 'Passo Célere', 'Falange', 10, 2, 'Talento', 'Quando um ataque falha contra você, recupere 1 Ponto de Fadiga. Se não puder recuperar PF, receba 1 Ponto de Esperança.'),
(145, 'Livro de Ava', 'Códice', 1, 2, 'Grimório', 'Propelir: faça um teste de conjuração contra um alvo corpo a corpo. Em um sucesso, ele é empurrado para um ponto em alcance distante e sofre d10+2 de dano mágico com sua Proficiência. Armadura de Tava: gaste 1 Ponto de Esperança para conceder um bônus de +1 na Armadura a um alvo que você possa tocar. Esse bônus dura até o próximo descanso do alvo ou até que você conjure Armadura de Tava novamente. Estaca de Gelo: faça um teste de conjuração (12) para invocar um grande espinho de gelo em alcance distante. Se usá-lo como arma, em vez disso, faça o teste de conjuração contra a Dificuldade do alvo. Em um sucesso, você causa d6 de dano físico usando sua Proficiência.'),
(146, 'Livro de Illiat', 'Códice', 1, 2, 'Grimório', 'Sonolência: faça um teste de conjuração contra um alvo muito próximo. Em um sucesso, ele fica Adormecido até sofrer dano ou até o mestre gastar 1 Ponto de Medo no turno dele para encerrar a condição. Saraivada Arcana: uma vez por descanso, gaste qualquer quantidade de Pontos de Esperança para atirar projéteis mágicos que acertam um alvo próximo à sua escolha. Role um número de d6 igual à quantidade de Pontos de Esperança gasta e cause o resultado deles como dano mágico ao alvo. Telepatia: gaste 1 Ponto de Esperança para criar uma linha de comunicação mental com um alvo que você possa ver. Essa conexão dura até seu próximo descanso ou até você conjurar Telepatia novamente.'),
(147, 'Livro de Tyfar', 'Códice', 1, 2, 'Grimório', 'Chama Selvagem: faça um teste de conjuração contra até três adversários corpo a corpo. Chamas irrompem de sua mão. Alvos atingidos sofrem 2d6 de dano mágico e marcam 1 Ponto de Fadiga. Mão Arcana: você conjura uma mão mágica idêntica à sua em força e tamanho num ponto em alcance distante. Névoa Misteriosa: faça um teste de conjuração (13) para conjurar uma névoa densa que fica em uma área estática dentro do alcance muito próximo. A neblina deixa essa área e tudo o que há nela fortemente obscurecido. grimório'),
(148, 'Livro de Sitil', 'Códice', 2, 2, 'Grimório', 'Ajustar Aparência: você muda magicamente sua aparência e vestimentas para evitar ser reconhecido. Paralelos: gaste 2 Pontos de Esperança para conjurar este feitiço sobre si mesmo ou sobre um aliado próximo. Na próxima vez que o alvo fizer um ataque, ele pode acertar um alvo adicional dentro do alcance contra o qual seu teste de ataque seria bem-sucedido. Você pode manter este feitiço ativo sobre uma única criatura por vez. Ilusão: faça um teste de conjuração (14). Em um sucesso, você cria uma ilusão visual temporária em um ponto em alcance próximo. Ela não pode ultrapassar seu tamanho e dura enquanto você olhar para ela. A ilusão não levanta suspeitas até um observador estar corpo a corpo dela.'),
(149, 'Livro de Vagras', 'Códice', 2, 2, 'Grimório', 'Portal Arcano: se não houver adversários corpo a corpo, faça um teste de conjuração (13). Em um sucesso, gaste 1 Ponto de Esperança para criar um portal de onde você está para outro ponto que você possa ver em alcance distante. Ele se fecha depois que uma criatura passar por ele. Revelar: faça um teste de conjuração. Se houver algo escondido por magia em alcance próximo, ela é revelada. Tranca Rúnica: faça um teste de conjuração (15) sobre um objeto que esteja tocando e que possa fechar (como um baú, cadeado, caixa ou fechadura). Uma vez por descanso, em um sucesso, você pode trancar o objeto de modo que ele só possa ser aberto por criaturas designadas por você. Este feitiço pode ser quebrado em uma hora por uma pessoa com acesso à magia. grimório'),
(150, 'Livro de Korvax', 'Códice', 3, 2, 'Grimório', 'Círculo Rúnico: marque 1 Ponto de Fadiga para criar um círculo mágico temporário abaixo de onde você está. Todos os adversários que entrarem ou estiverem em alcance cac sofrem 2d12+4 de dano mágico e são empurrados para um ponto em alcance muito próximo. Lapso: gaste 1 Ponto de Esperança para forçar um alvo corpo a corpo a fazer um teste de reação (15). Se falhar, ele esquece o último minuto de conversa com você. Levitação: faça um teste de conjuração para suspender temporariamente no ar um alvo que você possa ver e movê-lo para um ponto em alcance próximo relativo à posição original dele.'),
(151, 'Livro de Norai', 'Códice', 3, 2, 'Grimório', 'Amarração Mística: faça um teste de conjuração contra um alvo distante. Em um sucesso, ele fica temporariamente Imobilizado e deve marcar 1 Ponto de Fadiga. Se tiver uma criatura que esteja voando como alvo, este feitiço faz com que ela aterrisse e fique temporariamente Imobilizada. Bola de Fogo: faça um teste de conjuração contra um alvo muito distante. Em um sucesso, lance uma esfera de fogo que explode ao se chocar contra ele. O alvo e todas as criaturas Muito Próximas dele devem fazer um teste de reação (13). Alvos que falharem sofrem d20+5 de dano mágico com sua Proficiência. Alvos bem-sucedidos sofrem metade do dano.'),
(152, 'Livro de Ecsota', 'Códice', 4, 3, 'Grimório', 'Criar Construto: gaste 1 Ponto de Esperança para escolher um grupo de objetos ao seu redor e, a partir deles, crie um construto animado que obedece comandos básicos. Faça um teste de conjuração para mandá-lo agir. Quando necessário, ele compartilha sua Evasão e atributos, e os ataques dele causam 2d10+3 de dano físico. Você pode manter apenas um construto por vez, e ele se desfaz ao sofrer qualquer quantidade de dano. Repudiar: você pode interromper um efeito mágico em andamento. Faça um teste de conjuração usando seu atributo de conjuração. Se passar, uma vez por descanso, o efeito cessa e quaisquer consequências são evitadas.'),
(153, 'Livro de Grynn', 'Códice', 4, 2, 'Grimório', 'Deflexão: uma vez por descanso longo, gaste 1 Ponto de Esperança para negar o dano de um ataque que tenha você ou um aliado muito próximo como alvo. Muralha de Fogo: faça um teste de conjuração (15). Em um sucesso, crie uma muralha de fogo mágico entre dois pontos em alcance distante. Todas as criaturas no caminho dela devem escolher ficar em um dos lados, e tudo o que atravessá-la depois disso sofre 4d10+3 de dano mágico. Tranca Temporal: escolha um objeto distante como alvo. Esse objeto para no tempo e espaço exatamente onde está até o seu próximo descanso. Se uma criatura tentar movê-lo, faça um teste de conjuração contra ela para sustentar este feitiço.'),
(154, 'Muralha', 'Códice', 5, 2, 'Feitiço', 'Faça um teste de conjuração (15). Em um sucesso, gaste 1 Ponto de Esperança uma vez por descanso para criar uma parede mágica temporária entre dois pontos em alcance distante. Ela pode ter até 15m de altura e se formar em qualquer ângulo. Criaturas ou objetos no caminho dela são desviados para um dos lados à sua escolha. A muralha perdura até seu próximo descanso ou até você conjurar Muralha novamente.'),
(155, 'Teleporte', 'Códice', 5, 2, 'Feitiço', 'Uma vez por descanso longo, você pode instantaneamente teleportar a si mesmo e qualquer número de alvos próximos voluntários para um lugar onde você já esteve anteriormente. Escolha uma das opções a seguir e faça um teste de conjuração (16): • Se conhece o lugar muito bem, receba +3 de bônus; • Se visitou o lugar com alguma frequência, receba +1 de bônus; • Se não visitou o lugar com frequência, você não ganha um modificador; • Se visitou o lugar apenas uma vez, sofra uma penalidade de –2. Em um sucesso, você aparece no lugar pretendido. Se falhar, você aparece em um lugar diferente do pretendido. O grau da falha determina quão longe você aparece. feitiço'),
(156, 'Banir', 'Códice', 6, 0, 'Feitiço', 'Faça um teste de conjuração contra um alvo próximo. Em um sucesso, role um número de d20 igual ao seu atributo de conjuração. O alvo deve fazer um teste de reação com Dificuldade igual ao seu resultado mais alto. Em um sucesso, o alvo marca 1 Ponto de Fadiga, mas não é banido. Uma vez por descanso, se falhar, ele é banido deste reino. Quando os personagens rolarem com Medo, a Dificuldade sofre uma penalidade de –1 e o alvo faz outro teste de reação. Em um sucesso, ele volta do banimento.'),
(157, 'Sigilo da Retaliação', 'Códice', 6, 2, 'Feitiço', 'Marque um adversário próximo com um Sigilo da Retaliação. O mestre ganha 1 Ponto de Medo. Quando o adversário marcado causar dano a você ou aos seus aliados, coloque 1d8 nesta carta. Você pode acumular um número de d8 igual ao seu nível. Ao atacar o adversário marcado com sucesso, role os dados que estão nesta carta e some o total à sua rolagem de dano; em seguida, retire os dados. Este efeito termina quando o adversário marcado é derrotado ou quando você conjura Sigilo da Retaliação novamente.'),
(158, 'Livro de Homet', 'Códice', 7, 0, 'Grimório', 'Atravessar: faça um teste de conjuração (13). Uma vez por descanso, em um sucesso, você e todas as criaturas que o estejam tocando podem atravessar uma parede ou porta Próxima. O efeito termina quando todos estiverem do outro lado. Portal Planar: faça um teste de conjuração (14). Uma vez por descanso longo, em um sucesso, abra um portal para uma localidade que você já tenha visitado em outra dimensão ou plano de existência. Esse portal perdura até seu próximo descanso. grimório'),
(159, 'Dom do Códice', 'Códice', 7, 2, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio do Códice, receba os seguintes benefícios: • Você pode marcar 1 Ponto de Fadiga para somar sua Proficiência a um teste de conjuração; • Uma vez por descanso, substitua esta carta por qualquer carta em sua reserva sem pagar o custo de troca.'),
(160, 'Livro de Vyola', 'Códice', 8, 2, 'Grimório', 'Clareza Compartilhada: uma vez por descanso longo, gaste 1 Ponto de Esperança para escolher duas criaturas voluntárias. Quando uma delas for marcar PF, ela pode escolher qual das duas irá marcar. Este feitiço dura até o próximo descanso dos alvos. Sondar Memórias: faça um teste de conjuração contra um alvo distante. Em um sucesso, espione a mente do alvo e faça uma pergunta ao mestre. O mestre descreve as memórias do alvo que estejam relacionadas à resposta.'),
(161, 'Refúgio Seguro', 'Códice', 8, 3, 'Feitiço', 'Quando tem alguns minutos de calma para se concentrar, você pode gastar 2 Pontos de Esperança para invocar seu Refúgio Seguro: um grande abrigo interdimensional onde você e seus aliados podem ficar. Ao fazer isso, uma porta mágica aparece em algum lugar em alcance próximo. Apenas criaturas designadas por você podem entrar. Após entrar, você pode deixar a entrada invisível. Qualquer pessoa no interior do refúgio pode sair a hora que quiser. Depois que você sair, a porta de entrada deve ser invocada novamente. Ao fazer um descanso em seu Refúgio Seguro, você pode escolher um movimento de repouso adicional.'),
(162, 'Livro de Ronin', 'Códice', 9, 4, 'Grimório', 'Enervação Eterna: uma vez por descanso longo, faça um teste de conjuração contra um alvo próximo. Em um sucesso, ele fica permanentemente Vulnerável. O alvo não pode se recuperar dessa condição por quaisquer meios. Transformação: faça um teste de conjuração (15). Em um sucesso, transforme-se em um objeto inanimado que não exceda o dobro de seu tamanho normal. Você pode permanecer nessa forma até sofrer dano.'),
(163, 'Onda Desintegradora', 'Códice', 9, 4, 'Feitiço', 'Faça um teste de conjuração (18). Uma vez por descanso longo, em um sucesso, o mestre lhe informa quais adversários distantes têm Dificuldade 18 ou menor. Marque 1 Ponto de Fadiga para cada alvo que quiser atingir com este feitiço. O alvo morre e não pode voltar à vida por quaisquer meios.'),
(164, 'Livro de Yarrow', 'Códice', 10, 2, 'Grimório', 'Imunidade Mágica: gaste 5 Pontos de Esperança para ficar imune a dano mágico até seu próximo descanso. Manipulação Temporal: faça um teste de conjuração (18). Em um sucesso, o tempo desacelera temporariamente até parar para todos que estiverem em alcance distante, com exceção de você. Ele volta ao normal na próxima vez que você fizer um teste que tenha outra criatura como alvo.'),
(165, 'União Transcendental', 'Códice', 10, 1, 'Feitiço', 'Uma vez por descanso longo, gaste 5 Pontos de Esperança para conjurar este feitiço sobre duas ou mais criaturas voluntárias. Até seu próximo descanso, quando uma criatura conectada por essa união for marcar Pontos de Vida ou Pontos de Fadiga, as criaturas conectadas podem escolher qual delas marcará.'),
(166, 'Dissimulação', 'Graça', 1, 0, 'Talento', 'Gaste 1 Ponto de Esperança para receber vantagem em um teste para enganar ou fazer alguém acreditar em uma mentira que você contar.'),
(167, 'Enfeitiçar', 'Graça', 1, 0, 'Feitiço', 'Faça um teste de conjuração contra um alvo próximo. Em um sucesso, ele fica temporariamente Enfeitiçado. Enquanto estiver Enfeitiçado, a atenção do alvo se fixa em você. O campo de visão dele se estreita e todos os sons além da sua voz são abafados. Uma vez por descanso, você pode marcar 1 Ponto de Fadiga para forçar o alvo Enfeitiçado a marcar 1 PF também.'),
(168, 'Palavras Inspiradoras', 'Graça', 1, 1, 'Talento', 'Suas palavras são imbuídas de poder. Após um descanso longo, coloque um número de marcadores igual à sua Presença nesta carta. Ao falar com um aliado, você pode gastar um marcador desta carta para dar a ele um benefício dentre os seguintes: • Seu aliado recupera 1 PF; • Seu aliado recupera 1 PV; • Seu aliado ganha 1 Ponto de Esperança. Após um descanso longo, marcadores não utilizados são perdidos.'),
(169, 'Não Minta para Mim', 'Graça', 2, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo muito próximo. Em um sucesso, ele não pode mentir para você enquanto estiver em alcance próximo, porém não é obrigado a falar. Se você fizer uma pergunta e ele se recusar a responder, ele deve marcar 1 Ponto de Fadiga e o efeito termina. O alvo em geral não está ciente de que este feitiço foi conjurado sobre ele até que fale uma verdade contra sua vontade.'),
(170, 'Insolência', 'Graça', 2, 2, 'Talento', 'Ao insultar ou provocar um alvo distante, faça um teste de Presença contra ele. Uma vez por descanso, em um sucesso, role um número de d4 igual à sua Proficiência. O alvo deve marcar um número de Pontos de Fadiga igual ao maior resultado obtido.'),
(171, 'Lampejo Hipnótico', 'Graça', 3, 1, 'Feitiço', 'Faça um teste de conjuração contra todos os adversários próximos na sua frente. Uma vez por descanso, em um sucesso, crie lampejos ilusórios de cores e luzes que deixam os alvos atingidos temporariamente Atordoados e os força a marcar 1 PF. Enquanto estiverem Atordoados, os alvos não podem usar reações e não podem fazer quaisquer outras ações até que se recuperem desta condição.'),
(172, 'Invisibilidade', 'Graça', 3, 1, 'Feitiço', 'Faça um teste de conjuração (10). Em um sucesso, marque 1 Ponto de Fadiga e deixe você ou um aliado corpo a corpo Invisível. Uma criatura Invisível só pode ser vista por meios mágicos e testes de ataque contra ela são feitos com desvantagem. Coloque um número de marcadores igual ao seu atributo de conjuração nesta carta. Quando a criatura Invisível faz uma ação, gaste um marcador desta carta. Após o término da ação que consumiu o último marcador, o efeito termina. Você pode manter apenas uma criatura sob efeito de Invisibilidade por vez.'),
(173, 'Palavras Tranquilizantes', 'Graça', 4, 1, 'Talento', 'Durante um descanso curto, ao passar um tempo amparando outro personagem por meio do movimento de repouso Tratar Ferimentos, recupere 1 Ponto de Vida adicional desse personagem. Ao fazer isso, você também recupera 2 Pontos de Vida.'),
(174, 'Espionar', 'Graça', 4, 1, 'Feitiço', 'Escolha um alvo muito distante. Você pode ver e ouvir pelos olhos e ouvidos dele. Você pode escolher entre usar seus próprios sentidos ou os do alvo à vontade até seu próximo descanso ou até você conjurar outro feitiço.'),
(175, 'Sondar Pensamentos', 'Graça', 5, 2, 'Feitiço', 'Você pode espionar a mente dos outros. Gaste 1 Ponto de Esperança para ler pensamentos vagos e superficiais de um alvo distante. Faça um teste de conjuração contra o alvo para sondar pensamentos profundos e escondidos. Se rolar com Medo, a critério do mestre, o alvo pode perceber que você está lendo a mente dele.'),
(176, 'Palavras de Discórdia', 'Graça', 5, 1, 'Feitiço', 'Sussurre palavras de discórdia para um adversário corpo a corpo e faça um teste de conjuração (13). Em um sucesso, o alvo deve marcar 1 Ponto de Fadiga e atacar outro adversário em vez de você ou seus aliados. Após concluir o ataque, o alvo percebe o que aconteceu. Na próxima vez que conjurar Palavras de Discórdia sobre ele, você sofre uma penalidade de –5 no teste de conjuração.'),
(177, 'Jamais Esquecido', 'Graça', 6, 2, 'Talento', 'Ao marcar 1 ou mais Pontos de Vida devido a um ataque, você pode marcar 1 Ponto de Fadiga para colocar um número de marcadores nesta carta igual ao número de PV marcados. Para cada marcador nesta carta, você recebe um bônus de +5 na rolagem de dano do próximo ataque que você acertar. Em seguida, zere todos os marcadores.'),
(178, 'Partilhar o Fardo', 'Graça', 6, 0, 'Feitiço', 'Uma vez por descanso, absorva a Fadiga de uma criatura corpo a corpo voluntária. O alvo descreve quais conhecimentos ou emoções particulares são transferidos da mente dele para a sua. Transfira qualquer número de PF do alvo para você e em seguida receba 1 Ponto de Esperança para cada PF transferido.'),
(179, 'Carisma Infinito', 'Graça', 7, 1, 'Talento', 'Após fazer um teste para obter favores, mentir ou persuadir, você pode gastar 1 Ponto de Esperança para rolar novamente seu Dado de Esperança ou Medo.'),
(180, 'Dom da Graça', 'Graça', 7, 2, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio da Graça, receba os seguintes benefícios: • Você pode marcar 1 PA em vez de 1 PF; • Quando for fazer com que um alvo marque PV, você pode forçá-lo a marcar um número equivalente de PF em vez disso.'),
(181, 'Projeção Astral', 'Graça', 8, 0, 'Feitiço', 'Uma vez por descanso longo, marque 1 Ponto de Fadiga para projetar uma cópia de si mesmo que pode aparecer em qualquer lugar no qual você já tenha estado anteriormente. Você pode ver e ouvir através da projeção e pode afetar o mundo como se você estivesse no lugar dela. Uma criatura que investigue a projeção pode discernir sua origem mágica. Esse efeito dura até seu próximo descanso ou até sua projeção sofrer qualquer dano.'),
(182, 'Enfeitiçar em Massa', 'Graça', 8, 3, 'Feitiço', 'Faça um teste de conjuração contra todos os alvos distantes. Alvos atingidos ficam temporariamente Enfeitiçados. Enquanto um alvo estiver Enfeitiçado, a atenção dele se fixa em você. O campo de visão dele se estreita e todos os sons além da sua voz são abafados. Marque 1 Ponto de Fadiga para forçar todos os alvos Enfeitiçados a marcarem 1 PF, encerrando este feitiço.'),
(183, 'Imitador', 'Graça', 9, 3, 'Feitiço', 'Uma vez por descanso longo, esta carta pode imitar as habilidades de outra carta de domínio de 8º nível ou menor na mão de outro jogador. Gaste uma quantidade de Esperança igual à metade do nível da carta para ter acesso à habilidade. A cópia permanece até seu próximo descanso ou até o outro jogador colocar a carta original na reserva.'),
(184, 'Mestre do Ofício', 'Graça', 9, 0, 'Talento', 'Receba um bônus permanente de +2 em duas de suas Experiências, ou +3 em apenas uma. Em seguida, coloque esta carta na sua reserva permanentemente.'),
(185, 'Em Dobro', 'Graça', 10, 1, 'Feitiço', 'Quando um aliado próximo causa dano a um adversário, você pode fazer um teste de conjuração contra esse mesmo alvo. Em um sucesso, você causa o mesmo dano que seu aliado causou. Se você rolar um sucesso com Medo, coloque esta carta na reserva.'),
(186, 'Notoriedade', 'Graça', 10, 0, 'Talento', 'As pessoas sabem quem você é e o que já fez; por isso, o tratam de forma diferente. Ao se aproveitar de sua notoriedade para conseguir o que quer, você pode marcar 1 Ponto de Fadiga antes do teste para receber um bônus de +10 no resultado. Onde quer que vá, você obtém comida e bebida grátis, e o preço das outras mercadorias que você compra diminui em uma bolsa de ouro (até o mínimo de um punhado). Esta carta não conta para o limite de 5 cartas de domínio na sua mão e não pode ser colocada na reserva.'),
(187, 'Delinquente', 'Meia-noite', 1, 0, 'Talento', 'Você tem vantagem em testes para arrombar fechaduras não mágicas, desarmar armadilhas não mágicas ou roubar itens de um alvo (seja por meio da furtividade ou da força).'),
(188, 'Chuva de Lâminas', 'Meia-noite', 1, 1, 'Feitiço', 'Gaste 1 Ponto de Esperança para fazer um teste de conjuração e arremessar lâminas mágicas contra todos os alvos muito próximos. Alvos atingidos sofrem d8+2 de dano mágico com sua Proficiência. Se um alvo atingido estiver Vulnerável, ele sofre 1d8 de dano adicional.'),
(189, 'Disfarce Inquietante', 'Meia-noite', 1, 0, 'Feitiço', 'Quando tem alguns minutos para se preparar, você pode marcar 1 Ponto de Fadiga para tomar a forma de qualquer humanoide que você possa ver com clareza em sua mente. Enquanto estiver disfarçado dessa forma, você tem vantagem em testes de Presença para evitar ser descoberto. Coloque um número de marcadores igual ao seu atributo de conjuração nesta carta. Quando fizer uma ação enquanto estiver disfarçado, gaste um marcador. Após a ação que consumiu o último marcador, o efeito termina.'),
(190, 'Espírito da Meia-Noite', 'Meia-noite', 2, 1, 'Feitiço', 'Gaste 1 Ponto de Esperança para invocar um espírito de tamanho humanoide que pode se mover ou carregar coisas para você até seu próximo descanso. Você também pode mandá-lo atacar um adversário. Ao fazer isso, faça um teste de conjuração contra um alvo muito distante. Em um sucesso, o espírito se move até ficar corpo a corpo ao alvo. Role um número de d6 igual ao seu atributo de conjuração e cause o resultado deles como dano mágico ao alvo. O espírito então se dissipa. Você pode ter apenas um espírito por vez.'),
(191, 'Sombra Traiçoeira', 'Meia-noite', 2, 0, 'Feitiço', 'Faça um teste de conjuração contra todos os adversários muito próximos. Alvos atingidos ficam temporariamente Imobilizados pela própria sombra no lugar em que estão.'),
(192, 'Estrangulamento', 'Meia-noite', 3, 1, 'Talento', 'Quando se posiciona atrás de uma criatura de tamanho similar ao seu, você pode marcar 1 Ponto de Fadiga para estrangulá-la, deixando-a temporariamente Vulnerável. Quando uma criatura ataca um alvo Vulnerável dessa forma, ela causa 2d6 de dano adicional.'),
(193, 'Véu da Noite', 'Meia-noite', 3, 1, 'Feitiço', 'Faça um teste de conjuração (13). Em um sucesso, crie uma cortina de escuridão entre dois pontos em alcance distante. Apenas você pode enxergar através dessa escuridão. Você é considerado Escondido para adversários no outro lado da cortina e tem vantagem em testes de ataque feitos através da escuridão. A cortina dura até você conjurar outro feitiço.'),
(194, 'Mestre da Furtividade', 'Meia-noite', 4, 0, 'Talento', 'Ao rolar com Medo enquanto tenta se mover por uma área perigosa sem ser percebido, você pode marcar 1 PF para rolar com Esperança em vez disso. Se um aliado próximo também estiver tentando se mover sem ser percebido e rolar com Medo, você pode marcar 1 PF para mudar o resultado e fazê-lo rolar com Esperança.'),
(195, 'Glifo do Ocaso', 'Meia-noite', 4, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo muito próximo. Em um sucesso, gaste 1 Ponto de Esperança para conjurar um glifo sombrio sobre ele. O glifo expõe os pontos fracos do alvo, reduzindo temporariamente sua Dificuldade em um valor igual ao seu Conhecimento (mínimo de 1).'),
(196, 'Silêncio', 'Meia-noite', 5, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo próximo. Em um sucesso, gaste 1 Ponto de Esperança para conjurar um efeito mágico supressor sobre o alvo. Esse efeito afeta tudo em alcance muito próximo do alvo e o acompanha quando ele se move. O alvo, e tudo mais na área afetada, fica Silenciado. Enquanto estiver Silenciado, o alvo não pode fazer barulho ou conjurar feitiços. Essa condição dura até o mestre gastar 1 Ponto de Medo no turno dele para encerrá-la, até você conjurar Silêncio novamente ou até você sofrer dano maior.'),
(197, 'Recuo Espectral', 'Meia-noite', 5, 2, 'Feitiço', 'Gaste 1 Ponto de Esperança para ativar Recuo Espectral no local onde você está. Gaste mais 1 Ponto de Esperança a qualquer momento antes de seu próximo descanso para desaparecer da sua localização atual e reaparecer no local onde estava quando ativou Recuo Espectral. Depois que você reaparecer, este feitiço termina.'),
(198, 'Sussurros Sombrios', 'Meia-noite', 6, 0, 'Feitiço', 'Você pode se comunicar mentalmente com qualquer pessoa com a qual tenha tido contato físico. Uma vez que tenha aberto um canal de comunicação com o alvo, ele pode se comunicar com você da mesma forma. Além disso, você pode marcar 1 Ponto de Fadiga para fazer um teste de conjuração contra ele. Em um sucesso, você pode fazer uma das seguintes perguntas, que deve ser respondida pelo mestre: • Onde a pessoa está? • O que ela está fazendo? • Do que ela tem medo? • Com o que ela mais se preocupa?'),
(199, 'Disfarce em Massa', 'Meia-noite', 6, 0, 'Feitiço', 'Quando tem alguns minutos de silêncio para se concentrar, você pode marcar 1 Ponto de Fadiga para alterar a aparência de todas as criaturas Próximas voluntárias. As novas formas devem ter estrutura corporal e tamanho semelhantes e podem ser tanto algo ou alguém que você já tenha visto quanto criação sua. Uma criatura disfarçada dessa forma tem vantagem em testes de Presença para evitar ser descoberta. Ative uma contagem regressiva (8). Ela diminui em virtude de uma consequência escolhida pelo mestre. Quando a consequência da contagem regressiva é ativada, o disfarce termina.'),
(200, 'Dom da Meia-Noite', 'Meia-noite', 7, 2, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio da Meia-noite, receba os seguintes benefícios: • Uma vez por descanso, se você tiver 0 Ponto de Esperança e o mestre for receber Medo, em vez disso, você pode receber 1 Ponto de Esperança; • Ao acertar um ataque, você pode marcar 1 Ponto de Fadiga para somar o resultado de seu Dado de Medo à rolagem de dano.'),
(201, 'Esvanecer', 'Meia-noite', 7, 1, 'Feitiço', 'Quando um ataque que causaria dano físico a você falha, você pode gastar 1 Ponto de Esperança para ficar Escondido em um invólucro de sombras e se teleportar para um ponto próximo do atacante. Você permanece Escondido até o próximo teste que fizer.'),
(202, 'Caçador Sombrio', 'Meia-noite', 8, 2, 'Talento', 'Suas capacidades são aprimoradas quando você age nas sombras. Enquanto estiver na penumbra ou na escuridão, você recebe um bônus de +1 na Evasão e tem vantagem em testes de ataque.'),
(203, 'Carga Mágica', 'Meia-noite', 8, 1, 'Feitiço', 'Ao sofrer dano mágico, coloque um número de marcadores nesta carta igual ao número de PV marcados. Você pode acumular um número de marcadores igual ao seu atributo de conjuração. Quando acertar um ataque contra um alvo, você pode gastar um número qualquer de marcadores e somar uma quantidade equivalente de d6 à rolagem de dano.'),
(204, 'Terror Noturno', 'Meia-noite', 9, 2, 'Feitiço', 'Uma vez por descanso longo, escolha quaisquer alvos muito próximos. Eles passam a ver você como uma horrorosa visão de pesadelo. Os alvos devem ter sucesso em um teste de reação (16) ou ficam temporariamente Horrorizados. Enquanto estiverem Horrorizados, eles ficam Vulneráveis. Roube uma quantidade de Medo do mestre igual ao número de alvos Horrorizados (até o máximo de acúmulos de Medo do mestre). Role um número de d6 igual à quantidade de Medo roubado e cause o resultado deles como dano a cada alvo Horrorizado. Em seguida, descarte todo o Medo que roubou.'),
(205, 'Tributo do Anoitecer', 'Meia-noite', 9, 1, 'Talento', 'Escolha um alvo distante. Quando você tem sucesso em um teste que não resulta em uma rolagem de dano contra ele, coloque um marcador nesta carta. Ao causar dano contra esse alvo, gaste qualquer quantidade de marcadores e some um número equivalente de d12 à rolagem de dano. Você pode manter o Tributo do Anoitecer apenas sobre uma criatura por vez. Ao escolher um novo alvo ou fazer um descanso, marcadores não utilizados são perdidos.'),
(206, 'Eclipse', 'Meia-noite', 10, 2, 'Feitiço', 'Faça um teste de conjuração (16). Uma vez por descanso longo, em um sucesso, faça com que toda a área em alcance distante caia em completa escuridão, na qual apenas você e seus aliados podem enxergar. Os testes de ataque contra você ou seus aliados têm desvantagem dentro dessa escuridão. Além disso, quando você ou um aliado tem um sucesso com Esperança contra um adversário dentro dessa área, o alvo deve marcar 1 Ponto de Fadiga. Este feitiço dura até o mestre gastar 1 Ponto de Medo no turno dele para encerrar o efeito ou até você sofrer dano grave.'),
(207, 'Espectro das Trevas', 'Meia-noite', 10, 1, 'Feitiço', 'Marque 1 Ponto de Fadiga para tornar-se Incorpóreo. Essa condição dura até você fazer um teste tendo outra criatura como alvo. Enquanto estiver Incorpóreo, você é imune a dano físico e pode flutuar e atravessar objetos sólidos. Outras criaturas ainda podem vê-lo nessa forma.'),
(208, 'Rastreador Talentoso', 'Sabedoria', 1, 0, 'Talento', 'Ao rastrear uma criatura ou grupo de criaturas com base nos sinais da passagem delas, você pode gastar qualquer quantidade de Pontos de Esperança e fazer um número equivalente destas perguntas ao mestre: • Para que direção ele(s) foi(foram)? • Há quanto tempo a criatura ou grupo passou por aqui? • O que a criatura ou grupo fazia neste lugar? • Quantas criaturas havia? Ao encontrar os alvos rastreados dessa forma, você recebe um bônus de +1 na Evasão contra elas.'),
(209, 'Voz da Natureza', 'Sabedoria', 1, 0, 'Talento', 'Você fala o idioma do mundo natural. Quando quiser falar com as plantas e animais ao seu redor, faça um teste de Instinto (12). Em um sucesso, essas plantas ou animais fornecem a informação que conhecem. Se rolar com Medo, o conhecimento fornecido pode ser limitado ou ter um custo. Além disso, antes de fazer um testede conjuração em um ambiente natural, você pode gastar 1 Ponto de Esperança para receber um bônus de +2 na rolagem.'),
(210, 'Vinha Voraz', 'Sabedoria', 1, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo distante. Em um sucesso, raízes e vinhas saem do chão, causando 1d8+1 de dano físico e Imobilizando o alvo temporariamente. Além disso, em um sucesso, você pode gastar 1 Ponto de Esperança para temporariamente Imobilizar um adversário muito próximo do primeiro.'),
(211, 'Conjurar Enxame', 'Sabedoria', 2, 1, 'Feitiço', 'Besouros Blindados de Tekaira: marque 1 PF para conjurar um enxame de besouros ao seu redor. Na próxima vez que sofrer dano, reduza a gravidade em um limiar. Você pode gastar 1 Ponto de Esperança para manter os besouros conjurados após sofrer dano. Vaga-Lumes: faça um teste de conjuração contra todos os adversários próximos. Gaste 1 Ponto de Esperança para causar 2d8+3 de dano mágico aos alvos atingidos.'),
(212, 'Familiar da Natureza', 'Sabedoria', 2, 1, 'Feitiço', 'Gaste 1 Ponto de Esperança para invocar um pequeno espírito da natureza ou criatura da floresta. Esse familiar fica ao seu lado até seu próximo descanso, até você conjurar Familiar da Natureza novamente ou até que ele seja alvo de um ataque. Ao gastar 1 Ponto de Esperança adicional, você pode invocar um familiar voador. Você pode se comunicar com ele, fazer um teste de conjuração para mandá-lo executar tarefas simples e marcar 1 PF para enxergar pelos olhos dele. Ao causar dano a um adversário corpo a corpo ao seu familiar, some 1d6 à rolagem de dano.'),
(213, 'Projétil Corrosivo', 'Sabedoria', 3, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo distante. Em um sucesso, cause d6+4 de dano mágico usando sua Proficiência. Além disso, marque 2 ou mais Pontos de Fadiga para deixá-lo permanentemente Corroído. Um alvo Corroído sofre uma penalidade de –1 na Dificuldade para cada 2 Pontos de Fadiga que você gastou. Essa condição é cumulativa.'),
(214, 'Tronco Descomunal', 'Sabedoria', 3, 1, 'Feitiço', 'Uma vez por descanso, você pode conjurar um tronco espesso, retorcido e fácil de escalar em um ponto em alcance próximo. A altura dele pode ser equivalente ao alcance distante. Marque 1 Ponto de Fadiga para usar este feitiço como um ataque. Faça um teste de conjuração contra um adversário ou grupo de adversários próximo. O tronco irrompe, lançando os alvos no ar e derrubando-os, causando d8 de dano físico usando sua Proficiência.'),
(215, 'Constrição Mortal', 'Sabedoria', 4, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo próximo e escolha uma das seguintes opções: • Você puxa o alvo para um ponto corpo a corpo ou puxa a si mesmo para um ponto corpo a corpo a ele; • Você constringe o alvo e o força a marcar 2 Pontos de Fadiga; • Todos os adversários entre você e o alvo devem ter sucesso em um teste de reação (13) ou são atingidos por vinhas e sofrem 3d6+2 de dano fís. Em um sucesso, vinhas saem de suas mãos, causando o efeito escolhido e Imobilizando o alvo temporariamente.'),
(216, 'Campo Curativo', 'Sabedoria', 4, 2, 'Feitiço', 'Uma vez por descanso longo, você pode conjurar um campo de plantas curativas ao seu redor. Toda a área em alcance próximo irrompe em vida e natureza vibrante, permitindo que você e todos os aliados nessa área recuperem 1 Ponto de Vida. Gaste 2 Pontos de Esperança para curar 2 Pontos de Vida em vez de 1.'),
(217, 'Pele de Espinhos', 'Sabedoria', 5, 1, 'Feitiço', 'Uma vez por descanso, gaste 1 Ponto de Esperança para fazer com que espinhos brotem de todo o seu corpo. Ao fazer isso, coloque um número de marcadores igual ao seu atributo de conjuração nesta carta. Ao sofrer dano, você pode gastar qualquer quantidade de marcadores e rolar um número equivalente de d6. Reduza o dano sofrido em um número igual à soma dos resultados. Se estiver corpo a corpo ao atacante, cause a mesma quantidade de dano a ele. Após um descanso, marcadores não utilizados são perdidos.'),
(218, 'Fortaleza Selvagem', 'Sabedoria', 5, 1, 'Feitiço', 'Faça um teste de conjuração (13). Em um sucesso, gaste 2 Pontos de Esperança para fazer crescer uma barricada natural em formato de domo na qual você e um aliado podem buscar cobertura. Uma criatura dentro do domo não pode atacar nem ser alvo de ataques. Ataques feitos contra o domo acertam automaticamente. O domo tem 3 PV (coloque marcadores nesta carta para representálos) e tem 15/30 como seus limiares de dano. dano menor dano maior dano grave 15 30 Marque 1 PV Marque 2 PV Marque 3 PV'),
(219, 'Conjurar Montarias', 'Sabedoria', 6, 0, 'Feitiço', 'Gaste qualquer quantidade de Esperança para conjurar um número equivalente de montarias (como cavalos, camelos ou elefantes) que você e seus aliados podem usar até seu próximo descanso longo ou até que as montarias sofram dano. As montarias dobram sua velocidade de viagem por terra e, quando em perigo, permitem que você se mova para um ponto em alcance distante sem precisar de teste. Criaturas sobre as montarias sofrem uma penalidade de –2 em testes de ataque e ganham +2 de bônus nas rolagens de dano.'),
(220, 'Coletor', 'Sabedoria', 6, 1, 'Talento', 'Como um movimento de repouso adicional que você pode escolher, role 1d6 para descobrir o que você coleta. Colabore com o mestre para descrever esse item e adicione-o ao seu inventário como um consumível. Seu grupo pode carregar no máximo cinco consumíveis coletados por vez. 1d6 Consumível Efeito 1 Um alimento único recupera 2 Pontos de Fadiga 2 Uma bela relíquia receba 2 Pontos de Esperança 3 Uma runa arcana +2 em um teste de conjuração 4 Um frasco curativo recupera 2 Pontos de Vida 5 Um talismã da sorte role qualquer dado novamente 6 Escolha uma das opções acima.'),
(221, 'Dom da Sabedoria', 'Sabedoria', 7, 2, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio da Sabedoria, receba os seguintes benefícios: • Enquanto estiver em um ambiente natural, você ganha um bônus de +2 em testes de conjuração; • Uma vez por descanso, você pode dobrar sua Agilidade ou Instinto ao fazer um teste que use esse atributo. Você deve fazer isso antes de rolar os dados.'),
(222, 'Aspecto Selvagem', 'Sabedoria', 7, 2, 'Feitiço', 'Uma vez por descanso longo, marque 1 Ponto de Fadiga para canalizar a natureza ao seu redor e aprimorar a si mesmo. Descreva como sua aparência muda e, em seguida, coloque 1d6 nesta carta, com o 1 virado para cima. Enquanto o Dado de Aspecto Selvagem estiver ativo, você soma seu valor a todos seus testes. Após somar seu valor a um teste, aumente o valor do dado em 1. Se o valor do dado for ultrapassar 6, ou se você fizer um descanso, essa forma termina e você deve marcar 1 Ponto de Fadiga adicional.'),
(223, 'Espíritos da Floresta', 'Sabedoria', 8, 2, 'Feitiço', 'Faça um teste de conjuração (13). Em um sucesso, gaste qualquer quantidade de Pontos de Esperança para criar um número equivalente de espíritos da floresta. Todos surgem em pontos à sua escolha em alcance distante e fornecem os seguintes benefícios: • Seus aliados recebem um bônus de +3 em testes de ataque contra adversários cac a um espírito; • Se um aliado marcar 1 Ponto de Armadura enquanto estiver cac a um dos espíritos, ele pode marcar 1 Ponto de Armadura adicional. Após conceder um benefício ou sofrer qualquer dano, um espírito desaparece.'),
(224, 'Barreira Revigorante', 'Sabedoria', 8, 1, 'Feitiço', 'Faça um teste de conjuração (15). Uma vez por descanso, em um sucesso, crie uma barreira temporária de energia protetora que fica Muito Próxima de você. Você e todos os aliados que estão dentro da barreira quando este feitiço é conjurado recuperam 1d4 PV. Enquanto a barreira estiver de pé, você e todos os aliados no interior dela têm resistência a dano físico oriundo do lado de fora. Quando você se move, a barreira se move com você.'),
(225, 'Santuário Selvagem', 'Sabedoria', 9, 2, 'Talento', 'Após um descanso longo, coloque uma quantidade de marcadores nesta carta igual ao número de cartas do domínio da Sabedoria na sua mão e reserva. Quando fizer um teste de conjuração, você pode gastar qualquer número de marcadores após o teste para receber um bônus de +1 por marcador. Ao ter sucesso crítico em um teste de conjuração para um feitiço do domínio da Sabedoria, receba um marcador. Após o próximo descanso longo, marcadores não utilizados são perdidos.'),
(226, 'Soberania Vegetal', 'Sabedoria', 9, 1, 'Feitiço', 'Faça um teste de conjuração (18). Uma vez por descanso longo, em um sucesso, você remodela o mundo natural, alterando a flora em qualquer ponto em alcance distante. Por exemplo, você pode fazer árvores brotarem instantaneamente, criar um caminho através de vegetação densa ou erguer uma muralha de raízes.'),
(227, 'Força da Natureza', 'Sabedoria', 10, 2, 'Feitiço', 'Marque 1 Ponto de Fadiga para se transformar em um grande espírito da natureza, recebendo os seguintes benefícios: • Ao ter sucesso em um teste de ataque ou conjuração, receba +10 de bônus na rolagem de dano; • Ao causar dano suficiente para derrotar uma criatura Próxima, você a absorve e recupera 1 PA; • Você não pode ser Imobilizado. Antes de fazer um teste, você deve gastar 1 Ponto de Esperança. Se não puder fazer isso, volta à forma normal.'),
(228, 'Tempestade', 'Sabedoria', 10, 2, 'Feitiço', 'Escolha um dos tipos de tempestade abaixo e faça um teste de conjuração contra todos os alvos distantes. Alvos atingidos sofrem os efeitos até o mestre gastar 1 Ponto de Medo no turno dele para encerrar este feitiço. • Nevasca: causa 2d20+8 de dano mágico e deixa os alvos temporariamente Vulneráveis. • Furacão: causa 3d10+10 de dano mágico. Escolha uma direção para a qual o vento sopra. Alvos não podem se mover contra o vento. • Tempestade de Areia: cause 5d6+9 de dano mágico. Ataques oriundos de um ponto além do alcance corpo a corpo têm desvantagem.'),
(229, 'Raio Luminoso', 'Esplendor', 1, 1, 'Feitiço', 'Faça um teste de conjuração contra um alvo distante. Em um sucesso, gaste 1 Ponto de Esperança para lançar um raio de luz radiante contra ele, causando d8+2 de dano mágico usando sua Proficiência. O alvo fica temporariamente Vulnerável e emite uma luz intensa até se recuperar dessa condição.'),
(230, 'Toque Reparador', 'Esplendor', 1, 1, 'Feitiço', 'Você toca uma criatura e canaliza magia curativa para fechar seus ferimentos. Quando pode passar alguns minutos se concentrando em quem está ajudando, gaste 2 Pontos de Esperança para recuperar 1 PV ou PF do alvo. Uma vez por descanso longo, ao passar esse momento curativo descobrindo algo novo sobre a criatura ou revelando algo sobre si mesmo a ela, você pode fazê-la recuperar 2 Pontos de Vida ou Pontos de Fadiga, em vez de 1.'),
(231, 'Validação', 'Esplendor', 1, 0, 'Talento', 'Uma vez por descanso, após o teste de um aliado, mas antes das consequências ocorrerem, você pode auxiliá-lo com palavras de apoio. Ao fazer isso, seu aliado pode rolar os dados novamente.'),
(232, 'Últimas Palavras', 'Esplendor', 2, 1, 'Feitiço', 'Você pode conceder um momento de vida a um cadáver para conversar com ele. Faça um teste de conjuração (13). Em um sucesso com Esperança, o cadáver responde até três perguntas. Em um sucesso com Medo, o cadáver responde uma pergunta. O cadáver responde com sinceridade, mas não pode fornecer informações que desconhecia enquanto estava vivo. Se falhar, ou após o cadáver terminar de responder às suas perguntas, ele se desfaz em pó.'),
(233, 'Mãos Curativas', 'Esplendor', 2, 1, 'Feitiço', 'Faça um teste de conjuração (13) tendo como alvo uma criatura corpo a corpo que não seja você. Em um sucesso, marque 1 Ponto de Fadiga para recuperar 2 Pontos de Vida ou Pontos de Fadiga do alvo. Se falhar, marque 1 Ponto de Fadiga para recuperar 1 PV ou PF do alvo. Você não pode curar o mesmo alvo novamente até seu próximo descanso longo.'),
(234, 'Novo Fôlego', 'Esplendor', 3, 2, 'Talento', 'Uma vez por descanso, ao acertar um ataque contra um adversário, você pode recuperar 1 Ponto de Vida ou 3 Pontos de Fadiga. Em um sucesso com Esperança, você também recupera 1 PV ou 3 PF de um aliado próximo.'),
(235, 'Voz da Razão', 'Esplendor', 3, 1, 'Talento', 'Você fala com poder e autoridade sem igual. Você tem vantagem em testes para acalmar situações violentas ou convencer alguém a seguir sua ordem. Além disso, você demonstra mais firmeza sob pressão. Quando todos seus Pontos de Fadiga estiverem marcados, você ganha um bônus de +1 na Proficiência para rolagens de dano.'),
(236, 'Adivinhação', 'Esplendor', 4, 1, 'Feitiço', 'Uma vez por descanso longo, gaste 3 Pontos de Esperança para se comunicar com as forças do além e fazer uma única pergunta sobre algum evento, lugar, pessoa ou situação no futuro próximo que possa ser respondida com “sim” ou “não”. O tempo presente desaparece por um momento e a resposta surge magicamente diante de você.'),
(237, 'Sigilo da Vida', 'Esplendor', 4, 1, 'Feitiço', 'Gaste 3 Pontos de Esperança e escolha um aliado próximo. Ele é marcado por um brilhante sigilo de proteção. Quando esse aliado for fazer um movimento de morte, ele recupera 1 PV em vez disso. Este efeito termina quando salva o alvo de um movimento de morte, quando você conjura Sigilo da Vida sobre outro alvo ou quando faz um descanso longo.'),
(238, 'Moldar Material', 'Esplendor', 5, 1, 'Feitiço', 'Gaste 1 Ponto de Esperança para moldar parte de um material natural que esteja tocando (como gelo, madeira ou pedra) à sua vontade. A área do material não pode ser maior que você. Por exemplo, você pode criar uma ferramenta rudimentar ou criar uma porta. Você só pode afetar o material próximo do ponto que você está tocando.'),
(239, 'Punição', 'Esplendor', 5, 2, 'Feitiço', 'Uma vez por descanso, gaste 3 Pontos de Esperança para carregar sua Punição. Ao acertar seu próximo ataque de arma, dobre o resultado da rolagem de dano. Independente do tipo de dano da arma, esse ataque causa dano mágico.'),
(240, 'Restauração', 'Esplendor', 6, 2, 'Feitiço', 'Após um descanso longo, coloque um número de marcadores igual ao seu atributo de conjuração nesta carta. Toque uma criatura e gaste qualquer quantidade de marcadores. Para cada marcador gasto, recupere 2 Pontos de Vida ou Pontos de Fadiga do alvo. Você também pode gastar um marcador desta carta para tocar uma criatura e recuperá-la da condição Vulnerável ou curar uma doença física ou mágica (o mestre pode exigir o gasto de mais marcadores, dependendo da potência da doença). Após um descanso longo, marcadores não utilizados são perdidos.'),
(241, 'Zona de Proteção', 'Esplendor', 6, 2, 'Feitiço', 'Faça um teste de conjuração (16). Uma vez por descanso longo, em um sucesso, escolha um ponto em alcance distante e crie uma zona de proteção visível para todos os aliados muito próximos do ponto de origem. Ao fazer isso, coloque 1d6 nesta carta, com o 1 virado para cima. Quando um aliado na zona de proteção sofre dano, reduza esse dano pelo valor do dado. Em seguida, aumente o valor do dado em um. Se o valor do dado for ultrapassar 6, este efeito termina.'),
(242, 'Golpe Curativo', 'Esplendor', 7, 1, 'Feitiço', 'Ao causar dano a um adversário, você pode gastar 2 Pontos de Esperança para recuperar 1 PV de um aliado próximo.'),
(243, 'Dom do Esplendor', 'Esplendor', 7, 2, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio do Esplendor, receba os seguintes benefícios: • Um bônus de +3 no seu limiar de dano grave; • Uma vez por descanso longo, quando o dano sofrido exigir que marque PV, você pode, em vez disso, marcar uma quantidade equivalente de PF ou gastar uma quantidade equivalente de Esperança.'),
(244, 'Aura Defensora', 'Esplendor', 8, 2, 'Feitiço', 'Marque 1 Ponto de Fadiga para conjurar uma aura protetora sobre um alvo muito próximo. Quando o alvo marca 1 Ponto de Armadura, ele reduz a gravidade do ataque em um limiar adicional. Se este feitiço fizer uma criatura que sofreria dano não marcar Pontos de Vida, o efeito termina. Você pode manter a Aura Defensora apenas sobre uma criatura por vez.'),
(245, 'Fulgor Atordoante', 'Esplendor', 8, 2, 'Feitiço', 'Faça um teste de conjuração para disparar raios solares contra todos os adversários distantes à sua frente. Em um sucesso, gaste qualquer quantidade de Pontos de Esperança e force um número equivalente de alvos atingidos a fazer um teste de reação (14). Alvos bem-sucedidos sofrem 3d20+3 de dano mágico. Alvos que falharem sofrem 4d20+5 de dano mágico e ficam temporariamente Atordoados. Enquanto estiverem Atordoados, os alvos não podem usar reações e não podem fazer quaisquer outras ações até que se recuperem dessa condição.'),
(246, 'Aura Esmagadora', 'Esplendor', 9, 2, 'Feitiço', 'Faça um teste de conjuração (15) para fortalecer sua aura com magia. Em um sucesso, gaste 2 Pontos de Esperança para tornar sua Presença igual ao seu atributo de conjuração até seu próximo descanso longo. Enquanto este feitiço estiver ativo, seus adversários devem marcar 1 Ponto de Fadiga ao selecionarem você como alvo de um ataque.'),
(247, 'Feixe de Remissão', 'Esplendor', 9, 2, 'Feitiço', 'Faça um teste de conjuração (16). Em um sucesso, marque uma quantidade qualquer de PF para escolher uma linha de aliados em alcance distante como alvo. Você pode recuperar um número de Pontos de Vida, divididos como você quiser entre os alvos, igual à quantidade de PF que marcou.'),
(248, 'Revigorar', 'Esplendor', 10, 3, 'Feitiço', 'Após você ou um aliado próximo usar uma habilidade com limite de uso (como uma vez por descanso ou uma vez por sessão), você pode gastar uma quantidade qualquer de Pontos de Esperança e rolar um número equivalente de d6. Se tirar 6 em qualquer dado, a habilidade pode ser usada novamente.'),
(249, 'Ressurreição', 'Esplendor', 10, 2, 'Feitiço', 'Faça um teste de conjuração (20). Em um sucesso, faça com que uma criatura morta há no máximo 100 anos volte à vida com todas as suas capacidades. Em seguida, role 1d6. Se tirar 5 ou menos, coloque esta carta na reserva permanentemente. Se falhar, você não pode conjurar Ressurreição novamente por uma semana.'),
(250, 'Armadura Corporal', 'Valor', 1, 0, 'Talento', 'Enquanto não equipar uma armadura, você tem Armadura base igual a 3 + sua Força e usa estes limiares de dano base: • 1º patamar: 9/19; • 2º patamar: 11/24; • 3º patamar: 13/31; • 4º patamar: 15/38.'),
(251, 'Imposição', 'Valor', 1, 0, 'Talento', 'Ataque um alvo corpo a corpo com sua arma principal. Em um sucesso, você causa dano e o empurra para um ponto em alcance próximo. Em um sucesso com Esperança, acrescente 1d6 à rolagem de dano. Além disso, gaste 1 Ponto de Esperança para deixá-lo temporariamente Vulnerável.'),
(252, 'Sou Seu Escudo', 'Valor', 1, 1, 'Talento', 'Quando um aliado muito próximo for sofrer dano, você pode marcar 1 Ponto de Fadiga para prostrar-se no caminho e virar o alvo do ataque no lugar dele. Ao sofrer dano desse ataque, você pode marcar um número qualquer de Pontos de Armadura.'),
(253, 'Força Esmagadora', 'Valor', 2, 1, 'Talento', 'Você usa toda sua força física em um combate. Ao acertar um ataque usando uma arma com alcance corpo a corpo, receba um bônus igual à sua Força na rolagem de dano.'),
(254, 'Presença Corajosa', 'Valor', 2, 0, 'Talento', 'Ao fazer um teste de Presença, você pode gastar 1 Ponto de Esperança para somar sua Força à rolagem. Além disso, uma vez por descanso, quando for sofrer uma condição, você pode descrever como sua Presença Corajosa ajuda na situação e impede que você sofra a condição.'),
(255, 'Inspiração Crítica', 'Valor', 3, 1, 'Talento', 'Uma vez por descanso, quando você obtém um sucesso crítico em um ataque, todos os aliados muito próximos podem recuperar 1 PF ou receber 1 Ponto de Esperança.'),
(256, 'Palavras de Conforto', 'Valor', 3, 1, 'Talento', 'Uma vez por descanso longo, quando você consola ou inspira um aliado que falhou em um teste, vocês dois podem recuperar 2 Pontos de Fadiga cada.'),
(257, 'Incitar', 'Valor', 4, 1, 'Talento', 'Descreva como você provoca um alvo próximo. Em seguida, faça um teste de Presença contra ele. Em um sucesso, o alvo deve marcar 1 PF e, na próxima vez que o mestre colocá-lo em foco, ele deve atacar você com desvantagem.'),
(258, 'Bastião', 'Valor', 4, 2, 'Talento', 'Quando um aliado próximo falhar em um teste, você pode gastar 2 Pontos de Esperança para permitir que ele role novamente o Dado de Medo ou de Esperança.'),
(259, 'Armeiro', 'Valor', 5, 1, 'Talento', 'Você recebe um bônus de +1 na Armadura enquanto estiver usando armadura. Ao escolher Reparar Armadura como movimento de repouso durante um descanso, seus aliados também recuperam 1 Ponto de Armadura.'),
(260, 'Golpe Inspirador', 'Valor', 5, 1, 'Talento', 'Uma vez por descanso, ao ter sucesso crítico em um ataque, você e todos os aliados que possam vê-lo ou ouvi-lo podem recuperar 1 Ponto de Vida ou 1d4 Pontos de Fadiga.'),
(261, 'Inevitável', 'Valor', 6, 1, 'Talento', 'Ao falhar em um teste, seu próximo teste é feito com vantagem.'),
(262, 'Altivez', 'Valor', 6, 2, 'Talento', 'Receba um bônus igual à sua Proficiência no seu limiar grave. Ao marcar 1 ou mais PV devido a um ataque, recupere 1 Ponto de Fadiga.'),
(263, 'Desprezar Fraqueza', 'Valor', 7, 1, 'Talento', 'Quando sofrer dano, você pode marcar 1 Ponto de Fadiga para reduzir a gravidade do dano em um limiar. Ao fazer isso, role 1d6. Se tirar 3 ou menos, coloque esta carta na reserva.'),
(264, 'Dom do Valor', 'Valor', 7, 1, 'Talento', 'Se 4 ou mais cartas de domínio na sua mão pertencerem ao domínio do Valor, receba os seguintes benefícios: • Bônus de +1 na Armadura; • Ao marcar 1 ou mais Pontos de Vida sem marcar Pontos de Armadura, recupere 1 PA.'),
(265, 'Testar Os Limites', 'Valor', 8, 1, 'Talento', 'Uma vez por descanso longo, marque 3 Pontos de Fadiga para testar os limites de seu corpo. Você recebe um bônus de +2 em todos os atributos até seu próximo descanso.'),
(266, 'Abalo Sísmico', 'Valor', 8, 2, 'Talento', 'Gaste 2 Pontos de Esperança para golpear o solo abaixo de você. Faça um teste de Força contra todos os alvos próximos. Alvos atingidos são empurrados para um ponto em alcance distante e devem fazer um teste de reação (17). Quem falhar, sofre 4d10+8 de dano. Quem passar sofre metade do dano.'),
(267, 'Manter Posição', 'Valor', 9, 1, 'Talento', 'Descreva a posição defensiva que você assume e gaste 1 Ponto de Esperança. Se um adversário se mover para alcance muito próximo, ele é puxado para o alcance corpo a corpo e fica Imobilizado. Esta condição dura até você se mover ou rolar uma falha com Medo, ou até o mestre gastar 2 Pontos de Medo no turno dele para encerrá-la.'),
(268, 'Líder Exemplar', 'Valor', 9, 3, 'Talento', 'Ao causar dano a um adversário, você pode marcar 1 PF e descrever como encoraja seus aliados. O próximo personagem que atacar esse adversário pode recuperar 1 Ponto de Fadiga ou receber 1 Ponto de Esperança.'),
(269, 'Invencível', 'Valor', 10, 4, 'Talento', 'Ao marcar seu último Ponto de Vida, em vez de fazer um movimento de morte, você pode recuperar 1d6 Pontos de Vida. Em seguida, esta carta vai para sua reserva.'),
(270, 'Defesa Irredutível', 'Valor', 10, 1, 'Talento', 'Quando for marcar 1 Ponto de Armadura, role uma quantidade de d6 igual à sua Proficiência. Se algum tirar 6, reduza a gravidade em um limiar sem marcar 1 Ponto de Armadura.');
INSERT INTO INIMIGOS (ID, NOME, PATAMAR, PAPEL, CONTAGEM_HORDA, DESCRICAO, TATICAS, DIFICULDADE, LIMIARES, PV_MAXIMO, PF_MAXIMO, BONUS_ATAQUE, NOME_ATAQUE, DANO_ATAQUE, EXPERIENCIAS, HABILIDADES, IMAGEM) VALUES
(1, 'Arbusto Espinhento', 1, 'Lacaio', '', 'Um aglomerado de vinhas sanguinárias.', 'combinar, drenar, enrolar', 11, 'nenhum', 1, 1, '-1', 'Espinhos: corpo a corpo', '2 fís', '', '[{"name":"Lacaio (4)","type":"Passiva","description":"o arbusto-espinhento é derrotado quando sofre qualquer dano. Para cada 4 pontos de dano causados por um personagem ao arbusto, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os arbustos espinhentos Próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 2 pontos de dano físico. Os danos são somados."},{"name":"Drenar e Multiplicar","type":"Reação","description":"quando há três ou mais lacaios arbustos espinhentos Próximos e um ataque deste arbusto espinhento faz um alvo marcar Pontos de Vida, você pode combinar os lacaios em um enxame de arbustos. Os Pontos de Vida da horda equivalem ao número de lacaios combinados."}]', 'img/enemies/enemy_p4_161.png'),
(2, 'Enxame de Arbustos', 1, 'Horda', '3/PV', 'Um aglomerado de vinhas sanguinárias, cada uma tão grande quanto uma cabaça.', 'digerir, enrolar, imobilizar', 12, '6/11', 6, 3, '+0', 'Espinhos: corpo a corpo', '1d6+3 fís', 'Camuflagem +2', '[{"name":"Horda (1d4+2)","type":"Passiva","description":"quando os arbustos tiverem marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 1d4+2 pontos de dano físico, em vez do valor original."},{"name":"Esmagar","type":"Ação","description":"marque 1 Ponto de Fadiga para causar 2d6+8 pontos de dano físico direto a um alvo com 3 Marcadores de Arbusto ou mais."},{"name":"Atravancar","type":"Reação","description":"quando o arbusto acertar um ataque, o alvo recebe 1 Marcador de Arbusto. Um alvo com 1 marcador fica Imobilizado. Um alvo com 3 marcadores ou mais fica Vulnerável. Todos os marcadores de Arbusto podem ser removidos com sucesso em um teste de Acuidade (12 + o número de marcadores no alvo) ou causando dano maior ou superior ao enxame. Se um alvo remover Marcadores de Arbusto com um teste, uma quantidade de lacaios arbustos-espinhentos igual ao número de marcadores removidos surge em um ponto em alcance corpo a corpo."}]', 'img/enemies/enemy_p4_161.png'),
(3, 'Bando de Ratos', 1, 'Horda', '10/PV', 'Um amontoado de roedores se movendo como uma onda faminta.', 'consumir, enxamear, obscurecer', 10, '6/10', 6, 2, '-3', 'Garras: corpo a corpo', '1d8+2 fís', '', '[{"name":"Horda (1d4+1)","type":"Passiva","description":"quando o bando de ratos tiver marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 1d4+1 pontos de dano físico, em vez do valor original."},{"name":"Por Toda Parte","type":"Passiva","description":"todos os alvos em alcance cac fazem testes de ataque contra alvos que não sejam o bando com desvantagem."}]', 'img/enemies/enemy_p10_346.png'),
(4, 'Cobra-De-Vidro', 1, 'Comum', '', 'Uma serpente translúcida com uma cabeça imensa, que deixa um rastro de vidro por onde passa.', 'assustar, comer, escalar, manter distância', 14, '6/10', 5, 3, '+2', 'Presas de vidro: muito próximo', '1d8+2 fís', '', '[{"name":"Cacos Antiarmadura","type":"Passiva","description":"após acertar um ataque corpo a corpo contra a cobra-de-vidro, o atacante deve marcar 1 Ponto de Armadura. Se não for possível marcar 1 Ponto de Armadura, o atacante deve marcar 1 PV."},{"name":"Cuspideira","type":"Ação","description":"gaste 1 Ponto de Medo para transformar 1d6 no Dado de Cuspida. Quando a cobra-de-vidro estiver em foco, role esse dado. Se rolar 5 ou mais, todos os alvos distantes na frente da cobra-de-vidro devem passar em um teste de reação de Agilidade, ou sofrem 1d4 pontos de dano físico. Além disso, a cobra-de-vidro pode ser posta em foco uma segunda vez durante este turno do mestre."},{"name":"Serpente Giratória","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra todos os alvos muito próximos. Alvos atingidos por este ataque sofrem 1d6+1 pontos de dano físico."}]', 'img/enemies/enemy_p2_107.png'),
(5, 'Comerciante', 1, 'Manipulador', '', 'Um mercador bem trajado com olhar aguçado para obter lucro.', 'buscar lucro, comprar barato e vender caro, criar demanda, inflar preços', 12, '4/8', 3, 3, '-4', 'Porrete: corpo a corpo', '1d4+1 fís', 'Negociante Astuto +3', '[{"name":"Enrolação","type":"Passiva","description":"quando um personagem rolar 14 ou menos em testes de Presença contra o comerciante, ele deve marcar 1 Ponto de Fadiga."},{"name":"Tratamento Preferencial","type":"Passiva","description":"um personagem que passar num teste de Presença contra o comerciante recebe um desconto em suas compras. Enquanto quem falhou deve pagar mais caro e sofre desvantagem em futuros testes de Presença contra o comerciante."}]', 'img/enemies/enemy_p17_518.png'),
(6, 'Construto', 1, 'Solo', '', 'Quase um humanoide de pedra e aço, feito e animado por magia.', 'atropelar grupos, destruir ambientes, esmagar alvo, servir criador', 13, '7/15', 9, 4, '+4', 'Punhos poderosos: corpo a corpo', '1d20 fís', '', '[{"name":"Estrutura frágil","type":"Passiva","description":"quando o construto marca Pontos de Vida por dano físico, ele marca 1 PV adicional."},{"name":"Inclemente (2)","type":"Passiva","description":"o construto pode ser posto em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Atropelar","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra todos os alvos no caminho do construto enquanto ele se move. Alvos atingidos sofrem 1d8 pontos de dano físico."},{"name":"Sobrecarga","type":"Reação","description":"antes de rolar dano do ataque do construto, você pode marcar 1 Ponto de Fadiga para receber um bônus de +10 na rolagem de dano. Então ponha o construto em foco novamente."},{"name":"Terremoto da Morte","type":"Reação","description":"quando o construto marcar seu último Ponto de Vida, a magia que o sustenta rompe em uma explosão de força. Faça um ataque com vantagem contra todos os alvos muito próximos. Alvos atingidos sofrem 1d12+2 pontos de dano mágico."}]', 'img/enemies/enemy_p13_426.png'),
(7, 'Defensor Enraizado', 1, 'Brutamonte', '', 'Uma pessoa-vegetal robusta com vinhas capazes de agarrar.', 'agarrar, emboscar, proteger, socar', 10, '8/14', 7, 3, '+2', 'Vinhas: Próximo', '1d8+3 fís', 'Imenso+3', '[{"name":"Arrebatar","type":"Ação","description":"faça um ataque contra um alvo Próximo. Se o atingir, gaste 1 Ponto de Medo para puxá-lo para um ponto em alcance corpo a corpo, causando 1d6+2 pontos de dano físico e deixando-o Imobilizado até que o defensor sofra dano grave."},{"name":"Golpear o chão","type":"Ação","description":"golpeie o chão, empurrando todos os alvos muito próximos para um ponto em alcance distante. Cada alvo empurrado deve marcar 1 Ponto de Fadiga."}]', 'img/enemies/enemy_p4_161.png'),
(8, 'Demônio Menor', 1, 'Solo', '', 'Uma criatura avermelhada vinda dos Círculos Inferiores, consumida por sua ira contra todos os mortais.', 'encurralar, flagelar, ser errático, sorver dor', 14, '8/15', 8, 4, '+3', 'Garras: corpo a corpo', '1d8+6 fís', '', '[{"name":"Inclemente (2)","type":"Passiva","description":"o demônio pode ser posto em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Tudo Deve Ruir","type":"Passiva","description":"se um personagem estiver próximo do demônio e falhar com Medo, ele perde 1 Ponto de Esperança."},{"name":"Fogo Infernal","type":"Ação","description":"gaste 1 Ponto de Medo para fazer chover o fogo do inferno em alcance Próximo. Alvos na área devem fazer um teste de reação de Agilidade, quem falhar sofre 1d20+3 pontos de dano mágico. Quem passar sofre metade do dano."},{"name":"Ceifador","type":"Reação","description":"antes da rolagem de dano do demônio, você pode marcar 1 Ponto de Fadiga para aumentar o dano causado em uma quantidade igual aos PV marcados do demônio."},{"name":"Impulso","type":"Reação","description":"quando o demônio acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p2_109.png'),
(9, 'Dríade Jovem', 1, 'Líder', '', 'Uma pessoa-árvore autoritária que lidera as defesas da floresta.', 'comandar, eliminar intrusos, nutrir', 11, '6/11', 6, 2, '+0', 'Foice: corpo a corpo', '1d8+5 fís', 'Liderança +3', '[{"name":"Prisão de Espinhos","type":"Ação","description":"gaste 1 Ponto de Medo para formar uma jaula ao redor de um alvo muito próximo. O alvo fica Imobilizado até ter sucesso em um teste de Força. Se uma criatura fizer um teste contra a jaula, ela deve marcar 1 PF."},{"name":"Voz da Floresta","type":"Ação","description":"marque 1 Ponto de Fadiga para pôr em foco 1d4 aliados que possam atacar um mesmo alvo sem se mover. Se passar, ataques destes aliados causam metade do dano."},{"name":"Impulso","type":"Reação","description":"quando a dríade acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p4_161.png'),
(10, 'Elemental Menor do Caos', 1, 'Solo', '', 'Uma massa reluzente de magia incontrolável.', 'confundir, desestabilizar, metamorfosear', 14, '7/14', 7, 3, '+3', 'Golpe distorcido: Próximo', '1d12+6 mág', '', '[{"name":"Forma Arcana","type":"Passiva","description":"o elemental é resistente a dano mágico."},{"name":"Fluxo Pestilento","type":"Ação","description":"marque 1 Ponto de Vida para forçar todos os alvos Próximos a marcar 1 Ponto de Fadiga e ficarem Vulneráveis até o próximo descanso ou até que recuperem 1 PV."},{"name":"Refazer Realidade","type":"Ação","description":"gaste 1 Ponto de Medo para transformar a área próxima em um bioma diferente. Todos os alvos na área sofrem 2d6+3 pontos de dano mágico direto."},{"name":"Impulso","type":"Reação","description":"quando o elemental acerta um ataque contra um personagem, receba 1 Ponto de Medo."},{"name":"Reflexo Mágico","type":"Reação","description":"quando o elemental sofre dano de um ataque Próximo, causa metade do dano sofrido ao atacante."}]', 'img/enemies/enemy_p4_157.png'),
(11, 'Elemental Menor do Fogo', 1, 'Solo', '', 'Uma chama viva do tamanho de uma fogueira grande.', 'aumentar de tamanho, cercar inimigos, incendiar, intimidar', 13, '7/15', 9, 3, '+3', 'Golpe elemental: distante', '1d10+4 mág', '', '[{"name":"Inclemente (2)","type":"Passiva","description":"o elemental pode ser posto em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Explosão","type":"Ação","description":"gaste 1 Ponto de Medo para explodir em chamas. Faça um ataque contra todos os alvos Próximos. Alvos atingidos pelo elemental sofrem 1d8 pontos de dano mágico e são empurrados para um ponto em alcance distante."},{"name":"Queimada","type":"Ação","description":"marque 1 Ponto de Fadiga para escolher um ponto em alcance distante. O chão muito próximo desse ponto é imediatamente tomado por chamas. Todas as criaturas na área devem fazer um teste de reação de Agilidade. Alvos que falhem no teste sofrem 2d8 pontos de dano mágico pelas chamas. Alvos que passem sofrem metade do dano."},{"name":"Consumir Chamas","type":"Reação","description":"três vezes por cena, quando o elemental passar por objetos que sejam muito inflamáveis, consuma-os para recuperar 1 PV ou 1 PF."},{"name":"Impulso","type":"Reação","description":"quando o elemental acerta um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p4_159.png'),
(12, 'Ente Menor', 1, 'Lacaio', '', 'Uma muda ambulante que se ergueu para defender sua floresta.', 'esmagar, proteger, sobrecarregar', 10, 'nenhum', 1, 1, '-2', 'Galho-garra: corpo a corpo', '4 fís', '', '[{"name":"Lacaio (5)","type":"Passiva","description":"o ente menor é derrotado quando sofre qualquer dano. Para cada 5 pontos de dano causados por um personagem ao ente menor, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os entes menores Próximos dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 4 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p4_161.png'),
(13, 'Escorpião Gigante', 1, 'Brutamonte', '', 'Um aracnídeo grande como um homem com garras terríveis e um ferrão na cauda.', 'alimentar-se, agarrar, emboscar, envenenar', 13, '7/13', 6, 3, '+1', 'Pinças: corpo a corpo', '1d12+2 fís', 'Camuflagem +2', '[{"name":"Ataque Duplo","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque padrão contra dois alvos corpo a corpo."},{"name":"Ferrão Peçonhento","type":"Ação","description":"faça um ataque contra um alvo muito próximo. Em caso de sucesso, gaste 1 Ponto de Medo para que o alvo sofra 1d4+4 pontos de dano físico e fique Envenenado até seu próximo descanso ou até que passe em um teste de Conhecimento (16). Enquanto estiver Envenenado, o alvo deve rolar 1d6 antes de todos seus testes. Se rolar 4 ou menos, o alvo deve marcar 1 Ponto de Fadiga."},{"name":"Impulso","type":"Reação","description":"quando o escorpião acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p10_346.png'),
(14, 'Esqueleto Arqueiro', 1, 'Atirador', '', 'Um esqueleto frágil com um arco curto e flechas.', 'fingir de morto, perfurar alvos distraídos, roubar pele', 9, '4/7', 3, 2, '+2', 'Arco curto: distante', '1d8+1 fís', '', '[{"name":"Oportunista","type":"Passiva","description":"quando dois ou mais adversários estiverem muito próximos de uma criatura, todo o dano causado pelo esqueleto arqueiro na criatura é dobrado."},{"name":"Tiro Mortal","type":"Ação","description":"faça um ataque contra um alvo distante que esteja Vulnerável. Se acertar, marque 1 Ponto de Fadiga e cause 3d4+8 pontos de dano físico."}]', 'img/enemies/enemy_p5_200.png'),
(15, 'Esqueleto Arruinado', 1, 'Lacaio', '', 'Uma pilha barulhenta de ossos.', 'desmoronar, fingir de morto, sobrecarregar, roubar pele', 8, 'nenhum', 1, 1, '-1', 'Garras ósseas: corpo a corpo', '1 fís', '', '[{"name":"Lacaio (4)","type":"Passiva","description":"o esqueleto arruinado é derrotado quando sofre qualquer dano. Para cada 4 pontos de dano causados por um personagem ao esqueleto, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os esqueletos arruinados Próximos dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 1 ponto de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p5_202.png'),
(16, 'Esqueleto Guerreiro', 1, 'Comum', '', 'Um esqueleto empoeirado, armado com uma lâmina enferrujada.', 'agrupar, fingir de morto, roubar pele', 10, '4/8', 3, 2, '+0', 'Espada: corpo a corpo', '1d6+2 fís', '', '[{"name":"Puro Osso","type":"Passiva","description":"o guerreiro é resistente a dano físico."},{"name":"Nunca Morre","type":"Reação","description":"quando o esqueleto é derrotado, você pode colocá-lo em foco e rolar 1d6. Se rolar 6 e houver outros adversários na cena, o esqueleto se monta novamente e desmarca todos os PV."}]', 'img/enemies/enemy_p5_204.png'),
(17, 'Esqueleto Cavaleiro', 1, 'Brutamonte', '', 'Um grande esqueleto blindado com uma espada imensa.', 'destruir, matar os vivos, roubar pele', 13, '7/13', 5, 2, '+2', 'Espada grande enferrujada: cac', '1d10+2 fís', '', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o cavaleiro acertar um ataque, todos os personagens Próximos perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Cortar Até o Osso","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra todos os alvos muito próximos. Alvos atingidos pelo cavaleiro sofrem 1d8+2 pontos de dano físico e devem marcar 1 Ponto de Fadiga."},{"name":"Cova Dupla","type":"Reação","description":"quando o cavaleiro é derrotado, faça um ataque contra um alvo muito próximo (priorizando a criatura que derrotou o cavaleiro). Em caso de sucesso, o alvo sofre 1d4+8 pontos de dano físico e perde 1d4 Pontos de Esperança."}]', 'img/enemies/enemy_p5_198.png'),
(18, 'Guarda Armado', 1, 'Comum', '', 'Um guarda de armadura portando uma espada e um escudo pintado com as cores do assentamento.', 'chegar ao fim do dia, fechar portões, imobilizar, prender', 12, '5/9', 5, 2, '+1', 'Espada longa: corpo a corpo', '1d6+1 fís', 'Conhecimento Local +3', '[{"name":"Parede de Escudos","type":"Passiva","description":"uma criatura que tente se mover para muito próximo do guarda precisa passar em um teste de Agilidade. Se outros guardas armados estiverem em fila ao lado deste, e cada um estiver corpo a corpo ao próximo da fila, a Dificuldade aumenta em um número igual ao total de guardas armados em fila."},{"name":"Deter","type":"Ação","description":"faça um ataque contra um alvo muito próximo. Em caso de sucesso, marque 1 Ponto de Fadiga para Imobilizar o alvo até que se liberte com sucesso em um teste de ataque, um teste de Acuidade ou um teste de Força."}]', 'img/enemies/enemy_p14_450.png'),
(19, 'Guarda Arqueiro', 1, 'Atirador', '', 'Um guarda alto portando um arco longo e uma aljava com flechas nas cores do assentamento.', 'chegar ao fim do dia, fechar portões, imobilizar, prender', 10, '4/8', 3, 2, '+1', 'Arco longo: distante', '1d8+3 fís', 'Conhecimento Local +3', '[{"name":"Tiro Debilitante","type":"Ação","description":"faça um ataque contra um alvo distante. Em caso de sucesso, marque 1 Ponto de Fadiga para causar 1d12+3 pontos de dano físico. Um alvo que marque Pontos de Vida por causa deste ataque sofre desvantagem em testes de Agilidade até que recupere ao menos 1 Ponto de Vida."}]', 'img/enemies/enemy_p14_450.png'),
(20, 'Guarda Chefe', 1, 'Líder', '', 'Um guarda experiente com uma maça, um apito e um vozeirão.', 'buscar glória, fechar portões, imobilizar, prender', 15, '7/13', 7, 3, '+4', 'Maça: corpo a corpo', '1d10+4 fís', 'Comandante +2, Conhecimento Local +2', '[{"name":"Reunir a Guarda","type":"Ação","description":"gaste 2 Pontos de Medo para pôr o guarda chefe em foco junto de até 2d4 aliados Distantes."},{"name":"Ao Meu Sinal","type":"Reação","description":"Contagem (5). Quando o guarda chefe é posto em foco pela primeira vez, ative a contagem regressiva e a diminua sempre que um personagem fizer um teste de ataque. Quando a contagem chegar a zero, todos os guardas arqueiros em alcance distante fazem um ataque padrão com vantagem contra os alvos mais próximos de seus respectivos alcances. Se um alvo sofrer mais de um ataque, some os danos recebidos."},{"name":"Impulso","type":"Reação","description":"quando um ataque do guarda chefe atingir um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p14_450.png'),
(21, 'Guerreiro Arcano', 1, 'Líder', '', 'Um mercenário que combina aço e magia de maneira letal.', 'comandar, golpear, resistir', 14, '8/14', 6, 3, '+3', 'Espada longa mágica: cac', '1d8+4 fís/mág', 'Conhecimento Mágico +2', '[{"name":"Aço Arcano","type":"Passiva","description":"o dano causado pelo ataque padrão do guerreiro arcano é considerado físico e mágico."},{"name":"Explosão Opressora","type":"Ação","description":"marque 1 Ponto de Fadiga e escolha um grupo em alcance distante. Todos os alvos devem passar em um teste de reação de Agilidade ou sofrem 1d8+2 pontos de dano mágico. Receba 1 Ponto de Medo para cada alvo que marcar PV por esse ataque."},{"name":"Movimento de Unidade","type":"Ação","description":"gaste 2 Pontos de Medo para pôr em foco até cinco aliados Distantes."},{"name":"Impulso","type":"Reação","description":"quando o guerreiro arcano acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p17_518.png'),
(22, 'Lobo Atroz', 1, 'Oportunista', '', 'Um grande lobo com dentes ameaçadores, raramente visto sozinho.', 'arrastar, atormentar, cercar, defender território, proteger alcateia', 12, '5/9', 4, 3, '+2', 'Garras: corpo a corpo', '1d6+2 fís', 'Sentidos Aguçados +3', '[{"name":"Táticas de Bando","type":"Passiva","description":"se o lobo acertar um ataque padrão e houver outro lobo-atroz corpo a corpo do alvo, ele causa 1d6+5 pontos de dano físico em vez do dano do ataque padrão e receba 1 Ponto de Medo."},{"name":"Golpe Debilitante","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra um alvo corpo a corpo. Em caso de sucesso, o alvo sofre 3d4+10 pontos de dano físico direto e fica Vulnerável até que recupere ao menos 1 Ponto de Vida."}]', 'img/enemies/enemy_p18_544.png'),
(23, 'Lodo Verde', 1, 'Oportunista', '', 'Um monte vivo feito de gosma verde translúcida.', 'camuflagem, consumir e se multiplicar, envolver, esgueirar', 8, '5/10', 5, 2, '+1', 'Tentáculo de lodo: corpo a corpo', '1d6+1 mág', 'Camuflagem +3', '[{"name":"Forma Ácida","type":"Passiva","description":"quando o lodo acertar um ataque, o alvo deve marcar 1 Ponto de Armadura sem receber seus benefícios (mas ainda pode usar PA para reduzir o dano). Caso não possa marcar 1 PA, o alvo deve marcar 1 Ponto de Vida adicional."},{"name":"Lentidão","type":"Passiva","description":"se o lodo for posto em foco, mas não tiver nenhum marcador em sua ficha, ele é incapaz de agir. Coloque um marcador na ficha e descreva o que ele está se preparando para fazer. Quando puser o lodo em foco e ele tiver um marcador na ficha, remova o marcador para que ele possa agir."},{"name":"Envolver","type":"Ação","description":"faça um ataque padrão em um alvo corpo a corpo. Em caso de sucesso, o lodo Envolve o alvo, que deve marcar 2 Pontos de Fadiga. Alvos Envolvidos devem marcar 1 PF adicional ao fazer um teste. Se o lodo sofrer dano grave, o alvo é libertado."},{"name":"Agora São Dois","type":"Reação","description":"quando o lodo já tiver marcado 3 PV ou mais, você pode gastar 1 Ponto de Medo para dividi-lo em dois lodos verdes pequenos (sem PV ou PF marcados). Ponha ambos em foco imediatamente."}]', 'img/enemies/enemy_p7_268.png'),
(24, 'Lodo Verde Pequeno', 1, 'Oportunista', '', 'Um montinho vivo feito de gosma verde translúcida.', 'camuflagem, esgueirar', 14, '4/nenhum', 2, 1, '-1', 'Tentáculo de lodo: corpo a corpo', '1d4+1 mág', '', '[{"name":"Forma Ácida","type":"Passiva","description":"quando o lodo acertar um ataque, o alvo deve marcar 1 Ponto de Armadura sem receber seus benefícios (mas ainda pode usar PA para reduzir o dano). Caso não possa marcar 1 PA, o alvo deve marcar 1 Ponto de Vida adicional."}]', 'img/enemies/enemy_p7_268.png'),
(25, 'Lodo Vermelho', 1, 'Oportunista', '', 'Um monte vivo feito de gosma vermelha flamejante.', 'camuflagem, incendiar, inflamar, multiplicar', 10, '6/11', 5, 3, '+1', 'Tentáculo de lodo: corpo a corpo', '1d8+3 mág', 'Camuflagem +3', '[{"name":"Fogo Crepitante","type":"Passiva","description":"o lodo só pode se mover em alcance muito próximo com seu movimento normal. Ele incendeia qualquer objeto inflamável que toca."},{"name":"Incendiar","type":"Ação","description":"faça um ataque contra um alvo muito próximo. Em caso de sucesso, o alvo sofre 1d8 pontos de dano mágico e fica Em Chamas até que o fogo seja apagado com suceso em um teste de Acuidade (14). Enquanto estiver Em Chamas, o alvo sofre 1d4 pontos de dano mágico sempre que fizer um teste."},{"name":"Agora São Dois","type":"Reação","description":"quando o lodo já tiver marcado 3 PV ou mais, você pode gastar 1 Ponto de Medo para dividi-lo em dois lodos vermelhos pequenos (sem PV ou PF marcados). Ponha ambos em foco imediatamente."}]', 'img/enemies/enemy_p7_260.png'),
(26, 'Lodo Vermelho Pequeno', 1, 'Oportunista', '', 'Um montinho vivo feito de gosma vermelha flamejante.', 'camuflagem, pegar fogo', 11, '5/nenhum', 2, 1, '-1', 'Tentáculo de lodo: corpo a corpo', '1d4+2 mág', '', '[{"name":"Incandescente","type":"Reação","description":"quando uma criatura corpo a corpo causa dano ao lodo, ela sofre 1d6 pontos de dano mágico direto."}]', 'img/enemies/enemy_p7_270.png'),
(27, 'Mercenário', 1, 'Lacaio', '', 'Um mercenário armado testando a própria sorte.', 'avançar, dilacerar, lucrar, sobrecarregar', 10, 'nenhum', 1, 1, '+3', 'Espada longa: corpo a corpo', '3 fís', '', '[{"name":"Lacaio (4)","type":"Passiva","description":"o mercenário é derrotado quando sofre qualquer dano. Para cada 4 pontos de dano causados por um personagem ao mercenário, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os mercenários Próximos dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 3 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p8_292.png'),
(28, 'Mestre de Armas', 1, 'Brutamonte', '', 'Um mestre de armas porta uma espada com o dobro de seu tamanho.', 'agir primeiro, atacar os mais fracos, intimidar', 14, '8/15', 6, 3, '+2', 'Claymore: muito próximo', '1d12+2 fís', '', '[{"name":"Ataque Provocante","type":"Ação","description":"faça um ataque padrão contra um alvo. Em caso de sucesso, marque 1 Ponto de Fadiga para Provocar o alvo até o próximo ataque que ele acertar. Na próxima vez que um alvo Provocado atacar, ele sofre desvantagem contra alvos que não sejam o mestre de armas."},{"name":"Explosão de Adrenalina","type":"Ação","description":"uma vez por cena, gaste 1 Ponto de Medo para recuperar 2 Pontos de Vida e 2 Pontos de Fadiga."},{"name":"Impulso","type":"Reação","description":"quando o mestre de armas acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p14_450.png'),
(29, 'Mosquitos Gigantes', 1, 'Horda', '5/PV', 'Dúzias de mosquitos grandes como punhos, voando juntos como forma de proteção.', 'incomodar, roubar sangue, voar para longe', 10, '5/9', 6, 3, '-2', 'Probóscida: corpo a corpo', '1d8+3 fís', 'Camuflagem +2', '[{"name":"Horda (1d4+1)","type":"Passiva","description":"quando os mosquitos tiverem marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 1d4+1 pontos de dano físico, em vez do valor original."},{"name":"Voador","type":"Passiva","description":"quando estiverem em voo, os mosquitos recebem um bônus de +2 em sua Dificuldade."},{"name":"Hematófago","type":"Reação","description":"quando o ataque dos mosquitos faz com que um alvo marque Pontos de Vida, você pode marcar 1 Ponto de Fadiga para forçar o alvo a marcar 1 PV adicional."}]', 'img/enemies/enemy_p10_346.png'),
(30, 'Nobre Menor', 1, 'Manipulador', '', 'Um aristocrata muito bem-vestido exalando arrogância.', 'abusar de seu poder, mobilizar lacaios, obter recursos', 14, '6/10', 3, 5, '-3', 'Rapieira: corpo a corpo', '1d6+1 fís', 'Aristocrata +3', '[{"name":"Minha Terra, Minhas Regras","type":"Passiva","description":"todas as ações sociais feitas contra o nobre em suas terras sofrem desvantagem."},{"name":"Exilar","type":"Ação","description":"gaste 1 Ponto de Medo e escolha um personagem. O nobre proclama que o alvo e seus aliados sejam exilados de seu território. Enquanto estiverem exilados, o alvo e seus aliados sofrem desvantagem em situações sociais nos domínios do nobre."},{"name":"Guardas!","type":"Ação","description":"uma vez por cena, marque 1 Ponto de Fadiga para invocar 1d4 guardas armados, que surgem em um ponto em alcance distante para atender às vontades do nobre."}]', 'img/enemies/enemy_p17_518.png'),
(31, 'Ogro das Cavernas', 1, 'Solo', '', 'Um imenso humanoide que vê toda criatura senciente como comida.', 'arrancar cabeças com mordidas, arrancar membros, arremessar inimigos, devorar, pisotear', 13, '8/15', 8, 3, '+1', 'Porrete: muito próximo', '1d10+2 fís', 'Arremesso +2', '[{"name":"Aceleração","type":"Passiva","description":"você deve gastar 1 Ponto de Medo para pôr o ogro em foco. Quando estiver em foco, ele pode fazer um ataque padrão contra todos os alvos dentro do alcance."},{"name":"Arrebentar Ossos","type":"Passiva","description":"ataques do ogro causam dano direto."},{"name":"Chuva de Pedregulhos","type":"Ação","description":"marque 1 Ponto de Fadiga para levantar objetos pesados e arremessá-los em todos os alvos distantes na frente do ogro. Faça um ataque contra esses alvos, aqueles atingidos pelo ogro sofrem 1d10+2 pontos de dano físico. Caso o ogro atinja mais de um alvo, receba 1 Ponto de Medo."},{"name":"Fúria Violenta","type":"Reação","description":"quando o ogro marcar 2 Pontos de Vida ou mais, ele pode entrar em fúria. Movimente o ogro para um ponto em alcance Próximo e cause 2d6+3 pontos de dano físico direto em todos os alvos no caminho."}]', 'img/enemies/enemy_p16_492.png'),
(32, 'Palaciano', 1, 'Manipulador', '', 'Um socialite ambicioso vestido de maneira ostensiva.', 'bajular, descreditar, manobrar, planejar', 12, '4/8', 3, 4, '-4', 'Adagas: corpo a corpo', '1d4+2 fís', 'Socialite +3', '[{"name":"Bode Expiatório","type":"Ação","description":"gaste 1 Ponto de Medo para marcar um personagem como alvo. O palaciano convence uma multidão de indivíduos proeminentes de que o alvo é a causa de todos os seus conflitos e infortúnios."},{"name":"Zombaria","type":"Ação","description":"marque 1 Ponto de Fadiga para dizer algo em tom de zombaria, forçando um alvo Próximo a fazer um teste de reação de Presença (14) para se safar. Se falhar, o alvo deve marcar 2 Pontos de Fadiga e fica Vulnerável até o fim da cena."}]', 'img/enemies/enemy_p17_518.png'),
(33, 'Pirata Bruto', 1, 'Brutamonte', '', 'Um pirata musculoso e tatuado com punhos grandes como melões.', 'aterrorizar, esmagar, pilhar, saquear', 13, '8/15', 5, 3, '+1', 'Punhos massivos: corpo a corpo', '2d6 fís', 'Marinheiro +2', '[{"name":"Espadachim","type":"Passiva","description":"Quando o pirata bruto marcar 2 Pontos de Vida ou menos por um ataque realizado dentro de alcance corpo a corpo, o atacante deve marcar 1 Ponto de Fadiga."},{"name":"Limpar o Convés","type":"Ação","description":"Faça um ataque contra um alvo muito próximo. Em caso de sucesso, marque 1 Ponto de Fadiga para se mover até alcance corpo a corpo do alvo, causando 3d4 pontos de dano físico e empurrando alvo para um ponto em alcance Próximo."}]', 'img/enemies/enemy_p8_292.png'),
(34, 'Pirata Capitão', 1, 'Líder', '', 'Um lobo do mar carismático com um chapéu impressionante, sempre disposto a pilhar e saquear.', 'mandar para prancha, ordenar, pilhar, saquear', 14, '7/14', 7, 5, '+4', 'Sabre de abordagem: corpo a corpo', '1d12+2 fís', 'Comandante +2, Marinheiro +3', '[{"name":"Espadachim","type":"Passiva","description":"quando o capitão marcar 2 Pontos de Vida ou menos por um ataque corpo a corpo, o atacante deve marcar 1 Ponto de Fadiga."},{"name":"Reforços","type":"Ação","description":"uma vez por cena, marque 1 Ponto de Fadiga para invocar uma horda de piratas saqueadores, que surge em um ponto em alcance distante."},{"name":"Sem prisioneiros","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo que tenha três ou mais piratas corpo a corpo. O capitão inspira os piratas com bravatas e promessas da morte do alvo, que deve fazer um teste de reação de Presença. Se falhar, o alvo deve marcar 1d4+1 Pontos de Fadiga. Se passar, o alvo deve marcar 1 PF."},{"name":"Impulso","type":"Reação","description":"quando o capitão acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p8_292.png'),
(35, 'Piratas Saqueadores', 1, 'Horda', '3/PV', 'Um grupo sanguinário de bandidos dos mares.', 'ameaçar em grupo, pilhar, saquear', 12, '5/11', 4, 3, '+1', 'Sabre de abordagem: corpo a corpo', '1d8+2 fís', 'Marinheiro +3', '[{"name":"Espadachim","type":"Passiva","description":"quando os saqueadores marcarem 2 Pontos de Vida ou menos por um ataque corpo a corpo, o atacante deve marcar 1 Ponto de Fadiga."},{"name":"Horda (1d4+1)","type":"Passiva","description":"quando os saqueadores tiverem marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 1d4+1 pontos de dano físico, em vez do valor original."}]', 'img/enemies/enemy_p8_292.png'),
(36, 'Punhal Escarpado, Bandido', 1, 'Comum', '', 'Um criminoso ardiloso com a faca icônica de sua gangue.', 'fugir, lucrar, roubar, usar fumaça', 12, '8/14', 5, 3, '+1', 'Adagas: corpo a corpo', '1d8+1 fís', 'Ladino +2', '[{"name":"Aqui em Cima","type":"Passiva","description":"quando o bandido acerta um ataque padrão vindo de cima do alvo, ele causa 1d10+1 pontos de dano físico em vez do dano padrão."},{"name":"Escalador","type":"Passiva","description":"o bandido é capaz de escalar tão facilmente quanto corre."}]', 'img/enemies/enemy_p8_292.png'),
(37, 'Punhal Escarpado, Brigão', 1, 'Brutamonte', '', 'Um fortão imponente com um grande porrete.', 'agarrar, intimidar, lucrar, roubar', 12, '7/14', 7, 4, '-3', 'Porrete: corpo a corpo', '1d4+6 fís', 'Ladino +2, Ameaça Explícita +3', '[{"name":"Peguei, Chefia","type":"Passiva","description":"criaturas Imobilizadas pelo brigão sofrem dano dobrado em ataques de outros adversários."},{"name":"Segurar","type":"Ação","description":"faça um ataque contra um alvo corpo a corpo. Em caso de sucesso, o alvo não sofre dano, mas fica Imobilizado e Vulnerável. O alvo pode se libertar das duas condições com sucesso em um teste de Força ou se o brigão do punhal escarpado sofrer dano maior ou superior."}]', 'img/enemies/enemy_p9_322.png'),
(38, 'Punhal Escarpado, Bruxo', 1, 'Assistente', '', 'Um bandido de cajado, vestindo uma capa adornada com parafernália mágica, que usa feitiços contra seus inimigos.', 'comandar, enfeitiçar, lucrar', 13, '5/9', 4, 4, '+2', 'Cajado: distante', '1d6+2 mág', 'Conhecimento Mágico +2', '[{"name":"Amaldiçoar","type":"Ação","description":"escolha um alvo distante para ser temporariamente Amaldiçoado. Enquanto o alvo estiver Amaldiçoado, você pode marcar 1 Ponto de Fadiga para forçar as rolagens com Esperança do alvo a serem rolagens com Medo."},{"name":"Fluxo caótico","type":"Ação","description":"faça um ataque contra até três alvos muito próximos. Marque 1 Ponto de Fadiga para que todos os alvos atingidos pelo ataque sofram 2d6+3 pontos de dano mágico."}]', 'img/enemies/enemy_p9_324.png'),
(39, 'Punhal Escarpado, Chefe', 1, 'Líder', '', 'Um bandido veterano bem-vestido, com voz poderosa e olhar astuto.', 'chamar reforços, comandar, lucrar, valentia', 13, '7/14', 6, 3, '+2', 'Dardo: próximo', '1d8+3 fís', 'Conhecimento local +2', '[{"name":"Golpe de Misericórdia","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque contra um alvo próximo que esteja Vulnerável. Em caso de sucesso, o alvo sofre 2d6+12 pontos de dano físico e deve marcar 1 Ponto de Fadiga."},{"name":"Táticas","type":"Ação","description":"quando puser o chefe em foco, marque 1 Ponto de Fadiga para também pôr dois aliados próximos em foco."},{"name":"Tem Mais de Onde Veio","type":"Ação","description":"invoque três ladrões do punhal escarpado, que surgem em um ponto em alcance distante."},{"name":"Impulso","type":"Reação","description":"quando o chefe acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p9_326.png'),
(40, 'Punhal Escarpado, Ladrão', 1, 'Lacaio', '', 'Um ladrão com roupas simples e um pequeno punhal, tentando mostrar a que veio.', 'escapar, jogar fumaça, lucrar', 9, 'Nenhum', 1, 1, '-2', 'Adagas: corpo a corpo', '2 fís', 'Ladino +2', '[{"name":"Lacaio (3)","type":"Passiva","description":"o ladrão é derrotado quando sofre qualquer dano. Para cada 3 pontos de dano causados por um personagem ao ladrão, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os ladrões do punhal escarpado Próximos dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 2 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p9_322.png'),
(41, 'Punhal Escarpado, Seteiro', 1, 'Atirador', '', 'Um bandido esguio que ataca de longe com um arco curto.', 'emboscar, esconder-se, lucrar, reposicionar-se', 13, '4/7', 3, 2, '-1', 'Arco curto: distante', '1d10+2 fís', 'Furtividade +2', '[{"name":"Tiro furtivo","type":"Passiva","description":"se o seteiro estiver Escondido quando acertar um ataque padrão, ele causa 1d10+4 pontos de dano físico, em vez do dano padrão."}]', 'img/enemies/enemy_p9_322.png'),
(42, 'Punhal Escarpado, Sombra', 1, 'Oportunista', '', 'Um canalha ágil portando uma faca perigosa e usando sombras mágicas para isolar seus alvos.', 'dividir, emboscar, esconder, lucrar', 12, '4/8', 3, 3, '+1', 'Adagas: corpo a corpo', '1d4+4 fís', 'Intruso  +3', '[{"name":"Golpe Traiçoeiro","type":"Passiva","description":"quando a sombra for bem-sucedida em um ataque padrão feito com vantagem, ela causa 1d6+6 pontos de dano físico em vez do dano padrão."},{"name":"Ocultar","type":"Ação","description":"a sombra fica Escondida até o próximo ataque que fizer. Testes de ataque enquanto estiver Escondida por esta ação são feitos com vantagem."}]', 'img/enemies/enemy_p9_324.png'),
(43, 'Rato Gigante', 1, 'Lacaio', '', 'Um roedor do tamanho de um gato, habituado a sobreviver.', 'cavar, coletar, desgastar, fome', 10, 'Nenhum', 1, 1, '-4', 'Garras: corpo a corpo', '1 fís', 'Sentidos Aguçados +3', '[{"name":"Lacaio (3)","type":"Passiva","description":"o rato é derrotado quando sofre qualquer dano. Para cada 3 pontos de dano causados por um personagem ao rato, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os ratos gigantes Próximos dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 1 ponto de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p10_346.png'),
(44, 'Roedor Corrosivo', 1, 'Solo', '', 'Um inseto do tamanho de um cavalo com garras fortes e sangue ácido.', 'arrastar, alimentar, escavar, reposicionar', 14, '8/15', 8, 3, '+3', 'Garras: muito próximo', '1d12+2 fís', 'Sentido Sísmico +2', '[{"name":"Inclemente (3)","type":"Passiva","description":"o roedor pode ser posto em foco até 3 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Cuspe Ácido","type":"Ação","description":"faça um ataque contra todos os alvos próximos na frente do roedor. Alvos atingidos sofrem 2d6 pontos de dano físico e devem marcar 1 Ponto de Armadura sem receber seus benefícios (mas ainda podem usar PA para reduzir o dano). Se não for possível marcar 1 PA, o alvo deve marcar 1 Ponto de Vida adicional e você recebe 1 Ponto de Medo."},{"name":"Erupção de Terra","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer o roedor saltar para fora da terra. Todas as criaturas muito próximas devem passar em um teste de reação de Agilidade ou serão derrubadas, ficando Vulneráveis até que ajam novamente."},{"name":"Sangue ácido","type":"Reação","description":"quando o roedor sofre dano grave, todas as criaturas próximas são banhadas em seu sangue ácido, sofrendo 1d10 pontos de dano físico. A chuva de sangue cobre o chão em alcance muito próximo, e todas as criaturas além do roedor que se movam pela área sofrem 1d6 pontos de dano físico."}]', 'img/enemies/enemy_p10_346.png'),
(45, 'Saqueador', 1, 'Comum', '', 'Um lutador ágil armado com dardos.', 'flanquear, lucrar, pilhar, saquear', 12, '5/9', 3, 3, '+1', 'Dardo: Próximo', '1d6+2 fís', 'Camuflagem +2', '[{"name":"Distanciar","type":"Passiva","description":"após fazer um ataque padrão, o saqueador pode se mover para qualquer ponto em alcance distante."},{"name":"Recuar","type":"Reação","description":"quando uma criatura fica corpo a corpo para fazer um ataque no saqueador, você pode marcar 1 Ponto de Fadiga antes do teste de ataque para se mover para um ponto em alcance Próximo e fazer um ataque contra a criatura. Se acertar, o alvo sofre 1d10+2 pontos de dano físico."}]', 'img/enemies/enemy_p8_292.png'),
(46, 'Soldado Silvestre', 1, 'Comum', '', 'Um guerreiro feérico com armadura de folhas e casca de árvore.', 'carregar, emboscar, esconder, proteger, trilhar', 11, '6/11', 4, 2, '+0', 'Foice: corpo a corpo', '1d8+1 fís', 'Rastreador +2', '[{"name":"Táticas de Bando","type":"Passiva","description":"se o soldado acertar um ataque padrão e houver outro soldado silvestre corpo a corpo do alvo, ele causa 1d8+5 pontos de dano físico, em vez do dano padrão."},{"name":"Controle Florestal","type":"Ação","description":"gaste 1 Ponto de Medo para derrubar uma árvore próxima. Uma criatura atingida pela árvore deve passar em um teste de reação de Agilidade (15) ou sofre 1d10 pontos de dano físico."},{"name":"Camuflar-se","type":"Reação","description":"quando o soldado acertar um ataque, você pode marcar 1 Ponto de Fadiga para ficar Escondido até o Próximo ataque do soldado, ou até que um personagem passe em um teste de Instinto (14) para encontrá-lo."}]', 'img/enemies/enemy_p14_450.png'),
(47, 'Urso', 1, 'Brutamonte', '', 'Um grande urso de pelo espesso e garras poderosas.', 'defender território, escalar, rastrear, socar', 14, '9/17', 7, 2, '+1', 'Garras: corpo a corpo', '1d8+3 fís', 'Emboscada +3, Sentidos Aguçados +2', '[{"name":"Força Avassaladora","type":"Passiva","description":"alvos que marquem PV por um ataque padrão do urso são empurradas para um ponto em alcance muito próximo."},{"name":"Mordida","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra um alvo corpo a corpo. Em caso de sucesso, o alvo sofre 3d4+10 pontos de dano físico e fica Imobilizado até que se liberte com sucesso em um teste de Força."},{"name":"Impulso","type":"Reação","description":"quando o urso acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p18_544.png'),
(48, 'Zumbi Corpulento', 1, 'Brutamonte', '', 'Um cadáver grande, inchado e zangado.', 'atirar escombros, bater, destruir, esmagar', 10, '8/15', 7, 4, '+2', 'Pancada: muito próximo', '1d12+3 fís', 'Arremesso +4, Dano Colateral +2', '[{"name":"Lentidão","type":"Passiva","description":"se o zumbi for posto em foco, mas não tiver nenhum marcador em sua ficha, ele é incapaz de agir. Coloque um marcador na ficha e descreva o que ele está se preparando para fazer. Quando puser o zumbi em foco e ele tiver um marcador na ficha, remova o marcador para que ele possa agir."},{"name":"Lanhar","type":"Ação","description":"faça um ataque padrão com vantagem contra um alvo que o zumbi tiver Imobilizado. Em caso de sucesso, o ataque provoca dano direto."},{"name":"Dilacerar","type":"Reação","description":"quando o Zumbi acertar um ataque padrão, você pode marcar 1 Ponto de Fadiga para Imobilizar o alvo temporariamente e forçá-lo a marcar 2 Pontos de Fadiga."}]', 'img/enemies/enemy_p11_374.png'),
(49, 'Zumbi Emendado', 1, 'Solo', '', 'Cadáveres se movendo como uma coisa só, com membros grandes, torsos e punhos do tamanho de pequeninos adultos.', 'absorver corpos, assustar, fome, sacudir', 13, '8/15', 10, 3, '+4', 'Braços demais: muito próximo', '1d20 fís', 'Intimidação +2, Rasgar Coisas +2', '[{"name":"Destrutível","type":"Passiva","description":"quando o zumbi sofre dano maior ou superior, ele marca 1 Ponto de Vida adicional."},{"name":"Membros Demais","type":"Passiva","description":"quando o zumbi fizer um ataque padrão, ele pode atacar todos os alvos muito próximos."},{"name":"Berro Atormentado","type":"Ação","description":"marque 1 PF para obrigar todos os personagens distantes a fazer um teste de reação de Presença (13). A cada falha, quem falhou perde 1 Ponto de Esperança e você recebe 1 Ponto de Medo. Quem passar deve marcar 1 PF."},{"name":"Outro para a Pilha","type":"Ação","description":"quando o zumbi estiver muito próximo de um cadáver, ele pode incorporá-lo em si mesmo, recuperando 1 PV e 1 PF."}]', 'img/enemies/enemy_p11_376.png'),
(50, 'Zumbi Faminto', 1, 'Comum', '', 'Um cadáver animado que estremece ao se mover, movido pela fome.', 'agrupar, devorar, dilacerar carne, fome', 10, '4/6', 4, 1, '+0', 'Mordida: corpo a corpo', '1d6+1 fís', '', '[{"name":"Eles são muitos","type":"Passiva","description":"quando o zumbi estiver corpo a corpo a uma criatura e houver ao menos mais um zumbi Próximo, todos os ataques contra a criatura são feitos com vantagem."},{"name":"Horripilante","type":"Passiva","description":"alvos que marquem Pontos de Vida por ataques do zumbi também devem marcar 1 Ponto de Fadiga."}]', 'img/enemies/enemy_p11_378.png'),
(51, 'Zumbi Putrefato', 1, 'Lacaio', '', 'Um cadáver putrefato indo na direção de sua presa.', 'cercar, devorar carne, espancar, fome', 8, 'Nenhum', 1, 1, '-3', 'Mordida: corpo a corpo', '2 fís', '', '[{"name":"Lacaio (3)","type":"Passiva","description":"o zumbi putrefato é derrotado quando sofre qualquer dano. Para cada 3 pontos de dano causados por um personagem ao zumbi, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os zumbis putrefatos Próximos dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 2 ponto de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p11_378.png'),
(52, 'Horda de Zumbis', 1, 'Horda', '2/PV', 'Um grupo de cadáveres cambaleantes se movendo juntos por instinto.', 'consumir carne, fome, machucar', 8, '6/12', 6, 3, '-1', 'Mordida: corpo a corpo', '1d10+2 fís', '', '[{"name":"Horda (1d4+2)","type":"Passiva","description":"quando os zumbis tiverem marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 1d4+2 pontos de dano físico, em vez do valor original."},{"name":"Exceder","type":"Reação","description":"quando os zumbis marcarem Pontos de Vida por causa de um ataque cac, você pode marcar 1 Ponto de Fadiga para fazer um ataque padrão contra o atacante."}]', 'img/enemies/enemy_p11_376.png'),
(53, 'Águia Gigante', 2, 'Oportunista', '', 'Uma imensa ave de rapina com garras manchadas de sangue.', 'atacar com precisão, caçar, manter-se em movimento', 14, '8/19', 4, 4, '+1', 'Garras e bico: muito próximo', '2d6+3 fís', '', '[{"name":"Voo","type":"Passiva","description":"enquanto estiver em voo, a águia sofre um bônus de +3 em sua Dificuldade."},{"name":"Decolar","type":"Ação","description":"faça um ataque contra um alvo muito próximo. Em caso de sucesso, o alvo sofre 2d4+3 pontos de dano físico e deve passar em um teste de reação de Agilidade, ou fica Imobilizado pelas imensas garras da águia. Se o alvo ficar Imobilizado, a águia decola imediatamente para um ponto em alcance muito distante acima do campo de batalha enquanto o segura."},{"name":"Rasante Mortal","type":"Ação","description":"marque 1 PF para atacar um alvo distante. Em caso de sucesso, cause 2d10+2 pontos de dano físico e derrube o alvo, tornando-o Vulnerável até que ele aja novamente."},{"name":"Soltar à Morte","type":"Ação","description":"enquanto estiver em voo, a águia pode soltar um alvo Imobilizado que esteja segurando. Se isso acontecer, o alvo não fica mais Imobilizado, mas começa a cair. Se a queda não for prevenida nas próximas ações do grupo, o alvo sofre 2d20 pontos de dano físico ao bater no chão."}]', 'img/enemies/enemy_p16_492.png'),
(54, 'Aparição de Pedra', 2, 'Oportunista', '', 'Um caçador que se esgueira como um leão-da-montanha, com corpo de pedra acinzentada.', 'defender território, isolar presa, perseguir', 13, '11/22', 6, 3, '+3', 'Mordida e garras: corpo a corpo', '2d8+6 fís', 'Sentido de pedra +3', '[{"name":"Passo de Pedra","type":"Passiva","description":"a aparição pode se mover através de rocha e terra tão bem quanto no ar. Enquanto estiver dentro de rochas e terra, ela fica Escondida e é imune a qualquer dano."},{"name":"Cilada Pedregosa","type":"Ação","description":"enquanto estiver Escondida, marque 1 Ponto de Fadiga para saltar para um ponto em alcance corpo a corpo de um alvo muito próximo. O alvo deve passar em um teste de reação de Agilidade ou Instinto (15), ou sofre 2d8 pontos de dano físico e fica temporariamente Imobilizado."},{"name":"Rugido de Avalanche","type":"Ação","description":"gaste 1 Ponto de Medo para rugir enquanto estiver dentro de uma caverna para causar um deslizamento. Todos os alvos próximos devem passar em um teste de reação de Agilidade (14), ou sofrem 2d10 pontos de dano físico. Escombros podem ser removidos com uma Contagem (8)."},{"name":"Impulso","type":"Reação","description":"quando a aparição acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p12_400.png'),
(55, 'Assassino Aprendiz', 2, 'Lacaio', '', 'Um jovem aprendiz ávido para mostrar do que é capaz.', 'exibir, imprudência, matar, provar seu valor', 13, 'nenhum', 1, 1, '-1', 'Adaga de arremesso: muito próximo', '4 fís', 'Intruso +2', '[{"name":"Lacaio (6)","type":"Passiva","description":"o assassino é derrotado quando sofre qualquer dano. Para cada 6 pontos de dano causados por um personagem ao assassino, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os aprendizes de assassino próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 4 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p13_430.png'),
(56, 'Assassino Envenenador', 2, 'Oportunista', '', 'Um criminoso ardiloso, habilidoso com venenos e emboscadas.', 'antecipar, envenenar comida e água, matar, ser pago', 14, '8/16', 4, 4, '+3', 'Adaga de arremesso envenenada: próximo', '2d8+1 fís', 'Intruso +2', '[{"name":"Do Nada","type":"Passiva","description":"o assassino envenenador tem vantagem em testes de ataque realizados enquanto estiver Escondido."},{"name":"Veneno de Presâmia","type":"Passiva","description":"alvos que marquem Pontos de Vida por um ataque do assassino envenenador se tornam Vulneráveis até que recuperem 1 Ponto de Vida."},{"name":"Fumaça Vertiginosa","type":"Ação","description":"jogue uma bomba de fumaça que preenche o ar em alcance próximo, deixando todos os alvos na área Tontos. Alvos Tontos sofrem desvantagem em seus próximos testes, então se recuperam da condição."}]', 'img/enemies/enemy_p13_428.png'),
(57, 'Assassino Mestre', 2, 'Líder', '', 'Um assassino veterano de voz ameaçadora portando uma lâmina fatal.', 'emboscar, matar, preparar-se para qualquer situação, sobreviver', 15, '12/25', 7, 5, '+5', 'Adaga de serra: próximo', '2d10+2 fís', 'Comandar +2, Intruso +3', '[{"name":"Tarde Demais","type":"Passiva","description":"o assassino mestre causa dano direto enquanto estiver Escondido."},{"name":"Ataque Coordenado","type":"Ação","description":"marque 1 Ponto de Fadiga para pôr em foco um número de assassinos equivalente ao número de Pontos de Fadiga não marcados do assassino mestre."},{"name":"Impulso","type":"Reação","description":"quando o assassino mestre acertar um ataque contra um personagem, receba 1 Ponto de Medo."},{"name":"Lâmina sutil","type":"Reação","description":"quando o assassino mestre acerta um ataque contra um alvo Vulnerável, você pode gastar 1 Ponto de Medo para causar dano grave, em vez do dano padrão."}]', 'img/enemies/enemy_p12_402.png'),
(58, 'Barão Mercante', 2, 'Manipulador', '', 'Um mercador bem-sucedido no comando de uma grande operação.', 'abusar do poder, mobilizar lacaios, obter recursos', 15, '9/19', 5, 3, '-2', 'Rapieira: corpo a corpo', '1d6+2 fís', 'Nobreza +2, Comércio +2', '[{"name":"Os Melhores que o Dinheiro Pode Comprar","type":"Ação","description":"uma vez por cena, marque 1 Ponto de Fadiga para invocar 1d4+1 adversários de 1º patamar, que surgem Distantes para fazer valer a vontade do barão."},{"name":"Todos Têm um Preço","type":"Ação","description":"gaste 1 Ponto de Medo para oferecer a um alvo uma barganha perigosa em troca de algo que o alvo deseje ou precise. Um personagem que receba a oferta deve fazer um teste de reação de Presença (17). Se falhar, deve marcar 2 Pontos de Fadiga ou aceitar a oferta."}]', 'img/enemies/enemy_p17_518.png'),
(59, 'Caixa de Batalha', 2, 'Solo', '', 'Um construto em forma de cubo, com runas diferentes em cada face.', 'aguardar disfarçado, atropelar inimigos, mudar tática', 15, '10/20', 8, 6, '+2', 'Pancada: corpo a corpo', '2d6+3 fís', 'Camuflagem +2', '[{"name":"Inclemente (2)","type":"Passiva","description":"a caixa pode ser posta em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-la em foco."},{"name":"Táticas Aleatórias","type":"Ação","description":"marque 1 Ponto de Fadiga e role 1d6. A caixa de batalha usa uma das seguintes táticas: 1. Feixe de Mana. A caixa atira um feixe de calor. Faça um ataque contra um alvo distante. Em caso de sucesso, o alvo sofre 2d10+2 pontos de dano mágico. 2. Jatos de Fogo. A caixa se atira para o alto, girando e soltando jatos de fogo. Faça um ataque contra todos os alvos próximos. Alvos atingidos sofrem 2d8 pontos de dano físico. 3. Atropelar. A caixa se move de maneira imprevisível. Faça um ataque contra todos os personagens próximos. Alvos atingidos sofrem 1d6+5 pontos de dano físico e ficam Vulneráveis até que rolem com Esperança. 4. Gás Eletrizado. A caixa dispara um gás prateado que solta raios brilhantes. Todos os alvos próximos devem passar em um teste de reação de Acuidade, ou devem marcar 3 PF. 5. Impacto Atordoante. A caixa salta e provoca um impacto em suas faces, criando um estrondo sônico. Todos os alvos muito próximos devem passar em um teste de reação de Forca, ou ficam Vulneráveis até que a caixa seja derrotada. 6. Ganido Psiônico. A caixa libera um enxame de abelhas mecânicas, cujo zumbido afeta as mentes dos mortais. Todos os alvos próximos devem passar em um teste de reação de Presença ou sofrem 2d4+9 pontos de dano mágico direto."},{"name":"Sobrecarga","type":"Reação","description":"antes rolar o dano dos ataques da caixa, você pode marcar 1 Ponto de Fadiga para somar 1d6 ao teste de ataque. Além disso, receba 1 Ponto de Medo."},{"name":"Terremoto da Morte","type":"Reação","description":"quando a caixa marcar seu último Ponto de Vida, a magia que a sustenta rompe em uma explosão de força. Todos os alvos próximos devem passar em um teste de reação de Instinto ou sofrem 2d8+1 pontos de dano mágico."}]', 'img/enemies/enemy_p13_426.png'),
(60, 'Cavaleiro do Reino', 2, 'Líder', '', 'Um soldado condecorado de armadura pesada, montado num cavalo.', 'atropelar, buscar glória, mostrar dominância', 15, '13/26', 6, 4, '+4', 'Espada longa: corpo a corpo', '2d10+4 fís', 'Conhecimento Ancestral +3, Alta Sociedade +2, Táticas +2', '[{"name":"Armadura Reforçada","type":"Passiva","description":"quando o cavaleiro sofre dano físico, esse dano é reduzido em 3 pontos."},{"name":"Cavaleiro","type":"Passiva","description":"quando o cavaleiro estiver cavalgando uma montaria, ele recebe um bônus de +2 em sua Dificuldade. Se sofrer dano grave, ele é derrubado de sua montaria e perde o benefício até que seja posto em foco novamente."},{"name":"Ataque Montado","type":"Ação","description":"se o cavaleiro estiver cavalgando uma montaria, ele se move até alcance distante para fazer um ataque contra um alvo corpo a corpo. Em caso de sucesso, o alvo sofre 2d8+4 pontos de dano físico e deve marcar 1 Ponto de Fadiga."},{"name":"Pelo Reino!","type":"Ação","description":"marque 1 Ponto de Fadiga para colocar em foco 1d4+1 aliados. Ataques realizados por aliados postos em foco desta forma causam metade do dano."}]', 'img/enemies/enemy_p14_450.png'),
(61, 'Conscrito', 2, 'Lacaio', '', 'Um civil mal treinado enviado para a guerra.', 'atacar em grupo, seguir ordens, sobreviver', 12, 'nenhum', 1, 1, '+0', 'Lança: muito próximo', '6 fís', '', '[{"name":"Lacaio (6)","type":"Passiva","description":"o conscrito é derrotado quando sofre qualquer dano. Para cada 6 pontos de dano causados por um personagem ao conscrito, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os conscritos próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 6 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p14_450.png'),
(62, 'Conselheiro Real', 2, 'Manipulador', '', 'Um bajulador de alta patente com influência sobre a nobreza local.', 'bajular, produzir evidências, tramar', 14, '8/15', 3, 3, '-3', 'Varinha: distante', '1d4+3 fís', 'Administração +3, Bajulador +3', '[{"name":"Objeção Devastadora","type":"Passiva","description":"um personagem que role menos de 17 em um teste contra o conselheiro deve marcar 1 PF."},{"name":"Bode Expiatório","type":"Ação","description":"gaste 1 Ponto de Medo para convencer uma multidão ou um indivíduo notável que uma pessoa ou grupo é responsável pelos problemas do alvo. Este se torna hostil à pessoa ou grupo até que seja convencido de sua inocência com sucesso em um teste de Presença (17)."},{"name":"Sussurros Manipuladores","type":"Ação","description":"marque 1 Ponto de Fadiga para influenciar um NPC corpo a corpo com palavras sussurradas. A opinião do alvo sobre um assunto muda de acordo com a preferência do conselheiro, exceto quando em oposição direta às motivações do alvo."}]', 'img/enemies/enemy_p17_518.png'),
(63, 'Cortesão', 2, 'Manipulador', '', 'Um manipulador competente, mestre das interações sociais.', 'conseguir patronos, manobrar, seduzir', 13, '7/13', 3, 4, '-3', 'Adaga: corpo a corpo', '1d4+3 fís', 'Manipulação +3, Socialite +3', '[{"name":"Olhar Abrasador","type":"Reação","description":"quando um personagem próximo fizer um teste de Presença, você pode marcar 1 Ponto de Fadiga para lançar um olhar agourento. Se o alvo falhar na jogada, deve marcar 2 Pontos de Fadiga e fica Vulnerável até o fim da cena ou até passar em um teste social contra o cortesão; quando fizer isso, ele deve marcar 1 Ponto de Fadiga."}]', 'img/enemies/enemy_p17_518.png'),
(64, 'Crânio do Caos', 2, 'Atirador', '', 'Um crânio flutuante humanoide, animado por magia cintilante.', 'consumir magia, gargalhar, servir seu criador', 15, '8/16', 5, 4, '+2', 'Raio de energia: próximo', '2d8+3 mág', '', '[{"name":"Levitação","type":"Passiva","description":"o crânio levita a vários centímetros do chão e não pode ser Imobilizado."},{"name":"Proteção","type":"Passiva","description":"o crânio é resistente a dano mágico."},{"name":"Explosão Mágica","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra todos os alvos próximos. Alvos atingidos sofrem 2d6+4 pontos de dano mágico."},{"name":"Sorver Magia","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque contra um personagem muito próximo que tenha um atributo de conjuração. Em caso de sucesso, o alvo deve marcar 1d4 PF, e o crânio recupera esse mesmo valor de Pontos de Fadiga. Além disso, se acertar o ataque, o crânio pode imediatamente ser posto em foco de novo."}]', 'img/enemies/enemy_p15_472.png'),
(65, 'Cultista Adepto', 2, 'Assistente', '', 'Um mago experiente que lida com sombras e medo.', 'atrapalhar inimigos, bajular, fazer descobertas', 14, '9/18', 4, 6, '+2', 'Cajado de runas: distante', '2d4+3 mág', 'Conhecimento Perdido +2, Rituais +2', '[{"name":"Ataque Inquietante","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque padrão contra um alvo dentro do alcance. Em caso de sucesso, o alvo deve marcar 1 Ponto de Fadiga."},{"name":"Grilhões de Sombra","type":"Ação","description":"gaste 1 Ponto de Medo e escolha um ponto em alcance distante. Todos os alvos próximos desse ponto ficam Imobilizados por correntes de névoa até que se libertem com sucesso em um teste de Força ou Instinto. Um alvo Imobilizado por essa habilidade deve gastar 1 Ponto de Esperança para fazer esse teste."},{"name":"Manto dos Caídos","type":"Ação","description":"marque 1 Ponto de Fadiga para envolver um aliado próximo em um manto de Proteção até que o cultista adepto marque seu último Ponto de Vida. Enquanto estiver Protegido, o alvo possui resistência a todo tipo de dano."},{"name":"Seu Medo É Meu Refúgio","type":"Reação","description":"duas vezes por cena, quando um personagem rolar uma falha com Medo, recupere 1 PF."}]', 'img/enemies/enemy_p15_472.png'),
(66, 'Cultista Iniciado', 2, 'Lacaio', '', 'Um cultista de baixo escalão em robes simples, ávido a obter poder.', 'buscar conhecimento proibido, obter poder, seguir ordens', 13, 'nenhum', 1, 1, '+0', 'Adaga ritualística: corpo a corpo', '5 fís', '', '[{"name":"Lacaio (6)","type":"Passiva","description":"o cultista é derrotado quando sofre qualquer dano. Para cada 6 pontos de dano causados por um personagem ao cultista, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os cultistas iniciados próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 5 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p15_472.png'),
(67, 'Cultista Sicário', 2, 'Oportunista', '', 'Um assassino profissional que se tornou cultista.', 'capturar sacrifícios, isolar presas, subir cargos', 15, '9/17', 4, 4, '+2', 'Faca longa: corpo a corpo', '2d8+4 fís', '', '[{"name":"Abraço da Sombra","type":"Passiva","description":"o sicário é capaz de escalar e caminhar por superfícies verticais. Marque 1 Ponto de Fadiga para se mover de uma sombra à outra em alcance distante."},{"name":"Não Fique Para Trás","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer com que um alvo corpo a corpo faça um teste de reação de Instinto. Se falhar, o alvo deve marcar 2 Pontos de Fadiga, e é teleportado, junto ao sicário, para uma sombra distante, além de ficar temporariamente Vulnerável. Se passar, o alvo deve marcar 1 Ponto de Fadiga."}]', 'img/enemies/enemy_p15_472.png'),
(68, 'Enguias-Elétricas', 2, 'Horda', '2/PV', 'Um bando de enguias que cercam e eletrocutam suas vítimas.', 'eletrocutar presas, evitar grandes predadores, partir em pedaços', 14, '10/20', 5, 3, '+0', 'Mordida chocante: corpo a corpo', '2d6+4 fís', '', '[{"name":"Horda (2d4+1)","type":"Passiva","description":"quando as enguias tiverem marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 2d4+1 pontos de dano físico, em vez do valor original."},{"name":"Choque Paralisante","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque padrão contra todos os alvos muito próximos. Receba 1 Ponto de Medo a cada alvo que marcar Pontos de Vida."}]', 'img/enemies/enemy_p19_564.png'),
(69, 'Espectro Arqueiro', 2, 'Atirador', '', 'Um lutador fantasma com um arco etéreo, incapaz de seguir em frente.', 'atravessar objetos sólidos, ficar longe do conflito, recomeçar batalhas antigas', 13, '6/14', 3, 3, '+3', 'Arco longo: distante', '2d10+2 fís', 'Conhecimento Antigo +2', '[{"name":"Fantasma","type":"Passiva","description":"o espectro é resistente a dano físico. Marque 1 Ponto de Fadiga para movê-lo para um ponto em alcance próximo atravessando objetos sólidos."},{"name":"Escolher Alvo","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque contra um personagem distante que esteja muito próximo de pelo menos dois outros personagens. Em caso de sucesso, o alvo sofre 2d8+12 pontos de dano físico."}]', 'img/enemies/enemy_p5_200.png'),
(70, 'Espectro Capitão', 2, 'Líder', '', 'Um comandante fantasmagórico que lidera tropas do além-túmulo.', 'atravessar objetos sólidos, comandar tropas, recomeçar batalhas antigas', 16, '13/26', 4, 3, '+3', 'Arco longo: distante', '2d10+3 fís', 'Conhecimento Antigo +3', '[{"name":"Fantasma","type":"Passiva","description":"o espectro é resistente a dano físico. Marque 1 Ponto de Fadiga para movê-lo para um ponto em alcance próximo atravessando objetos sólidos."},{"name":"Batalha Sem Fim","type":"Ação","description":"gaste 2 Pontos de Medo para trazer de volta até 1d4+1 aliados espectrais derrotados para a batalha nos locais em que surgiram originalmente (sem PV ou PF marcados)."},{"name":"Impulso","type":"Reação","description":"quando o capitão acertar um ataque contra um personagem, receba 1 Ponto de Medo."},{"name":"Manter posições","type":"Reação","description":"se aliados espectrais do capitão forem forçados a fazer um teste de reação, você pode marcar 1 Ponto de Fadiga para dar a esses aliados um bônus de +2 no teste."}]', 'img/enemies/enemy_p5_198.png'),
(71, 'Espectro Guardião', 2, 'Comum', '', 'Um lutador fantasmagórico com lanças e espadas, preso em seu dever.', 'atravessar objetos sólidos, proteger tesouro, recomeçar batalhas antigas', 15, '7/15', 4, 3, '+1', 'Lança: muito próximo', '2d8+1 fís', 'Conhecimento antigo +2', '[{"name":"Fantasma","type":"Passiva","description":"o espectro é resistente a dano físico. Marque 1 Ponto de Fadiga para movê-lo para um ponto em alcance próximo atravessando objetos sólidos."},{"name":"Lâmina Túmular","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque contra um alvo muito próximo. Em caso de sucesso, o alvo sofre 2d10+6 pontos de dano físico e deve marcar 1 PF."}]', 'img/enemies/enemy_p5_204.png'),
(72, 'Espião', 2, 'Manipulador', '', 'Um agente secreto habilidoso com o hábito de estar no local certo para escutar segredos.', 'bisbilhotar, cortar e correr, disfarçar aparência', 15, '8/17', 4, 3, '-2', 'Adaga: corpo a corpo', '2d6+3 fís', 'Espionagem +3', '[{"name":"Descobrir Segredos","type":"Ação","description":"gaste 1 Ponto de Medo para descrever como o espião sabe de um segredo sobre um personagem na cena."},{"name":"Escondido à Vista","type":"Reação","description":"quando um personagem ou grupo estiver discutindo um assunto sensível, você pode marcar 1 Ponto de Fadiga para revelar que o espião está presente na cena, observando-os. Se o espião escapar para reportar o que descobriu, receba 1d4 Pontos de Medo."}]', 'img/enemies/enemy_p13_430.png'),
(73, 'Esquadrão de Arqueiros', 2, 'Horda', '2/PV', 'Um grupo de arqueiros portando arcos massivos.', 'atirar fogo, manter-se juntos, sobreviver', 13, '8/16', 4, 3, '+0', 'Arco longo: distante', '2d6+3 fís', '', '[{"name":"Horda (1d6+3)","type":"Passiva","description":"quando o esquadrão tiver marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 1d6+3 pontos de dano físico, em vez do valor original."},{"name":"Saraivada Concentrada","type":"Ação","description":"marque 1 Ponto de Fadiga para escolher um ponto em alcance distante. Até a próxima rolagem com Medo, qualquer criatura que se mova em alcance próximo do ponto escolhido deve fazer um teste de reação de Agilidade. Se falhar, a criatura sofre 2d6+3 pontos de dano físico. Se passar, sofre metade do dano."},{"name":"Saraivada Focada","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um ponto em alcance distante. Faça um ataque com vantagem contra todos os alvos próximos do ponto escolhido. Alvos atingidos sofrem 1d10+4 pontos de dano físico."}]', 'img/enemies/enemy_p14_450.png'),
(74, 'Experimento Fracassado', 2, 'Comum', '', 'Um experimento necromântico fracassado, resultando em algo distorcido e desajeitado.', 'caçar, devorar, rastrear', 13, '12/23', 3, 3, '+1', 'Mordida e garras: corpo a corpo', '2d6+5 fís', 'Imitador +3', '[{"name":"Resistência Distorcida","type":"Passiva","description":"o experimento é resistente a dano físico."},{"name":"Investida Cambaleante","type":"Ação","description":"marque 1 Ponto de Fadiga para pôr o experimento em foco como um movimento adicional do mestre em vez de gastar Medo."},{"name":"Exceder","type":"Reação","description":"quando o experimento ataca um alvo muito próximo de outros adversários, o ataque do experimento causa dano dobrado."}]', 'img/enemies/enemy_p15_472.png'),
(75, 'Gigante Lutador', 2, 'Brutamonte', '', 'Um gigante forte com um martelo de guerra maior que um humano.', 'bater, derrubar, ganhar a vida, sobrecarregar', 15, '14/28', 7, 4, '+2', 'Martelo de guerra: muito próximo', '2d12+3 fís', 'Intruso +2', '[{"name":"Aríete","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer o gigante avançar até um objeto inanimado próximo que possa ser esmagado por ele (como uma parede, carrinho ou estande de mercado) e o destrua. Todos os alvos muito próximos do objeto devem passar em um teste de reação de Agilidade, ou sofrem 2d4+3 pontos de dano físico dos estilhaços."},{"name":"Contra-ataque Sanguinário","type":"Reação","description":"quando o gigante marcar 2 Pontos de Vida ou mais por um ataque muito próximo, ele pode fazer um ataque padrão contra o atacante. Em caso de sucesso, ele causa 2d6+15 pontos de dano físico, em vez do dano original."},{"name":"Impulso","type":"Reação","description":"quando o lutador acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p16_492.png'),
(76, 'Gigante Mestre das Feras', 2, 'Líder', '', 'Um guerreiro de armadura de couro, com um chicote e um arco imenso.', 'comandar, ganhar a vida, imobilizar, manobrar, proteger companheiros animais', 16, '12/24', 6, 5, '+2', 'Arco longo: distante', '2d8+4 fís', 'Adestração +3', '[{"name":"Dois por Um","type":"Passiva","description":"quando o mestre das feras estiver em foco, você também pode pôr em foco um adversário animal de 1º patamar que esteja sob o controle dele."},{"name":"Companhia Mortal","type":"Ação","description":"duas vezes por cena, invoque um urso, lobo-atroz ou outro adversário animal semelhante de 1º patamar sob o controle do mestre das feras. O adversário surge num ponto em alcance próximo e é posto em foco imediatamente."},{"name":"Pregar no Chão","type":"Ação","description":"faça um ataque padrão contra um alvo. Em caso de sucesso, você pode marcar 1 PF para prendê-lo a uma superfície próxima. O alvo preso fica Imobilizado até que se liberte com sucesso em um teste de Acuidade ou Força."}]', 'img/enemies/enemy_p16_492.png'),
(77, 'Gigante Recruta', 2, 'Lacaio', '', 'Um lutador gigante de armadura emprestada.', 'aterrorizar, bater, ganhar a vida, sobrecarregar', 13, 'nenhum', 1, 2, '+1', 'Martelo de guerra: muito próximo', '5 fís', '', '[{"name":"Lacaio (7)","type":"Passiva","description":"o recruta é derrotado quando sofre qualquer dano. Para cada 7 pontos de dano causados por um personagem ao recruta, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os gigantes recrutas próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 5 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p16_492.png'),
(78, 'Górgona', 2, 'Solo', '', 'Um humanoide escamoso com cobras na cabeça, armado com um arco dourado e enraivecido por ter sua paz perturbada.', 'acuar, bater e correr, petrificar, se vingar', 15, '13/25', 9, 3, '+4', 'Arco curto fúlgido: distante', '2d20+3 mág', 'Furtividade +3', '[{"name":"Flechas Fúlgidas","type":"Passiva","description":"quando a górgona acerta um ataque, o alvo fica Iluminado até o fim da cena e não pode se esconder. Testes de ataque feitos contra alvos Iluminados recebem vantagem."},{"name":"Inclemente (2)","type":"Passiva","description":"a górgona pode ser posta em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-la em foco."},{"name":"Coroa de Serpentes","type":"Ação","description":"faça um teste de ataque contra um alvo corpo a corpo usando as serpentes protetoras da górgona. Em caso de sucesso, marque 1 Ponto de Fadiga para causar 2d10+4 pontos de dano físico ao alvo e fazê-lo marcar 1 PF."},{"name":"Impulso","type":"Reação","description":"quando a górgona acertar um ataque contra um personagem, receba 1 Ponto de Medo."},{"name":"Olhar Petrificante","type":"Reação","description":"quando a górgona sofre dano de um adversário próximo, você pode gastar 1 Ponto de Medo para forçar o atacante a fazer um teste de reação de Instinto. Se falhar, ele começa a se transformar em pedra, marcando 1 Ponto de Vida e iniciando uma Contagem de Petrificação (4), que diminui toda vez que a górgona for atacada. Quando a contagem termina, o alvo deve fazer um movimento de morte. Se a górgona for derrotada, a Contagem de Petrificação é interrompida."}]', 'img/enemies/enemy_p17_520.png'),
(79, 'Mago de Batalha', 2, 'Atirador', '', 'Um mago veterano treinado em mágica destrutiva.', 'buscar poder, desenvolver novos feitiços, estraçalhar formações', 16, '11/23', 5, 6, '+4', 'Cajado: distante', '2d10+4 mág', 'Conhecimento Mágico +2, Estratégia +2', '[{"name":"Teleporte de Batalha","type":"Passiva","description":"antes ou depois de ter feito um ataque padrão, você pode marcar 1 PF para se teleportar para um ponto em alcance distante."},{"name":"Artilharia Arcana","type":"Ação","description":"gaste 1 Ponto de Medo para lançar uma saraivada de raios mágicos. Todos os alvos na cena precisam realizar um teste de reação de Agilidade. Alvos que falharem sofrem 2d12 pontos de dano mágico. Alvos que passarem sofrem metade do dano."},{"name":"Erupção","type":"Ação","description":"gaste 1 Ponto de Medo e escolha um ponto em alcance distante. A área muito próxima do ponto explode em terreno intransponível. Todos os alvos dentro da área devem fazer um teste de reação de Agilidade (14). Alvos que falharem sofrem 2d10 pontos de dano físico e são jogados para fora da área. Alvos que passarem sofrem metade do dano e não são movidos."},{"name":"Recuperar Esfera de Proteção","type":"Ação","description":"marque 1 PF para recuperar a Esfera de Proteção do mago."},{"name":"Esfera de Proteção","type":"Reação","description":"quando o mago sofre dano de um ataque próximo, cause 2d6 pontos de dano mágico ao atacante. Esta reação não pode ser utilizada novamente até que o mago a recupere com Recuperar Esfera de Proteção, abaixo."}]', 'img/enemies/enemy_p17_518.png'),
(80, 'Matilha Demoníaca', 2, 'Horda', '1/PV', 'Cães demoníacos que bruxuleiam com brasas infernais.', 'agradar seus mestres, causar medo, consumir carne', 15, '11/23', 6, 3, '+0', 'Garras e presas: corpo a corpo', '2d8+2 fís', 'Rastrear Cheiros +3', '[{"name":"Horda (2d4+1)","type":"Passiva","description":"quando a matilha tiver marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 2d4+1 pontos de dano físico, em vez do valor original."},{"name":"Uivo Apavorante","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer com que todos os alvos muito próximos percam 1 Ponto de Esperança. Se o alvo não puder perder 1 Ponto de Esperança, ele deve marcar 2 Pontos de Fadiga em vez disso."},{"name":"Impulso","type":"Reação","description":"quando a matilha acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p18_544.png'),
(81, 'Minotauro Arrasador', 2, 'Brutamonte', '', 'Um imenso firbolg com cabeça de touro e pavio curto.', 'consumir, estraçalhar, navegar, perseguir, subjugar', 16, '14/27', 7, 5, '+2', 'Machado de batalha: muito próximo', '2d8+5 fís', 'Navegação +2', '[{"name":"Vocês Vão Se Ver Comigo","type":"Passiva","description":"é preciso gastar 1 Ponto de Medo para pôr o minotauro em foco. Quando estiver em foco, ele pode fazer um ataque padrão contra todos os alvos no alcance."},{"name":"Estouro","type":"Ação","description":"marque 1 Ponto de Fadiga para avançar através de um grupo próximo e atacar todos os alvos no caminho do minotauro. Alvos atingidos pelo ataque sofrem 2d6+8 pontos de dano físico e são empurrados para um ponto em alcance muito distante. Um alvo empurrado contra um objeto sólido ou outra criatura sofre +1d6 pontos de dano (some todos os danos)."},{"name":"Sanguinolência","type":"Ação","description":"faça um ataque contra um alvo muito próximo, movendo o minotauro até ficar em alcance corpo a corpo ao alvo. Se acertar, ele causa 2d8 pontos de dano físico direto."}]', 'img/enemies/enemy_p18_542.png'),
(82, 'Oscilume Jovem', 2, 'Solo', '', 'Um inseto grande como um cavalo, com escamas iridescentes e asas cristalinas que se movem mais rápido do que o olhar.', 'arrebatar, caçar, colecionar coisas brilhantes', 14, '13/26', 10, 5, '+3', 'Asas afiadas: muito próximo', '2d10+4 fís', '', '[{"name":"Inclemente (3)","type":"Passiva","description":"o oscilume pode ser posto em foco até 3 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Acuidade Inigualável","type":"Passiva","description":"antes do oscilume fazer um ataque, role 1d6. Se rolar 4 ou mais, a Evasão do alvo é reduzida para a metade contra este ataque."},{"name":"Dança Mental","type":"Ação","description":"marque 1 Ponto de Fadiga para criar uma exibição mágica que ocupa a mente dos inimigos ao redor. Todos os alvos próximos devem fazer um teste de reação de Instinto. Para cada alvo que falhe, você recebe 1 Ponto de Medo e o oscilume descobre um dos medos do alvo."},{"name":"Sopro Alucinógeno","type":"Reação","description":"Contagem (ciclo 1d6). Quando o oscilume sofrer dano pela primeira vez, ative a contagem regressiva. Quando ela terminar, o oscilume sopra um gás alucinógeno em todos os alvos Distantes à sua frente. Alvos precisam passar em um teste de reação de Instinto ou têm visões terríveis. Alvos cujos medos o oscilume conheça sofrem desvantagem nesse teste. Alvos que falhem no teste devem marcar 1 Ponto de Fadiga e perder 1 Ponto de Esperança."}]', 'img/enemies/enemy_p19_564.png'),
(83, 'Patife Mascarado', 2, 'Oportunista', '', 'Um ladrão astuto com habilidades acrobáticas e predileção por drama.', 'esconder, evadir, furtar, lucrar', 14, '8/17', 4, 5, '+3', 'Sabre: corpo a corpo', '2d8+3 fís', 'Acrobacia +3', '[{"name":"Mãos Ágeis","type":"Ação","description":"faça um ataque contra um alvo corpo a corpo. Em caso de sucesso, o patife causa 1d8+2 pontos de dano físico e rouba um item ou consumível do inventário do alvo."},{"name":"Plano de Fuga","type":"Ação","description":"marque 1 Ponto de Fadiga para revelar uma armadilha armada pelo patife em algum lugar do campo de batalha. Todos os alvos muito próximos da armadilha devem passar em um teste de reação de Agilidade (13) ou serão puxados pelos pés e pendurados de cabeça para baixo, ficando Imobilizados e Vulneráveis. Libertar-se com sucesso em um teste de Acuidade ou Força (13) encerra as duas condições."}]', 'img/enemies/enemy_p13_430.png'),
(84, 'Portador dos Segredos', 2, 'Líder', '', 'Um líder clandestino ligado diretamente aos Deuses Caídos.', 'acumular poder, tomar o comando, tramar', 16, '13/26', 7, 4, '+3', 'Cajado místico: distante', '2d12 mág', 'Coerção +2, História dos Deuses Caídos +2', '[{"name":"Aproveitar o Momento","type":"Ação","description":"gaste 2 Pontos de Medo para pôr 1d4 aliados em foco. Ataques feitos por aliados postos em foco por esta ação causam metade do dano."},{"name":"Matilha Demoníaca","type":"Reação","description":"uma vez por cena, quando o portador dos segredos marcar 2 ou mais PV, você pode marcar 1 PF para invocar uma matilha demoníaca, que surge em um ponto alcance próximo e é imediatamente posta em foco."},{"name":"Ritual de Invocação","type":"Reação","description":"Contagem (6). Quando o portador dos segredos for posto em foco pela primeira vez, ative a contagem regressiva. Toda vez que o portador marcar Pontos de Vida, diminua a contagem em um valor igual aos PV. Quando a contagem terminar, invoque um demônio menor em um ponto em alcance próximo."},{"name":"Vontade do Mestre","type":"Reação","description":"quando você puser um aliado distante em foco, marque 1 Ponto de Fadiga para receber 1 Ponto de Medo."}]', 'img/enemies/enemy_p17_518.png'),
(85, 'Predador Mortal', 2, 'Líder', '', 'Uma figura morta-viva em um casaco de couro, com olhos atentos e comportamento cruel.', 'caçar, devorar, rastrear', 16, '15/27', 6, 4, '+5', 'Dilacerar: muito próximo', '2d12+1 fís', 'Cão de Caça +3', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o predador acerta um ataque, todos os personagens distantes perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Marcado para Morrer","type":"Ação","description":"gaste 1 Ponto de Medo para amaldiçoar um alvo muito próximo com uma marca até o fim da cena. Ataques do predador contra o alvo Marcado causam dano direto. O predador só é capaz de manter um alvo Marcado por vez."},{"name":"Morte Inevitável","type":"Ação","description":"marque 1 PF para pôr 1d4 aliados em foco. Ataques destes aliados causam metade do dano."},{"name":"Ataque Violento","type":"Reação","description":"Contagem (ciclo 1d6). Quando o predador estiver em foco pela primeira vez, ative a contagem regressiva. Quando ela terminar, ele se move em uma linha reta até um ponto em alcance distante e faz um ataque contra todos os alvos no caminho. Alvos atingidos sofrem 2d8+2 pontos de dano físico."}]', 'img/enemies/enemy_p18_544.png'),
(86, 'Sereia', 2, 'Oportunista', '', 'Uma pessoa meio-peixe, de escamas brilhantes e voz irresistível.', 'consumir, seduzir presas, vencer com música', 14, '9/18', 5, 3, '+2', 'Maxilar distendido: corpo a corpo', '2d6+3 fís', 'Repertório de Canções +3', '[{"name":"Público em Transe","type":"Passiva","description":"se a sereia fizer um ataque padrão contra um alvo Fascinado por sua canção, o ataque causa 2d10+1 pontos de dano, em vez do dano padrão."},{"name":"Canção Fascinante","type":"Ação","description":"gaste 1 Ponto de Medo para cantar uma música que afeta todos os alvos próximos, que devem passar em um teste de reação de Instinto, ou ficam Fascinados até marcarem 2 Pontos de Fadiga. Outras sereias próximas do alvo podem marcar 1 Ponto de Fadiga cada para aumentar a Dificuldade do teste de reação em +1. Enquanto estiver Fascinado, o alvo não pode agir e fica Vulnerável."}]', 'img/enemies/enemy_p19_564.png'),
(87, 'Soldado de Elite', 2, 'Comum', '', 'Um escudeiro de armadura ou plebeu experiente buscando crescimento.', 'fazer alianças, manter a ordem, obter glória', 15, '9/18', 4, 3, '+1', 'Lança: muito próximo', '2d8+4 fís', '', '[{"name":"Reforçar","type":"Ação","description":"marque 1 Ponto de Fadiga para ficar corpo a corpo a um aliado e fazer um ataque contra um alvo muito próximo. Em caso de sucesso, o alvo sofre 2d10+2 pontos de dano físico e o aliado pode recuperar 1 Ponto de Fadiga."},{"name":"Lealdade do Vassalo","type":"Reação","description":"quando o soldado estiver muito próximo de um aliado que seja um cavaleiro ou outro nobre prestes a receber dano, ele pode marcar 1 PF para ficar em alcance corpo a corpo do aliado e sofrer o dano em seu lugar."}]', 'img/enemies/enemy_p14_450.png'),
(88, 'Tubarão', 2, 'Brutamonte', '', 'Um grande predador aquático, sempre em ação.', 'atacar o fraco, isolar a presa, seguir sangue', 14, '14/28', 7, 3, '+2', 'Mandíbula dentuça: muito próximo', '2d12+1 fís', 'Olfato +3', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o tubarão acerta um ataque, todos os personagens distantes perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Mordida Lacerante","type":"Passiva","description":"quando o tubarão acerta um ataque, o alvo deve marcar 1 PA sem receber seus benefícios (mas ainda pode usar PA para reduzir o dano). Caso não possa marcar 1 PA, o alvo deve marcar 1 PV adicional."},{"name":"Sangue na água","type":"Reação","description":"quando uma criatura próxima do tubarão marca Pontos de Vida por um ataque de outra criatura, você pode marcar 1 Ponto de Fadiga para pôr ele em foco imediatamente, deixá-lo corpo a corpo ao alvo e fazer um ataque padrão."}]', 'img/enemies/enemy_p17_518.png'),
(89, 'Autômato Carcereiro', 3, 'Assistente', '', 'Um construto-jaula com portas metálicas grossas no torso.', 'bater, carregar para longe, emboscar, proteger', 16, '19/33', 5, 3, '+2', 'Corpo Esmagador: muito próximo', '3d6+2 fís', '', '[{"name":"Escudo Defensivo","type":"Passiva","description":"criaturas corpo a corpo ao carcereiro sofrem desvantagem em testes de ataque contra ele. Criaturas aprisionadas dentro dele são imunes a este efeito."},{"name":"Prender","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra um alvo muito próximo. Se acertar, o carcereiro Imobiliza o alvo dentro de si até que passe em um teste de Força (18). Alvos Imobilizados por esta ação só podem atacar o carcereiro."}]', 'img/enemies/enemy_p20_584.png'),
(90, 'Autômato Sentinela', 3, 'Brutamonte', '', 'Um construto empoeirado com mãos de maça.', 'destruir a qualquer custo, expurgar, proteger', 17, '21/40', 6, 3, '+3', 'Maça potente: muito próximo', '2d12+1 fís', '', '[{"name":"Pancada Cinética","type":"Passiva","description":"alvos que sofram dano do ataque padrão da sentinela são empurrados a um ponto muito próximo."},{"name":"Encaixotar","type":"Ação","description":"marque 1 Ponto de Fadiga para focar em um alvo muito próximo. O alvo sofre desvantagem em testes de ataque enquanto estiver muito próximo da sentinela. A sentinela só pode focar em um alvo de cada vez."},{"name":"Tiro de Mana","type":"Ação","description":"gaste 1 Ponto de Medo para causar uma explosão mágica em um ponto em alcance distante. Todos muito próximos do ponto escolhido devem fazer um teste de reação de Agilidade. Quem falhar sofre 2d8+20 pontos de dano mágico e são empurrados para um ponto em alcance próximo. Quem passar sofre metade do dano e não é empurrado."},{"name":"Impulso","type":"Reação","description":"quando a sentinela acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p20_584.png'),
(91, 'Autômato Torreta', 3, 'Atirador', '', 'Uma torreta imensa com armadura reforçada e doze pernas mecânicas.', 'confinar, concentrar fogo, marcar, proteger', 16, '20/32', 5, 4, '+3', 'Canhão mecanomágico: distante', '3d10+3 mág', '', '[{"name":"Fogo Lento","type":"Passiva","description":"se você puser a torreta em foco e ela não tiver nenhum marcador, ela não pode fazer um ataque padrão. Coloque um marcador na ficha e descreva o que ela está se preparando para fazer. Quando puser a torreta em foco e ela tiver um marcador na ficha, remova o marcador para que ela possa atacar."},{"name":"Marcar Alvo","type":"Ação","description":"gaste 1 Ponto de Medo para Marcar um alvo distante, que fica Marcado até a torreta ser destruída ou até o alvo se esconder. A Evasão de um alvo Marcado é reduzida à metade."},{"name":"Concentrar Fogo","type":"Reação","description":"quando outro adversário causar dano a um alvo distante da torreta, você pode marcar 1 PF para somar o ataque padrão da torreta à rolagem de dano."},{"name":"Detonação","type":"Reação","description":"quando a torreta for destruída, ela explode. Todos os alvos próximos devem fazer um teste de reação de Agilidade. Quem falhar sofre 3d20 pontos de dano físico. Quem passar sofre metade do dano."}]', 'img/enemies/enemy_p20_584.png'),
(92, 'Cavaleiro Cervo', 3, 'Comum', '', 'Um cavaleiro com imponentes galhadas e usa armadura de espinhos.', 'eliminar intrusos, isolar, manobrar, proteger a floresta', 17, '19/36', 7, 5, '+3', 'Espada de vinhas: corpo a corpo', '3d8+3 fis', 'Conhecimento da Floresta +3', '[{"name":"Aqui em Cima","type":"Passiva","description":"quando o cavaleiro acerta um ataque padrão vindo de cima do alvo, ele causa 3d12+3 pontos de dano físico, em vez do dano padrão."},{"name":"Lâmina da Floresta","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque contra todos os alvos muito próximos. Alvos atingidos sofrem dano físico igual a 3d4 + o limiar maior do alvo."},{"name":"Armadura de Espinhos","type":"Reação","description":"quando o cavaleiro sofre dano de um ataque corpo a corpo, você pode marcar 1 Ponto de Fadiga para causar 1d10+5 pontos de dano físico ao atacante."}]', 'img/enemies/enemy_p5_198.png'),
(93, 'Centelha Elemental', 3, 'Lacaio', '', 'Uma fagulha ardente de fogo elemental.', 'crescer, consumir, inflamar', 15, 'nenhum', 1, 1, '+0', 'Explosões de fogo: próximo', '5 mág', '', '[{"name":"Lacaio (9)","type":"Passiva","description":"a centelha é derrotada quando sofre qualquer dano. Para cada 9 pontos de dano causados por um personagem à centelha, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todas as centelhas elementais próximas dele. Esses lacaios ficam corpo a corpo ao alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 5 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p4_159.png'),
(94, 'Demônio da Avareza', 3, 'Assistente', '', 'Monstro em trajes de nobre, com chifres circulares adornados por joias.', 'alimentar avareza, consumir, semear discórdia', 17, '15/29', 6, 5, '+2', 'Mandíbula faminta: corpo a corpo', '3d6+5 mág', 'Manipulação +3', '[{"name":"Números Vão Subir","type":"Passiva","description":"testes de ataque do demônio recebem um bônus igual ao número de punhados de ouro que ele possui."},{"name":"Tudo Tem um Preço","type":"Passiva","description":"ataques contra o demônio sofrem desvantagem a não ser que o atacante gaste um punhado de ouro. O demônio começa com um número de punhados de ouro igual ao número de personagens. Quando um alvo precisa marcar PV por causa do ataque padrão do demônio, o alvo pode escolher gastar um punhado de ouro no lugar de marcar Pontos de Vida (1 punhado por PV). Punhados de ouro gastos por personagens graças a este efeito são somados ao total do demônio da avareza."},{"name":"Tempo é Dinheiro","type":"Ação","description":"gaste 3 punhados de ouro (ou 1 Ponto de Medo) para pôr 1d4+1 aliados em foco."}]', 'img/enemies/enemy_p21_618.png'),
(95, 'Demônio do Desespero', 3, 'Oportunista', '', 'Um demônio de membros longos, que se infiltra nas sombras.', 'manter-se nas sombras, minar a determinação, tornar o medo contagiante', 17, '18/35', 6, 5, '+3', 'Raio miasmático: distante', '3d6+1 mág', 'Manipulação +3', '[{"name":"Profundezas do Desespero","type":"Passiva","description":"o demônio causa dano dobrado a personagens com 0 Pontos de Esperança."},{"name":"Esforço é Inútil","type":"Ação","description":"gaste 1 Ponto de Medo para afetar os espíritos de todos os personagens Distantes. Alvos afetados devem substituir seus Dados de Esperança por 1d8 até rolar um sucesso com Esperança ou até seu próximo descanso."},{"name":"Impulso","type":"Reação","description":"quando o demônio acertar um ataque contra um personagem, receba 1 Ponto de Medo."},{"name":"Amigos São uma Decepção","type":"Reação","description":"quando um personagem falhar com Medo, você pode marcar 1 PF para fazer com que todos os outros personagens próximos percam 1 Ponto de Esperança."}]', 'img/enemies/enemy_p21_616.png'),
(96, 'Demônio da Inveja', 3, 'Atirador', '', 'Uma demônio inconstante, de membros esguios e desejos insaciáveis.', 'guardar rancor, pegar o que é dos outros, usurpar o sucesso alheio', 17, '17/30', 6, 6, '+4', 'Ataque psíquico: distante', '3d8+3 mág', 'Manipulação +3', '[{"name":"Mente Desprotegida","type":"Passiva","description":"o ataque padrão do demônio causa dano direto."},{"name":"Minha Vez","type":"Reação","description":"quando o demônio marcar Pontos de Vida por um ataque, gaste uma quantidade de Pontos de Medo igual à de PV marcados para fazer o atacante marcar a mesma quantidade de Pontos de Vida."},{"name":"Agora É Meu!","type":"Reação","description":"quando um personagem muito próximo do demônio sofre dano grave, você pode gastar 1 Ponto de Medo para forçar o alvo a fazer um teste de reação de Acuidade. Se ele falhar, o demônio escolhe um item ou consumível do inventário do alvo e o toma para si."},{"name":"Rivalidade","type":"Reação","description":"quando uma criatura próxima sofre dano de outro adversário, você pode marcar 1 PF para somar 1d4 à rolagem de dano."}]', 'img/enemies/enemy_p21_614.png'),
(97, 'Demônio da Ira', 3, 'Brutamonte', '', 'Um demônio com punhos gigantescos movido por uma fúria infindável.', 'alimentar a fúria, causar destruição, impressionar rivais', 17, '22/40', 7, 5, '+3', 'Punhos: muito próximo', '3d8+1 mág', 'Intimidação +2', '[{"name":"Ira Implacável","type":"Passiva","description":"os ataques do demônio causam dano direto."},{"name":"Calor da Batalha","type":"Ação","description":"gaste 1 Ponto de Medo para enraivecer todos os personagens. Eles devem usar 1d20 como Dado de Medo até o fim da cena."},{"name":"Retaliação","type":"Reação","description":"quando o demônio sofre dano de um ataque próximo, você pode marcar 1 Ponto de Fadiga para fazer um ataque padrão contra o atacante."},{"name":"Sangue e almas","type":"Reação","description":"Contagem (ciclo 1d6). Ative a contagem quando um ataque for feito no campo de visão do demônio. A contagem diminui sempre que um personagem for atingido por uma ação violenta. Ao final da contagem, invoque 1d4 demônios menores, que surgem em pontos em alcance próximo."}]', 'img/enemies/enemy_p22_640.png'),
(98, 'Demônio da Soberba', 3, 'Líder', '', 'Um demônio belo e cruel, com uma lança reluzente e robes elegantes.', 'clamar vitória prematura, condescendência, provar superioridade', 18, '18/36', 7, 5, '+4', 'Lança perfeita: muito próximo', '3d10 fís', 'Manipulação +2', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o demônio acerta um ataque, todos os personagens Distantes perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Dobro ou Nada","type":"Passiva","description":"quando um personagem distante falhar em um teste, ele pode rolar novamente seu Dado de Medo e ficar com o novo resultado. Se falhar novamente, ele deve marcar 2 PF, enquanto o Demônio recupera 1 Ponto de Fadiga."},{"name":"Perícia Inigualável","type":"Ação","description":"marque 1 Ponto de Fadiga para causar o dano do ataque padrão do demônio a um alvo próximo."},{"name":"Raiz da Perversidade","type":"Ação","description":"gaste 1 Ponto de Medo para colocar em foco dois outros demônios Distantes."},{"name":"Sem Comparação","type":"Reação","description":"quando um personagem próximo do demônio falhar em um teste, o personagem deve marcar 1 PF."}]', 'img/enemies/enemy_p21_612.png'),
(99, 'Dragão do Gelo Jovem', 3, 'Solo', '', 'Um dragão azul com quatro patas poderosas e asas tingidas de gelo.', 'avalanche, congelar, defender covil, espancar, proteger o que é meu, voar', 18, '21/41', 10, 6, '+7', 'Mordida e garras: próximo', '4d10 fís', 'Proteger o Que É Meu +3', '[{"name":"Desespero","type":"Passiva","description":"quando um personagem distante do dragão rola com Medo, ele perde 1 Ponto de Esperança."},{"name":"Inclemente (3)","type":"Passiva","description":"o dragão pode ser posto em foco até 3 vezes por turno do mestre. Gaste Ponsos de Medo normalmente para colocá-lo em foco."},{"name":"Romper e Esmagar","type":"Passiva","description":"se um alvo atingido pelo dragão não marcar Pontos de Armadura para reduzir o dano, o alvo deve marcar 1 Ponto de Fadiga."},{"name":"Avalanche","type":"Ação","description":"gaste 1 Ponto de Medo para o dragão provocar um grande deslizamento de neve e gelo, cobrindo todas as outras criaturas distantes. Todos os alvos na área devem passar em um teste de reação de Instinto ou serão soterrados por pedras e neve, ficando Vulneráveis até que se libertem dos escombros. Receba 1 Ponto de Medo para cada personagem que falhar no teste."},{"name":"Sopro da Nevasca","type":"Ação","description":"gaste 2 Pontos de Medo para liberar uma espiral congelante na área próxima na frente do dragão. Todos os alvos na área devem fazer um teste de reação de Agilidade. Quem passar devem marcar 2 Pontos de Fadiga ou sofrer metade do dano a seguir. Quem falhar sofre 4d6+5 pontos de dano mágico e fica Imobilizado pelo gelo até que se liberte com sucesso em um teste de Força."},{"name":"Escamas Congeladas","type":"Reação","description":"quando uma criatura muito próxima acertar um ataque contra o dragão, ela deve marcar 1 Ponto de Fadiga e fica Arrefecido até o próximo descanso ou até recuperar 1 Ponto de Fadiga. Criaturas Arrefecidas sofrem desvantagem em testes de ataque."},{"name":"Impulso","type":"Reação","description":"quando o dragão acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p22_642.png'),
(100, 'Dríade', 3, 'Líder', '', 'Um espírito da natureza em forma de uma árvore humanoide.', 'cultivar, expulsar, ordenar, preservar floresta', 16, '24/38', 8, 5, '+4', 'Arco curto outonal: distante', '3d10+1 fís', 'Conhecimento da Floresta +4', '[{"name":"Área de Espinhos","type":"Ação","description":"marque 1 Ponto de Fadiga e escolha um ponto em alcance distante. Crie um arbusto de espinhos que cobre a área próxima do ponto escolhido. Todos os alvos na área sofrem 2d6+2 pontos de dano físico quando forem tentar agir. Um alvo deve passar em um teste de Acuidade ou causar mais de 20 pontos de dano à dríade em um ataque para sair da área."},{"name":"Cultivar Mudas","type":"Ação","description":"gaste 1 Ponto de Medo para cultivar três lacaios entes menores, que surgem em um ponto em alcance próximo e são postos em foco imediatamente."},{"name":"Todos Um","type":"Reação","description":"quando um aliado próximo morrer, você pode gastar 1 Ponto de Medo para recuperar 2 PV e 2 PF, uma vez que a força vital do aliado retornou à floresta."}]', 'img/enemies/enemy_p4_161.png'),
(101, 'Ente Carvalho', 3, 'Brutamonte', '', 'Uma árvore antiga e sólida, capaz de se movimentar.', 'bater com galhos, esconder-se à vista, preservar a floresta, fincar raízes', 17, '22/40', 7, 4, '+2', 'Galho: muito próximo', '3d8+2 fís', 'Conhecimento da Floresta +3', '[{"name":"Só Uma Árvore","type":"Passiva","description":"antes de fazer qualquer ataque numa luta, ou depois de se esconder, o ente é indistinguível de outras árvores até que faça algo ou até que um personagem passe em um teste de Instinto para identificá-lo."},{"name":"Barragem de Sementes","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra até três alvos próximos, atirando sementes neles. Alvos atingidos sofrem 2d10+5 pontos de dano físico."},{"name":"Enraizar","type":"Ação","description":"marque 1 Ponto de Fadiga para Enraizar o ente onde ele estiver, deixando-o Imobilizado enquanto estiver Enraizado. Ele pode encerrar este efeito em vez de se mover quando estiver em foco. Enquanto estiver Enraizado o ente tem resistência a dano físico."}]', 'img/enemies/enemy_p4_161.png'),
(102, 'Ente Jovem', 3, 'Lacaio', '', 'Uma pequena muda senciente.', 'bater, cercar, misturar-se, preservar a floresta', 14, 'nenhum', 1, 1, '+0', 'Galhos: corpo a corpo', '8 fís', '', '[{"name":"Lacaio (6)","type":"Passiva","description":"o ente é derrotado quando sofre qualquer dano. Para cada 6 pontos de dano causados por um personagem ao ente, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os entes jovens próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 8 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p4_161.png'),
(103, 'Grande Elemental da Terra', 3, 'Brutamonte', '', 'Um deslizamento vivo de pedras e poeira, grande como uma casa.', 'avalanche, derrubar, socar', 17, '22/40', 10, 4, '+7', 'Punho de pedra: muito próximo', '3d10+1 fís', '', '[{"name":"Lentidão","type":"Passiva","description":"se o elemental for posto em foco, mas não tiver nenhum marcador em sua ficha, ele é incapaz de agir. Coloque um marcador na ficha e descreva o que ele está se preparando para fazer. Quando puser o elemental em foco e ele tiver um marcador na ficha, remova o marcador para que ele possa agir."},{"name":"Objeto Fixo","type":"Passiva","description":"um ataque que moveria o elemental o faz em dois alcances a menos (por exemplo, alcance distante se torna muito próximo). Quando o elemental sofrer dano físico, reduza esse dano em 7 pontos."},{"name":"Soterrar","type":"Passiva","description":"quando o elemental acertar um ataque, o alvo deve perder 1 Ponto de Armadura sem receber seus benefícios (mas ainda pode usar PA para reduzir o dano). Se não puder perder 1 PA, o alvo deve marcar 1 PV adicional."},{"name":"Deslizamento","type":"Ação","description":"marque 1 Ponto de Fadiga para criar um deslizamento que soterra com escombros a área próxima em frente ao elemental. Todos os alvos na área devem fazer um teste de reação de Agilidade (19). Quem falhar sofre 2d12+5 pontos de dano físico e ficam Vulneráveis até fazer uma rolagem com Esperança. Quem passar sofre metade do dano."},{"name":"Impulso","type":"Reação","description":"quando o elemental acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p23_662.png'),
(104, 'Grande Elemental da Água', 3, 'Assistente', '', 'Uma grande onda viva que engole seus inimigos.', 'afogar, dilúvio, dispersar', 17, '17/34', 5, 5, '+3', 'Onda devastadora: muito próximo', '3d4+1 mág', '', '[{"name":"Afogar","type":"Ação","description":"gaste 1 Ponto de Medo para fazer um ataque contra todos os alvos muito próximos. Alvos atingidos pelo elemental ficam Imobilizados e Vulneráveis e começam a se afogar. Um alvo pode se libertar com um sucesso em um teste de Força ou Instinto, que encerran ambas as condições."},{"name":"Jato D’água","type":"Ação","description":"marque 1 Ponto de Fadiga para atacar um alvo muito próximo. Em caso de sucesso, o alvo sofre 2d4+7 pontos de dano e desvantagem no seu próximo teste. Em caso de falha, o alvo deve marcar 1 Ponto de Fadiga."},{"name":"Maré Alta","type":"Reação","description":"quando o elemental acerta um ataque padrão, você pode marcar 1 Ponto de Fadiga para empurrar o alvo para um ponto em alcance próximo."}]', 'img/enemies/enemy_p23_662.png'),
(105, 'Hidra', 3, 'Solo', '', 'Um quadrúpede bestial com várias cabeças em pescoços compridos, cada uma munida de presas terríveis.', 'aterrorizar, devorar, regenerar', 18, '19/35', 10, 5, '+3', 'Mordida: próximo', '2d12+2 fís', '', '[{"name":"Bicho de Várias Cabeças","type":"Passiva","description":"a hidra começa com 3 cabeças e pode chegar até 5. Cada vez que a hidra sofrer dano maior ou superior, ela perde uma cabeça."},{"name":"Inclemente (X)","type":"Passiva","description":"a hidra pode ser posta em foco até X vezes por turno do mestre, sendo X o número de cabeças dela. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Berro Aterrorizante","type":"Ação","description":"todos os personagens distantes perdem 2 Pontos de Esperança."},{"name":"Regeneração","type":"Ação","description":"se a hidra tiver marcado algum Ponto de Vida, gaste 1 Ponto de Medo para que ela recupere 1 PV e faça crescer novas duas cabeças."},{"name":"Fraqueza Mágica","type":"Reação","description":"quando a hidra sofre dano mágico, ela fica Atordoada até a próxima rolagem com Medo. Enquanto estiver Atordoada, ela não pode usar Regeneração, mas fica imune a dano mágico."}]', 'img/enemies/enemy_p24_680.png'),
(106, 'Lodo Verde Gigante', 3, 'Oportunista', '', 'Um monte ácido verde mais alto que um humano comum.', 'camuflagem, envolver, esgueirar, multiplicar-se', 15, '15/30', 7, 4, '+3', 'Tentáculo de lodo: corpo a corpo', '3d8+1 mág', 'Misturar-se +3', '[{"name":"Forma Ácida","type":"Passiva","description":"quando o lodo acertar um ataque, o alvo deve marcar 1 Ponto de Armadura sem receber seus benefícios (mas ainda pode usar PA para reduzir o dano). Caso não possa marcar 1 PA, o alvo deve marcar 1 Ponto de Vida adicional."},{"name":"Lentidão","type":"Passiva","description":"se o lodo for posto em foco, mas não tiver nenhum marcador em sua ficha, ele é incapaz de agir. Coloque um marcador na ficha e descreva o que ele está se preparando para fazer. Quando puser o lodo em foco e ele tiver um marcador na ficha, remova o marcador para que ele possa agir."},{"name":"Envolver","type":"Ação","description":"faça um ataque padrão em um alvo corpo a corpo. Em caso de sucesso, o lodo Envolve o alvo, que deve marcar 2 Pontos de Fadiga. Alvos Envolvidos devem marcar 1 PF adicional ao fazer um teste. Se o lodo sofrer dano grave, o alvo é libertado."},{"name":"Agora São Dois","type":"Reação","description":"quando o lodo tiver marcado 4 PV ou mais, você pode gastar 1 Ponto de Medo para dividi-lo em dois lodos verdes (sem PV ou PF marcados) e postos em foco imediatamente."}]', 'img/enemies/enemy_p7_268.png'),
(107, 'Monarca', 3, 'Manipulador', '', 'O soberano de uma nação, cercado de privilégios e detentor de poder sem igual em seus domínios.', 'criar um legado, reger vassalos, vencer rivais', 16, '16/32', 6, 5, '+0', 'Martelo de guerra: corpo a corpo', '3d6+3 fís', 'História +3, Nobreza +3', '[{"name":"Execute Eles!","type":"Ação","description":"gaste 1 Ponto de Medo por personagem do grupo de aventureiros para condená-lo por crimes reais ou inventados. Um personagem que passar em um teste de Presença pode exigir um julgamento por combate ou outro tipo de julgamento especial."},{"name":"Guarda da Coroa","type":"Ação","description":"uma vez por cena, marque 1 PF para invocar seis lacaios de 3º patamar, que surgem em pontos em alcance próximo para servir à vontade do monarca."},{"name":"Casus Belli","type":"Reação","description":"Contagem de longo prazo (8). Gaste 1 Ponto de Medo para ativar a contagem depois que o desejo de guerra do monarca for revelado. Quando a contagem termina, o monarca terá motivos para enviar sua nação à guerra, e terá apoio por essas motivações. Receba 1d4 Pontos de Medo."}]', 'img/enemies/enemy_p17_518.png'),
(108, 'Morcego Atroz', 3, 'Oportunista', '', 'O leal animal de estimação de um vampiro.', 'esconder-se, mergulho rasante, proteger líder', 14, '16/30', 5, 3, '+2', 'Garras e presas: corpo a corpo', '2d6+7 fís', 'Sede de Sangue +3', '[{"name":"Voador","type":"Passiva","description":"enquanto estiver em voo, a Dificuldade do morcego aumenta em +3."},{"name":"Guincho","type":"Ação","description":"marque 1 Ponto de Fadiga para dar um guincho agudo na direção de todos os alvos Distantes que na frente do morcego. Alvos devem marcar 1d4 PF."},{"name":"Guardião","type":"Reação","description":"quando um aliado vampiro marca Pontos de Vida, o morcego pode marcar 1 Ponto de Fadiga para voar, ficar corpo a corpo do atacante e fazer um ataque com vantagem contra ele. Em caso de sucesso, o morcego causa 2d6+2 pontos de dano físico."}]', 'img/enemies/enemy_p25_700.png'),
(109, 'Oscilume Adulto', 3, 'Solo', '', 'Um inseto alado grande como uma casa com escamas iridescentes e asas mais velozes que o olhar.', 'arrebatar, caçar, colecionar coisas brilhantes, fazer ninhos.', 17, '20/35', 12, 6, '+3', 'Asas afiadas: muito próximo', '3d20 fís', '', '[{"name":"Inclemente (4)","type":"Passiva","description":"o oscilume pode ser posto em foco até 4 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Nunca Erra","type":"Passiva","description":"quando o oscilume fizer um ataque, a Evasão do alvo é reduzida à metade para este ataque."},{"name":"Voo Mortal","type":"Passiva","description":"enquanto estiver em voo, o oscilume pode se mover até um ponto em alcance distante em vez de alcance próximo antes de fazer uma ação."},{"name":"Dança Mental","type":"Ação","description":"marque 1 Ponto de Fadiga para criar uma exibição mágica que ocupa a mente dos inimigos ao redor. Todos os alvos próximos devem fazer um teste de reação de Instinto. Para cada alvo que falhe, você recebe 1 Ponto de Medo e o oscilume descobre um dos medos do alvo."},{"name":"Redemoinho","type":"Ação","description":"gaste 1 Ponto de Medo para rodopiar, fazendo um ataque contra todos os alvos muito próximos. Alvos atingidos sofrem 3d8 pontos de dano físico direto."},{"name":"Reflexos Sinistros","type":"Reação","description":"quando o oscilume sofre dano de um ataque próximo, você pode marcar 1 Ponto de Fadiga para reduzir o dano à metade."},{"name":"Sopro Alucinógeno","type":"Reação","description":"Contagem (ciclo 1d6). Quando o oscilume sofrer dano pela primeira vez, ative a contagem regressiva. Quando ela terminar, o oscilume sopra um gás alucinógeno em todos os alvos Distantes à sua frente. Alvos precisam passar em um teste de reação de Instinto ou têm visões terríveis. Alvos cujos medos o oscilume conheça sofrem desvantagem nesse teste. Alvos que falhem no teste perdem 2 Pontos de Esperança e sofrem 3d8+3 pontos de dano mágico direto."}]', 'img/enemies/enemy_p25_702.png'),
(110, 'Vampiro', 3, 'Comum', '', 'Um morto-vivo inteligente com lábios manchados de sangue e um sorriso de predador.', 'encantar, enganar, intimidar, morder, sorver', 16, '18/35', 5, 4, '+3', 'Rapieira: corpo a corpo', '3d8 fís', 'Caçador noturno +3', '[{"name":"Mordida Vampírica","type":"Ação","description":"faça um ataque contra um alvo corpo a corpo. Em caso de sucesso, cause 5d4 pontos de dano físico. Um alvo que marque Pontos de Vida por causa deste ataque perde 1 Ponto de Esperança e deve marcar 1 Ponto de Fadiga. O vampiro, então, recupera 1 PV."},{"name":"Forma de Névoa","type":"Reação","description":"quando o vampiro sofre dano físico, você pode gastar 1 Ponto de Medo para reduzir esse dano à metade."}]', 'img/enemies/enemy_p25_700.png'),
(111, 'Vampiro Mestre', 3, 'Líder', '', 'Um morto-vivo cativante que se veste com a elegância de um nobre.', 'criar servos, encantar, intimidar, mandar, voar', 17, '22/42', 6, 6, '+5', 'Rapieira: corpo a corpo', '2d20+4 fís', 'Aristocrata +3', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o vampiro acerta um ataque, todos os personagens distantes perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Olhe nos Meus Olhos","type":"Passiva","description":"uma criatura que se mova para ficar corpo a corpo ao vampiro deve fazer um teste de reação de Instinto. Se ela falhar, você recebe 1d4 Pontos de Medo."},{"name":"Começou a Caçada","type":"Ação","description":"gaste 2 Pontos de Medo para invocar 1d4 vampiros, que surgem em pontos em alcance distante e são postos em foco imediatamente."},{"name":"Consumir Seguidores","type":"Ação","description":"quando o vampiro estiver corpo a corpo a um aliado, ele pode fazer o aliado marcar 1 Ponto de Vida. O vampiro, então, recupera 1 PV."},{"name":"Drenar Vida","type":"Reação","description":"quando o vampiro é posto em foco, role 1d8. Se rolar 6 ou mais, todos os alvos muito próximos devem marcar 1 PV."}]', 'img/enemies/enemy_p25_700.png'),
(112, 'Arquinecromante', 4, 'Líder', '', 'Um mago em decomposição vestindo robes esfarrapados.', 'corromper, decompor, fugir para lutar outro dia, ressuscitar', 21, '33/66', 9, 8, '+6', 'Raio necrótico: distante', '4d12+8 mág', 'Conhecimento Proibido +3, Sabedoria Secular +3', '[{"name":"Dança da Morte","type":"Ação","description":"marque 1 Ponto de Fadiga para pôr em foco 1d4 aliados. Ataques feitos por aliados postos em foco desta maneira causam metade do dano, ou você pode gastar 1 Ponto de Medo para que causem dano completo."},{"name":"Feixe Decadente","type":"Ação","description":"marque 2 Pontos de Fadiga para fazer com que todos os alvos Distantes façam um teste de reação de Forca. Quem falhar sofre 2d20+12 pontos de dano mágico e você recebe 1 Ponto de Medo. Quem passar sofre metade do dano. Um alvo que marque 2 PV ou mais também deve marcar 2 PF e fica Vulnerável até rolar com Esperança."},{"name":"Portões da Morte","type":"Ação","description":"gaste 1 Ponto de Medo para invocar uma legião de zumbis, que surge em um ponto em alcance próximo e é posta em foco imediatamente."},{"name":"Hoje Não, Meus Caros","type":"Reação","description":"quando o arquinecromante tiver marcado 7 Pontos de Vida ou mais, você pode gastar 1 Ponto de Medo para fazê-lo se teleportar para um lugar seguro, onde pode se recuperar. Um personagem que passe em um teste de Instinto pode rastrear o destino do arquinecromante."},{"name":"Sua Vida É Minha","type":"Reação","description":"Contagem (Ciclo 2d6). Quando o arquinecromante tiver marcado 6 Pontos de Vida ou mais, ative a contagem regressiva. No fim da contagem, você causa 2d10+6 pontos de dano mágico direto a um alvo próximo. O arquinecromante, então, recupera um número de PF ou de PV iguais ao número de PV marcados pelo alvo do ataque."}]', 'img/enemies/enemy_p26_718.png'),
(113, 'Caído, Feiticeiro', 4, 'Assistente', '', 'Um mago poderoso aprisionado pelas barganhas que realizou em vida.', 'adquirir, atormentar, desencorajar, dominar', 19, '26/42', 6, 5, '+4', 'Cajado Corrupto: distante', '4d6+10 mág', 'Conhecimento Antigo +2', '[{"name":"Conflagração","type":"Ação","description":"gaste 1 Ponto de Medo para liberar uma tempestade de fogo implacável e fazer um ataque contra todos os alvos próximos. Alvos atingidos pelo feiticeiro sofrem 2d10+6 pontos de dano mágico direto."},{"name":"Prisão de Pesadelos","type":"Ação","description":"marque 1 Ponto de Fadiga para prender um alvo distante em uma poderosa ilusão de seus piores medos. Enquanto estiver preso, o alvo fica Imobilizado e Vulnerável até que se liberte com sucesso em um teste de Instinto, que remove as duas condições."},{"name":"Escorregadio","type":"Reação","description":"se o feiticeiro sofrer dano causado por um ataque, ele pode se teleportar para um ponto em alcance distante."},{"name":"Grilhões da Culpa","type":"Reação","description":"Contagem (Ciclo 2d6). Quando o feiticeiro for posto em foco pela primeira vez, ative a contagem regressiva. Quando a contagem terminar, todos os alvos Distantes ficam Vulneráveis e devem marcar 1 Ponto de Fadiga por terem revivido seus maiores arrependimentos. Um alvo pode se libertar da culpa com sucesso em um teste de Presença ou Força. Falhar nesse teste causa perda de 1 Ponto de Esperança."}]', 'img/enemies/enemy_p26_718.png'),
(114, 'Caído, Defensor', 4, 'Lacaio', '', 'Uma alma maldita, presa pela vontade dos Deuses Caídos.', 'conquistar descanso, dominar, esmagar, punir', 18, 'nenhum', 1, 1, '+2', 'Machado maldito: muito próximo', '12 fís', '', '[{"name":"Aura de Ruína","type":"Passiva","description":"um personagem que marque PV por um ataque feito pelo defensor perde 1 Ponto de Esperança."},{"name":"Lacaio (12)","type":"Passiva","description":"o defensor é derrotado quando sofre qualquer dano. Para cada 12 pontos de dano causados por um personagem ao defensor, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os defensores próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 12 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p26_718.png'),
(115, 'Caído, General Arrasa-Reinos', 4, 'Solo', '', 'Um Deus Caído, envolto em ira e ressentimento, trazendo milênios de experiência em destruir o espírito de heróis.', 'corromper, dominar, punir, quebrar os fracos', 20, '36/66', 8, 5, '+7', 'Chicote de farpas: próximo', '4d8+7 fís', 'Conquista +3, História +2, Intimidação +3', '[{"name":"Armadura de Brasas","type":"Passiva","description":"quando o arrasa-reinos sofre dano, reduza o valor em 2d10 pontos."},{"name":"Inclemente (2)","type":"Passiva","description":"o arrasa-reinos pode ser posto em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Chicote Atormentador","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque padrão contra todos os alvos muito próximos. Se um alvo usar PA para reduzir o dano deste ataque, ele perde 2 Pontos de Armadura."},{"name":"Arauto da Ruína","type":"Reação","description":"quando um alvo marcar Pontos de Vida por causa de um ataque do arrasa-reinos, todos os personagens Distantes deste alvo perdem 1 Ponto de Esperança."},{"name":"Cólera Desmedida","type":"Reação","description":"Contagem (Decrescente 8). Quando o arrasa-reinos for posto em foco pela primeira vez, ative a contagem. Quando ela terminar, ele cria uma torrente de fúria incarnada que remove a carne dos ossos. Todos os alvos Distantes devem fazer um teste de reação de Presença. Quem falhar sofre 2d6+10 pontos de dano mágico direto. Quem passar sofre metade do dano. Para cada Ponto de Vida marcado por esse dano, invoque um defensor caído em um ponto em alcance muito próximo do alvo que tenha marcado Pontos de Vida. Se a contagem regressiva tiver seu valor máximo reduzido para 0, o arrasa-reinos marca seus PV restantes e todos os alvos Distantes devem marcar todos os seus PV e fazer um movimento de morte."},{"name":"Desconheço a Derrota (mudança de forma)","type":"Reação","description":"quando o arrasa-reinos marcar seu último Ponto de Vida, substitua-o pelo campeão invicto e o ponha em foco imediatamente."}]', 'img/enemies/enemy_p27_738.png'),
(116, 'Caído, General Campeão Invicto', 4, 'Solo', '', 'Aquele que apenas os mais temíveis têm chance de temer.', 'assegurar vitória a qualquer custo, distribuir morte impiedosa, punir os desafiantes', 18, '35/58', 11, 5, '+8', 'Espada quebra-corações: muito próximo', '4d12+13 fís', 'Conquista +3, História +2, Intimidação +3', '[{"name":"Armadura Inconstante","type":"Passiva","description":"quando o campeão invicto sofre dano, reduza o valor em 1d10 pontos."},{"name":"Inclemente (3)","type":"Passiva","description":"o campeão invicto pode ser posto em foco até 3 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Golpe Destruidor","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque padrão contra todos os alvos muito próximos. Personagens atingidos perdem uma quantidade de Pontos de Esperança igual ao número de PV marcados pelo ataque."},{"name":"Infindáveis Legiões","type":"Ação","description":"gaste 1 Ponto de Medo para invocar um número de defensores caídos igual ao dobro do número de personagens, que surgem em pontos em alcance distante."},{"name":"Arauto da Ruína","type":"Reação","description":"quando um alvo marcar Pontos de Vida por causa de um ataque do arrasa-reinos, todos os personagens Distantes deste alvo perdem 1 Ponto de Esperança."},{"name":"Círculo de Profanação","type":"Reação","description":"Contagem (1d8). Quando o campeão invicto for posto em foco pela primeira vez, ative a contagem regressiva. Ao final da contagem, ative um círculo mágico que cobre uma área distante do campeão. Um alvo dentro da área fica Vulnerável até que saia do círculo. A área pode ser removida causando dano grave ao campeão invicto."},{"name":"Impulso","type":"Reação","description":"quando o campeão invicto atingir um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p27_740.png'),
(117, 'Dragão Vulcânico, Predador de Obsidiana', 4, 'Solo', '', 'Uma imensa criatura alada com escamas de obsidiana e garras impossivelmente afiadas.', 'arremeter, caçar, defender covil, intimidar, voar', 19, '33/65', 6, 5, '+8', 'Garras de obsidiana: próximo', '4d10+4 fis', 'Caçar do Alto +5', '[{"name":"Escamas de Obsidiana","type":"Passiva","description":"o dragão é resistente a dano físico."},{"name":"Inclemente (2)","type":"Passiva","description":"o dragão pode ser posto em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Voador","type":"Passiva","description":"enquanto estiver em voo, a Dificuldade do dragão aumenta em +3."},{"name":"Bomba Rasante","type":"Ação","description":"se o dragão estiver em voo, marque 1 Ponto de Fadiga para escolher um ponto em alcance distante. Mova-o até o ponto escolhido e faça um ataque contra todos os alvos muito próximos. Alvos atingidos pelo dragão sofrem 2d10+6 pontos de dano físico, devem marcar 1 Ponto de Fadiga e perdem 1 Ponto de Esperança."},{"name":"Cauda-avalanche","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra todos os alvos próximos. Alvos atingidos pelo dragão sofrem 4d6+4 pontos de dano físico, são empurrados para um ponto em alcance distante e ficam Vulneráveis até suas próxima rolagem com Esperança."},{"name":"Erupção de Fúria (mudança de forma)","type":"Reação","description":"quando o predador de obsidiana marcar seu último Ponto de Vida, substitua-o pelo flagelo de magma e o ponha em foco imediatamente."}]', 'img/enemies/enemy_p28_760.png'),
(118, 'Dragão Vulcânico, Flagelo de Magma', 4, 'Solo', '', 'Enfurecido pelas feridas, o dragão explode em lava derretida.', 'encharcar com lava, incinerar, repelir invasores, reposicionar-se', 20, '30/58', 7, 5, '+9', 'Garras cobertas de lava: próximo', '4d12+4 fís', 'Caçar do Alto +5', '[{"name":"Inclemente (3)","type":"Passiva","description":"o dragão pode ser posto em foco até 3 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Escamas Rachadas","type":"Passiva","description":"quando o dragão sofre dano, role um número de d6 igual ao número de Pontos de Vida marcados. Receba 1 Ponto de Medo para cada resultado 4 ou maior."},{"name":"Erupção","type":"Ação","description":"gaste 1 Ponto de Medo para fazer as escamas do dragão explodirem lava, cobrindo a área muito próxima. Todos os alvos na área devem passar em um teste de reação de Agilidade ou sofrem 4d6+6 pontos de dano físico e são empurrados para um ponto em alcance próximo. A área afetada permanece coberta de lava. Uma criatura, além dragão, que adentre a área ou faça uma ação dentro dela, deve marcar 6 PV."},{"name":"Poder Pulverizante","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra um alvo muito próximo. Em caso de sucesso, o alvo sofre 4d8+1 pontos de dano físico, perde 1 Ponto de Esperança e é empurrado para um ponto em alcance próximo. O dragão recupera 1 Ponto de Fadiga."},{"name":"Esguicho de Lava","type":"Reação","description":"quando o dragão sofre dano grave de um ataque muito próximo, sangue fervilhante esguicha da ferida, causando 2d10+4 pontos de dano físico direto ao atacante."},{"name":"Sopro Vulcânico","type":"Reação","description":"quando o dragão sofre dano maior, role 1d10. Se rolar 8 ou mais, o dragão sopra um jato de lava distante à sua frente. Todos os alvos na área devem fazer um teste de reação de Agilidade. Quem falhar sofre 2d10+4 pontos de dano físico, marca 1d4 Pontos de Fadiga e fica Vulnerável até que recupere 1 PF. Quem passar sofre metade do dano e deve marcar 1 Ponto de Fadiga."},{"name":"Vingança Cinzenta (mudança de forma)","type":"Reação","description":"quando o flagelo de magma marcar seu último PV, substitua-o pelo tirano das cinzas e imediatamente o ponha em foco."}]', 'img/enemies/enemy_p28_762.png'),
(119, 'Dragão Vulcânico, Tirano das Cinzas', 4, 'Solo', '', 'Nenhum inimigo jamais teve a insolência de feri-lo tanto. Quando a lava assenta, vira cinza, assim como antigos inimigos da criatura.', 'intimidar, matar ou ser morto, sufocar, voar', 18, '29/55', 8, 5, '+10', 'Garras e dentes: próximo', '4d12+15 fís', 'Caçar do Alto +5', '[{"name":"Acuado","type":"Passiva","description":"marque 1 Ponto de Fadiga em vez de gastar 1 Ponto de Medo para pôr o dragão em foco."},{"name":"Asas Feridas","type":"Passiva","description":"enquanto estiver em voo, a Dificuldade do dragão aumenta em +1."},{"name":"Inclemente (4)","type":"Passiva","description":"o dragão pode ser posto em foco até 4 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Reduzir a Cinzas","type":"Passiva","description":"quando um personagem próximo do dragão falhar em um teste, ele perde 1 Ponto de Esperança e você recebe 1 Ponto de Medo. Se um personagem não puder perder 1 Ponto de Esperança, ele deve marcar 1 PV."},{"name":"Hecatombe","type":"Ação","description":"Contagem (1d12). Gaste 1 Ponto de Medo para ativar a contagem, que diminui toda vez que um personagem rolar com Medo. Quando a contagem termina, o dragão se debate, causando dano ambiental (como um terremoto, avalanche ou colapso das paredes). Todos os alvos Distantes devem fazer um teste de reação de Força. Quem falhar sofre 2d10+10 pontos de dano físico e fica Imobilizado pelos escombros até se libertar com sucesso em um teste de Força. Quem passar sofre metade do dano. Se o dragão for derrotado enquanto a contagem ainda está ativa, prossiga com os efeitos do fim da contagem imediatamente, como consequência da destruição causada pela sua morte."},{"name":"Nuvem Cinzenta","type":"Ação","description":"gaste 1 Ponto de Medo para esmagar o chão e jogar cinzas para o ar em alcance distante. Um alvo dentro da nuvem de cinzas sofre desvantagem em testes. A nuvem se dispersa na próxima vez que um adversário for posto em foco."},{"name":"Violência Desesperada","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque contra todos os alvos próximos. Alvos atingidos pelo dragão sofrem 2d20+2 pontos de dano físico, são empurrados para pontos em alcance próximo de onde estavam e devem marcar 1 Ponto de Fadiga."}]', 'img/enemies/enemy_p29_778.png'),
(120, 'Exaltado, Arqueiro', 4, 'Atirador', '', 'Soldados espirituais armados com um arco santo.', 'atirar, focar flecha, obedecer, reposicionar-se', 19, '25/45', 3, 2, '+4', 'Arco longo santo: distante', '4d8+8 fís', '', '[{"name":"Punição dos Culpados","type":"Passiva","description":"o arqueiro causa dano dobrado a alvos marcados como Culpados por um serafim supremo."},{"name":"Saraivada Divina","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque padrão contra até três alvos."}]', 'img/enemies/enemy_p14_450.png'),
(121, 'Exaltado, Soldado', 4, 'Lacaio', '', 'Almas de fiéis abençoados com armamento divino.', 'aglomerar, obedecer, manobrar melhor, punir', 18, 'nenhum', 1, 2, '+2', 'Espada e escudo: corpo a corpo', '10 fís', '', '[{"name":"Lacaio (13)","type":"Passiva","description":"o soldado é derrotado quando sofre qualquer dano. Para cada 13 pontos de dano causados por um personagem ao soldado, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Voo Divino","type":"Passiva","description":"enquanto o soldado estiver em voo, gaste 1 Ponto de Medo para movê-lo paraum ponto em alcance distante, em vez de próximo, antes de realizar uma ação."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os soldados exaltados próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 10 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p14_450.png'),
(122, 'Kraken', 4, 'Solo', '', 'Uma besta marinha lendária, maior que o maior dos galeões, com tentáculos repletos de ventosas e uma bocarra terrível.', 'afogar, agarrar, consumir, esmagar', 20, '35/70', 11, 8, '+7', 'Tentáculos: próximo', '4d12+10 fís', 'Natação +3', '[{"name":"Inclemente (3)","type":"Passiva","description":"o kraken pode ser posto em foco até 3 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Múltiplos Tentáculos","type":"Passiva","description":"enquanto o kraken tiver 7 Pontos de Vida marcados ou menos, ele pode fazer seu ataque padrão contra dois alvos dentro do alcance."},{"name":"Agarrar e Afogar","type":"Ação","description":"faça um teste de ataque contra um alvo próximo. Em caso de sucesso, marque 1 Ponto de Fadiga para agarrar a vítima com um tentáculo e puxá-la para dentro da água. O alvo fica Imobilizado e Vulnerável até que se liberte com sucesso em um teste de Força ou até que o kraken sofra dano maior ou superior. Enquanto estiver Imobilizado e Vulnerável por esta habilidade, o alvo deve marcar 1 PF quando fizer um teste."},{"name":"Jato Fervente","type":"Ação","description":"gaste 1 Ponto de Medo para que o kraken cuspa um jato de água fervente em todos os alvos Distantes que estiverem em linha. Todos os alvos precisam passar em um teste de reação de Agilidade ou sofrem 4d6+9 pontos de dano físico. Se um alvo marcar Pontos de Armadura para reduzir o dano, ele também deve marcar 1 Ponto de Fadiga."},{"name":"Impulso","type":"Reação","description":"quando o kraken acertar um ataque contra um personagem, receba 1 Ponto de Medo."}]', 'img/enemies/enemy_p31_816.png'),
(123, 'Oráculo da Perdição', 4, 'Solo', '', 'Uma imponente criatura imortal que é a encarnação do destino, fadada a ver apenas os piores futuros possíveis.', 'condenar, descartar, desencorajar, mudar local', 20, '38/68', 11, 10, '+8', 'Ataque psíquico: distante', '4d8+9 mág', 'Conhecimento Irrestrito +4', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o oráculo acerta um ataque, todos os personagens Distantes perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Fechar Paredes","type":"Passiva","description":"quando uma criatura muito distante falhar em um teste, ela deve marcar 1 Ponto de Fadiga."},{"name":"Invocar Atormentadores","type":"Ação","description":"uma vez por dia, gaste 2 Pontos de Medo, para invocar 2d4 lacaios de 2º patamar ou menor, relacionados aos pesadelos de um dos personagens. Eles surgem em pontos em alcance próximo do personagem."},{"name":"Prever Destino","type":"Ação","description":"gaste 1 Ponto de Medo para conceder a um alvo distante uma visão de seus pesadelos pessoais. O alvo deve fazer um teste de reação de Conhecimento. Se falhar, o alvo perde todos os Pontos de Esperança e sofre 2d20+4 pontos de dano mágico direto. Se passar, sofre metade do dano e perde 1 Ponto de Esperança."},{"name":"Conhecimento Agourento","type":"Reação","description":"quando o oráculo avista uma criatura mortal, ele imediatamente descobre um dos pesadelos pessoais da criatura."},{"name":"Destino Rancoroso","type":"Reação","description":"quando o oráculo marcar Pontos de Vida por um ataque muito próximo, você pode marcar 1 Ponto de Fadiga para empurrar o atacante para um ponto em alcance distante e causar-lhe 2d10+4 pontos de dano físico."}]', 'img/enemies/enemy_p30_796.png'),
(124, 'Reinos Exteriores, Abominação', 4, 'Brutamonte', '', 'Uma zombaria caótica à própria vida, em fluxo constante.', 'debilitar, demolir, devorar', 19, '35/71', 7, 5, '+2d4', 'Pseudópode gigante: muito próximo', '4d6+13 mág', '', '[{"name":"Forma Caótica","type":"Passiva","description":"quando a abominação ataca, role 2d4 e use o resultado como modificador de ataque."},{"name":"Presença Desconcertante","type":"Passiva","description":"um alvo que sofra dano causado pela abominação deve fazer um teste de reação de Instinto. Se falhar, sofre desvantagem no seu próximo teste e você sofre 1 Ponto de Medo."},{"name":"Abalar Realidade","type":"Ação","description":"gaste 1 Ponto de Medo para abalar as bordas da realidade em alcance distante da abominação. Todos os alvos na área devem passar em um teste de reação de Conhecimento, ou ficam Dissociados da realidade até o fim da cena. Quando um alvo Dissociado gasta Pontos de Esperança ou marca PA, PV ou PF, deve gastar ou marcar o dobro de pontos necessários."},{"name":"Forma Irreal","type":"Reação","description":"quando a abominação sofre dano, reduza-o em 1d20 pontos. Se ela marcar 1 Ponto de Vida ou menos ao ser atingida por 1 ataque, você recebe 1 Ponto de Medo."}]', 'img/enemies/enemy_p30_796.png'),
(125, 'Reinos Exteriores, Corruptor', 4, 'Assistente', '', 'Uma massa amorfa feita de luz cromática.', 'confundir, distrair, subjugar', 19, '27/47', 4, 3, '+7', 'Pseudópode corroído: muito próximo', '4d8+5 mág', '', '[{"name":"Estilhaçar o Âmago","type":"Passiva","description":"um personagem que sofra dano do corruptor perde 1 Ponto de Esperança."},{"name":"Vomitar Realidade","type":"Ação","description":"marque 1 Ponto de Fadiga para vomitar porções parcialmente digeridas de outras realidades em todos os alvos próximos. Alvos precisam passar em um teste de reação de Conhecimento ou devem marcar 2 PF."}]', 'img/enemies/enemy_p30_796.png'),
(126, 'Reinos Exteriores, Servo', 4, 'Lacaio', '', 'Vagamente um humanoide, desprovido de memórias e identidade.', 'destruir, desorientar, enojar, intimidar', 17, 'nenhum', 1, 1, '+3', 'Garras e dentes: muito próximo', '11 fís', '', '[{"name":"Lacaio (13)","type":"Passiva","description":"o servo é derrotado quando sofre qualquer dano. Para cada 13 pontos de dano causados por um personagem ao servo, um lacaio adicional no alcance, e que seria atingido pelo ataque, é derrotado."},{"name":"Ataque em Grupo","type":"Ação","description":"gaste 1 Ponto de Medo para escolher um alvo e pôr em foco todos os servos dos Reinos Exteriores próximos dele. Esses lacaios ficam em alcance corpo a corpo do alvo e fazem um teste de ataque compartilhado. Se acertarem, cada um causa 11 pontos de dano físico. Os danos são somados."}]', 'img/enemies/enemy_p30_796.png'),
(127, 'Serafim Supremo', 4, 'Líder', '', 'Um campeão que lidera tropas sagradas e defende os ideais de um deus.', 'castigar, forçar dogma, julgar, voar', 20, '37/70', 7, 5, '+8', 'Espada sagrada: muito próximo', '4d10+10 fís', 'Conhecimento Divino +3', '[{"name":"Inclemente (3)","type":"Passiva","description":"o serafim pode ser posto em foco até 3 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-lo em foco."},{"name":"Voo Divino","type":"Passiva","description":"enquanto o serafim estiver em voo, gaste 1 Ponto de Medo para movê-lo até um ponto em alcance distante, em vez de próximo, antes dele fazer uma ação."},{"name":"Julgamento","type":"Ação","description":"gaste 1 Ponto de Medo para marcar um alvo como Culpado aos olhos da divindade do serafim até que este seja derrotado. Alvos Culpados não recebem Esperança ao rolar com Esperança. Quando o serafim acerta um ataque padrão contra um alvo Culpado, ele causa dano grave, em vez do dano padrão. O serafim só pode marcar um alvo por vez."},{"name":"Raios Divinos","type":"Ação","description":"marque 1 Ponto de Fadiga para emitir uma fração de divindade através de um raio abrasador de luz que atinge até vinte alvos Muito Distantes. Alvos devem fazer um teste de reação de Presença, com desvantagem se estiverem marcados como Culpados. Quem falhar sofre 4d6+12 pontos de dano mágico. Quem passar sofre metade deste dano."},{"name":"Somos Um","type":"Ação","description":"uma vez por cena, gaste 1 Ponto de Medo para pôr em foco todos os outros adversários Distantes. Ataques feitos por eles por conta desta ação causam metade do dano."}]', 'img/enemies/enemy_p30_796.png'),
(128, 'Zumbi Aperfeiçoado', 4, 'Brutamonte', '', 'Um zumbi imponente e musculoso, aperfeiçoado por magia.', 'agredir, aterrorizar, caçar, consumir', 20, '40/70', 9, 4, '+4', 'Machado grande: muito próximo', '4d12+15 fís', '', '[{"name":"Aterrorizante","type":"Passiva","description":"quando o zumbi acerta um ataque, todos os personagens Distantes perdem 1 Ponto de Esperança. Receba 1 Ponto de Medo."},{"name":"Presença Aterradora","type":"Passiva","description":"personagens não podem gastar Esperança para usar habilidades contra o zumbi."},{"name":"Golpe Perfeito","type":"Ação","description":"marque 1 Ponto de Fadiga para fazer um ataque padrão contra todos os alvos muito próximos. Alvos atingidos ficam Vulneráveis até o próximo descanso."},{"name":"Oportunista","type":"Reação","description":"quando outro adversário causar dano a um alvo muito próximo do zumbi, você pode gastar 1 Ponto de Medo para somar o dano do ataque padrão do zumbi ao dano."}]', 'img/enemies/enemy_p11_376.png'),
(129, 'Legião de Zumbis', 4, 'Horda', '3/PV', 'Um grupo de zumbis, poderosos a despeito da carne putrefata.', 'cercar, consumir cérebros, rasgar carne', 17, '25/45', 8, 5, '+2', 'Mãos Zumbificadas: próximo', '4d6+10 fís', '', '[{"name":"Obstinada","type":"Passiva","description":"a legião tem resistência a dano físico."},{"name":"Horda (2d6+5)","type":"Passiva","description":"quando a legião tiver marcado metade de seus Pontos de Vida ou mais, seu ataque padrão causa 2d6+5 pontos de dano físico, em vez do valor original."},{"name":"Inclemente (2)","type":"Passiva","description":"a legião pode ser posta em foco até 2 vezes por turno do mestre. Gaste Pontos de Medo normalmente para colocá-la em foco."},{"name":"Exceder","type":"Reação","description":"quando a legião marcar PV por causa de um ataque corpo a corpo, você pode marcar 1 Ponto de Fadiga para fazer um ataque padrão contra o atacante."}]', 'img/enemies/enemy_p11_376.png');
