-- ==========================================================================
-- BANCO DE DADOS COMPLETO DAGGERHEART RPG (FICHAS, CARTAS, INIMIGOS E SKILLS)
-- ==========================================================================

CREATE DATABASE IF NOT EXISTS DAGGERHEART CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE DAGGERHEART;

CREATE TABLE IF NOT EXISTS PERSONAGENS (
    ID INT PRIMARY KEY AUTO_INCREMENT NOT NULL,
    NOME VARCHAR(100) NOT NULL,
    CLASSE VARCHAR(50) NOT NULL,
    SUBCLASSE VARCHAR(100) DEFAULT '',
    ANCESTRALIDADE VARCHAR(50) NOT NULL,
    ANCESTRALIDADE_SECUNDARIA VARCHAR(100) DEFAULT '',
    ANCESTRALIDADE_TIPO VARCHAR(50) DEFAULT 'unica',
    COMUNIDADE VARCHAR(50) NOT NULL,
    NIVEL INT NOT NULL DEFAULT 1,
    GENERO VARCHAR(50) DEFAULT '',
    AGILIDADE INT NOT NULL DEFAULT 0,
    FORCA INT NOT NULL DEFAULT 0,
    ACUIDADE INT NOT NULL DEFAULT 0,
    INSTINTO INT NOT NULL DEFAULT 0,
    PRESENCA INT NOT NULL DEFAULT 0,
    CONHECIMENTO INT NOT NULL DEFAULT 0,
    EVASAO INT NOT NULL DEFAULT 10,
    ARMADURA INT NOT NULL DEFAULT 0,
    ARMADURA_SLOTS INT NOT NULL DEFAULT 6,
    ESPERANCA INT NOT NULL DEFAULT 2,
    PV_MAXIMO INT NOT NULL DEFAULT 6,
    PF_MAXIMO INT NOT NULL DEFAULT 6,
    DANO_MENOR INT NOT NULL DEFAULT 1,
    DANO_MAIOR INT NOT NULL DEFAULT 2,
    DANO_GRAVE INT NOT NULL DEFAULT 3,
    EXPERIENCIAS TEXT,
    HABILIDADES_CLASSE TEXT,
    HABILIDADE_SUBCLASSE TEXT,
    HABILIDADE_COMUNIDADE TEXT,
    HABILIDADE_RACA TEXT,
    OURO_PUNHADOS INT NOT NULL DEFAULT 0,
    OURO_BOLSAS INT NOT NULL DEFAULT 0,
    OURO_BAU INT NOT NULL DEFAULT 0,
    ARMA_PRINCIPAL TEXT,
    ARMA_SECUNDARIA TEXT,
    ARMADURA_ATIVA TEXT,
    INVENTARIO TEXT,
    CARTAS_DOMINIO TEXT,
    IMAGEM LONGTEXT
);

DROP TABLE IF EXISTS REGRAS_SISTEMA;
CREATE TABLE REGRAS_SISTEMA (
    ID INT PRIMARY KEY AUTO_INCREMENT NOT NULL,
    CATEGORIA VARCHAR(50) NOT NULL,
    CHAVE VARCHAR(100) NOT NULL,
    DADOS JSON NOT NULL
);

DROP TABLE IF EXISTS CARTAS_DOMINIO;
CREATE TABLE CARTAS_DOMINIO (
    ID INT PRIMARY KEY NOT NULL,
    NOME VARCHAR(150) NOT NULL,
    DOMINIO VARCHAR(50) NOT NULL,
    NIVEL INT NOT NULL DEFAULT 1,
    CUSTO_RETORNO INT NOT NULL DEFAULT 0,
    TIPO VARCHAR(50) NOT NULL,
    DESCRICAO TEXT NOT NULL
);

DROP TABLE IF EXISTS INIMIGOS;
CREATE TABLE INIMIGOS (
    ID INT PRIMARY KEY NOT NULL,
    NOME VARCHAR(150) NOT NULL,
    PATAMAR INT NOT NULL DEFAULT 1,
    PAPEL VARCHAR(50) NOT NULL,
    CONTAGEM_HORDA VARCHAR(50) DEFAULT '',
    DESCRICAO TEXT,
    TATICAS VARCHAR(255) DEFAULT '',
    DIFICULDADE INT NOT NULL DEFAULT 10,
    LIMIARES VARCHAR(50) DEFAULT '',
    PV_MAXIMO INT NOT NULL DEFAULT 1,
    PF_MAXIMO INT NOT NULL DEFAULT 0,
    BONUS_ATAQUE VARCHAR(20) DEFAULT '+0',
    NOME_ATAQUE VARCHAR(150) DEFAULT '',
    DANO_ATAQUE VARCHAR(100) DEFAULT '',
    EXPERIENCIAS VARCHAR(255) DEFAULT '',
    HABILIDADES JSON NOT NULL,
    IMAGEM VARCHAR(255) DEFAULT ''
);

